window.__LIBQ=window.__LIBQ||{};window.__LIBQ["the-gioi-hoan-my"]=window.__LIBQ["the-gioi-hoan-my"]||{};window.__LIBQ["the-gioi-hoan-my"]["q06"]=window.__LIBQ["the-gioi-hoan-my"]["q06"]||{};window.__LIBQ["the-gioi-hoan-my"]["q06"]["artifacts"]={"updatedAt":"2026-07-26","count":174,"artifacts":[{"id":"dien-co-bang-dong-xanh","name":"Điện cổ bằng đồng xanh","cn":"","category":"khac","categoryLabel":"Cổ điện","phamCap":"Chưa rõ","soHuu":["Bất Lão Sơn"],"trangThai":"Nguyên vẹn","blurb":"Cổ điện bằng đồng xanh nằm trên một ngọn núi thuộc Ngũ Hành Sơn, không hư hao trong biến động dữ dội.","detail":"Khi cường giả thượng giới tìm cách giáng lâm, lớp gỉ xanh trên cổ điện bong ra và toàn bộ công trình phát sáng như bảo ngọc. Tiểu Tháp nhận định ngôi điện đồng này bất diệt.","nguon":["@c0501"]},{"id":"te-dan-phong-an-sinh-linh-bat-diet","name":"Tế đàn phong ấn sinh linh bất diệt","cn":"","category":"khac","categoryLabel":"Tế đàn","phamCap":"Chưa rõ","soHuu":["Bất Lão Sơn"],"trangThai":"Đã bị phá hủy","blurb":"Tế đàn từng phối hợp với xích thần Ngũ hành để giam giữ sinh linh bất diệt qua vô tận năm tháng.","detail":"Sinh linh bất diệt không tiếc đại giá vận dụng bí pháp làm nổ tung tế đàn, phá hủy một bộ phận trọng yếu của phong ấn và tiến gần hơn tới việc thoát khốn.","nguon":["@c0501"]},{"id":"te-dan-chi-ton-cua-tan-hao","name":"Tế đàn Chí Tôn của Tần Hạo","cn":"","category":"khac","categoryLabel":"Tế đàn","phamCap":"Chưa rõ","soHuu":["Tần Hạo"],"trangThai":"Đã được Tiểu Tháp thu vào trong tháp","blurb":"Tế đàn tỏa ra khí tức Chí Tôn, cộng hưởng trực tiếp với Tần Hạo bằng các xích thần trật tự.","detail":"Tế đàn hiện ra dị tượng rồng gầm và Thần Hoàng niết bàn, đồng thời buông xuống từng luồng xích thần trật tự nối với vị trí của Tần Hạo. Sau đó, Tiểu Tháp thu cả tế đàn, Tần Hạo và vợ chồng Thạch Tử Lăng vào bên trong tháp.","nguon":["@c0501"]},{"id":"dong-phu-bao-kho-bat-lao-son","name":"Động phủ bảo khố Bất Lão Sơn","cn":"","category":"khac","categoryLabel":"Kho vật phẩm","phamCap":"Chưa rõ","soHuu":["Bất Lão Sơn"],"trangThai":"Đã bị đột nhập","blurb":"Động phủ cất giữ số lượng lớn thần liệu và thần vật của Bất Lão Sơn.","detail":"Tiểu Tháp dùng kiếm khí hỗn độn phá cấm chế cùng cửa đá của động phủ. Bên trong chất đầy bảo vật, thần liệu và thần vật, tỏa ra bảo quang cùng những đợt sóng thần lực mạnh mẽ.","nguon":["@c0501"]},{"id":"khoi-tan-cot-nho","name":"Khối tàn cốt nhỏ","cn":"","category":"nguyen-lieu","categoryLabel":"Vật phẩm chưa rõ","phamCap":"Chưa rõ","soHuu":["Thạch Hạo"],"trangThai":"Đã được Thạch Hạo nhặt lấy","blurb":"Khối tàn cốt nhỏ nằm khuất trong một góc kho báu, có bề ngoài trắng bóng và trơn nhẵn.","detail":"Vật này không nổi bật bằng các thần liệu xung quanh, nhưng khi phát hiện ra nó, Thạch Hạo lập tức kinh hãi, bước nhanh tới và nhặt vào tay. Lai lịch cùng công dụng của khối tàn cốt chưa được làm rõ.","nguon":["@c0501"]},{"id":"dat-hon-don","name":"Đất Hỗn độn","cn":"","category":"nguyen-lieu","categoryLabel":"Thần liệu","phamCap":"Thần liệu","soHuu":["Tiểu Tháp"],"trangThai":"Đã bị Tiểu Tháp nuốt","blurb":"Thần liệu mang dấu ấn của thời đại hỗn độn, có thể dùng để chế tạo bảo cụ vô thượng.","detail":"Một đống lớn Đất Hỗn độn được cất giữ trong bảo khố Bất Lão Sơn. Tiểu Tháp thu lấy và nuốt số thần liệu này để phục hồi những dấu tích chiến đấu trên thân tháp.","nguon":["@c0502"]},{"id":"buc-tranh-bo-sung-tinh-khi","name":"Bức tranh bổ sung tinh khí","cn":"","category":"phap-bao","categoryLabel":"Pháp khí","phamCap":"Không nêu","soHuu":["Bất Lão Thiên tôn"],"trangThai":"Đang được sử dụng","blurb":"Bức tranh lờ mờ treo trên đầu Bất Lão Thiên tôn, liên tục bổ sung phần tinh khí đã tiêu tán.","detail":"Pháp khí này giúp hình chiếu của Bất Lão Thiên tôn duy trì lâu hơn dự liệu trong cuộc giao chiến và truy kích sinh linh bất diệt.","nguon":["@c0502"]},{"id":"cay-ngu-nguyen","name":"Cây Ngũ nguyên","cn":"","category":"dan-duoc","categoryLabel":"Thánh dược","phamCap":"Thánh dược","soHuu":["Thạch Hạo"],"trangThai":"Gần chết nhưng vẫn còn sống","blurb":"Cây thánh dược năm lá bị sinh linh bất diệt hút mất phần lớn tinh hoa nhưng vẫn giữ được sức sống mạnh mẽ.","detail":"Cây Ngũ nguyên được trồng trong đất Ngũ hành tại một khu vực có trận pháp thần linh che giấu. Thạch Hạo mang cả cây lẫn chậu đi; cây có khả năng lột xác thành thần vật mang thần tính vô lượng nếu được đưa lên thượng giới.","nguon":["@c0502"]},{"id":"dat-ngu-hanh","name":"Đất Ngũ hành","cn":"","category":"nguyen-lieu","categoryLabel":"Thần thổ","phamCap":"Không nêu","soHuu":["Thạch Hạo"],"trangThai":"Được mang khỏi Bất Lão Sơn","blurb":"Thần thổ lấy từ Ngũ Hành Sơn, có khả năng nuôi trồng thần vật.","detail":"Đất Ngũ hành được chứa trong những chậu đá năm màu và dùng để trồng cây Ngũ nguyên. Tiểu Tháp không nuốt số đất này, để Thạch Hạo mang cả chậu và thánh dược đi.","nguon":["@c0502"]},{"id":"khuc-tre-cua-truong-luc-kim-than","name":"Khúc tre của Trượng lục kim thân","cn":"","category":"phap-bao","categoryLabel":"Pháp khí","phamCap":"Không nêu","soHuu":["Trượng Lục"],"trangThai":"Đang được sử dụng","blurb":"Khúc tre óng ánh như ngọc bích được Trượng lục kim thân sử dụng khi tham gia chiến trường.","detail":"Hình chiếu của Tây Phương giáo dùng khúc tre điểm thẳng vào thân Tiểu Tháp, đánh nó ngã nhào trong lúc các cường giả truy kích sinh linh bất diệt.","nguon":["@c0502"]},{"id":"kinh-thien-an","name":"Kình thiên ấn","cn":"","category":"phap-bao","categoryLabel":"Pháp bảo","phamCap":"Chưa rõ","soHuu":["Bất lão Thiên tôn"],"trangThai":"Đang được sử dụng","blurb":"Pháp bảo được Bất lão Thiên tôn vận dụng bằng pháp lực kinh thế để chặn kiếm hồng đang bổ tới.","detail":"Kình thiên ấn có thể đón chặn và phá giải đòn kiếm bị chuyển hướng về phía Bất lão Thiên tôn.","nguon":["@c0503"]},{"id":"xa-loi-cua-tay-phuong-giao","name":"Xá lợi của Tây Phương giáo","cn":"","category":"khac","categoryLabel":"Vật phẩm","phamCap":"Chưa rõ","soHuu":[],"trangThai":"Từng bị Tiểu Tháp cướp lấy","blurb":"Một viên xá lợi vô cùng trọng yếu của Tây Phương giáo, từng bị Tiểu Tháp cướp để chữa trị tổn thương.","detail":"Sau đại chiến với thượng giới, Tiểu Tháp bị tổn hại nghiêm trọng nên lấy viên xá lợi này để chữa trị bản thân. Sự việc trở thành nguyên nhân khiến Tây Phương giáo truy sát Tiểu Tháp.","nguon":["@c0503"]},{"id":"dia-vang-sau-dau-tay-phuong-giao-chu","name":"Đĩa vàng sau đầu Tây Phương giáo chủ","cn":"","category":"phap-bao","categoryLabel":"Pháp bảo","phamCap":"Chưa rõ","soHuu":["Tây Phương giáo chủ"],"trangThai":"Đang được sử dụng","blurb":"Một đĩa vàng rất lớn hiện ra sau đầu Tây Phương giáo chủ, trông giống mặt trời.","detail":"Đĩa vàng xuất hiện phía sau đầu Tây Phương giáo chủ và trực tiếp ngăn cản khi thân Tiểu Tháp ép xuống.","nguon":["@c0503"]},{"id":"tran-do-cua-bat-lao-thien-ton","name":"Trận đồ của Bất lão Thiên tôn","cn":"","category":"phap-bao","categoryLabel":"Bí bảo","phamCap":"Không rõ","soHuu":["Bất lão Thiên tôn"],"trangThai":"Bị đánh nát","blurb":"Bí bảo duy trì hình chiếu của Bất lão Thiên tôn tại hạ giới, ngăn tinh khí thần của hình chiếu tiêu tan.","detail":"Trận đồ bị cành liễu xuyên thủng, các mảnh vỡ bay tứ tung và không còn giữ được tinh khí thần, khiến hình chiếu của Bất lão Thiên tôn trở nên bất ổn rồi dần tiêu tan.","nguon":["@c0504"]},{"id":"tien-kiem-cua-cuong-gia-cuoi-trau","name":"Tiên kiếm của cường giả cưỡi trâu","cn":"","category":"phap-bao","categoryLabel":"Binh khí","phamCap":"Không rõ","soHuu":["Cường giả vô thượng cưỡi trâu"],"trangThai":"Bị đánh văng","blurb":"Tiên kiếm có thể tự động rút khỏi vỏ, phát ra thần quang và sát khí để công phạt.","detail":"Tiên kiếm được dùng để đối đầu cành liễu của Liễu Thần. Trong đại chiến, Liễu Thần dùng một ngón tay va chạm với mũi kiếm, làm thần năng vô thượng bùng phát và đánh văng thanh kiếm ra xa.","nguon":["@c0504"]},{"id":"dien-dong-bat-lao-son","name":"Điện đồng Bất Lão sơn","cn":"","category":"khac","categoryLabel":"Cung điện truyền giới","phamCap":"","soHuu":["Bất Lão sơn"],"trangThai":"Trận pháp bên trong đã nổ tung","blurb":"Cung điện bằng đồng của Bất Lão sơn có lối thông tới thượng giới.","detail":"Ngũ Hành sơn hóa thành một luồng khí bản nguyên rồi tiến vào điện đồng để rời khỏi tám vực. Sau khi nó biến mất, trận pháp bên trong nổ tung, cung điện rung chuyển và lưu lại dao động nguyên khí mạnh.","nguon":["@c0506"]},{"id":"con-mat-trung-dong","name":"Con mắt Trùng đồng","cn":"","category":"khac","categoryLabel":"Thần nhãn","phamCap":"","soHuu":["Thạch Hạo"],"trangThai":"Đang được Thạch Hạo sử dụng","blurb":"Thần nhãn được Thạch Hạo dùng để dò xét bản thể và hình dáng của Sinh linh bất diệt.","detail":"Con mắt chỉ nhìn thấy một vùng thần quang vàng chói mà không thể nhìn thấu bản thể đối phương. Sức mạnh phát ra còn khiến thần thức của Thạch Hạo bị thiêu đốt và đau nhói.","nguon":["@c0506"]},{"id":"dia-hoa-dich","name":"Địa hỏa dịch","cn":"","category":"nguyen-lieu","categoryLabel":"Linh dịch","phamCap":"Linh dịch hệ Hỏa","soHuu":[],"trangThai":"Tồn tại trong tám linh trì gần thành trì Hỏa nha","blurb":"Linh dịch hệ Hỏa ẩn trong dung nham, chứa lượng thần năng dồi dào có thể tẩm bổ Chí tôn cốt.","detail":"Tám linh trì Địa hỏa dịch nằm gần thành trì Hỏa nha. Tuy không phải thần dịch đỉnh cấp, số lượng linh dịch rất lớn và thần năng bên trong khiến Chí tôn cốt của Thạch Hạo sinh phản ứng, muốn hấp thu để tiếp tục tiến hóa.","nguon":["@c0507"]},{"id":"thach-nhu-van-nam","name":"Thạch nhũ vạn năm","cn":"","category":"nguyen-lieu","categoryLabel":"Linh dịch","phamCap":"Tích lũy vạn năm","soHuu":["Thạch Hạo"],"trangThai":"Tinh hoa trong ao đã được hấp thu hết","blurb":"Thạch nhũ tích tụ suốt vạn năm trong một động phủ bỏ hoang, ẩn chứa tinh hoa linh tính mạnh mẽ.","detail":"Thạch Hạo tìm thấy một ao thạch nhũ trong động phủ bỏ hoang rồi uống và hấp thu toàn bộ. Phần lớn tinh hoa tiến vào vùng ngực, tẩm bổ Chí tôn cốt và giúp các phù văn của bảo thuật bản mệnh hiện rõ hơn.","nguon":["@c0507"]},{"id":"thuyen-co-tren-bien-kim-o","name":"Thuyền cổ trên biển Kim Ô","cn":"","category":"khac","categoryLabel":"Thuyền cổ","phamCap":"Chưa rõ","soHuu":[],"trangThai":"Đang lướt trên biển Kim Ô","blurb":"Chiếc thuyền cổ bí ẩn có thể di chuyển trên biển dung nham bị quy tắc cấm không bao phủ.","detail":"Thuyền xuất hiện khi tổ địa Kim Ô được giải phong và lướt trên biển dung nham rộng vô tận. Chủ nhân, công dụng và phương thức giúp nó tồn tại trong khu vực đủ sức uy hiếp Tôn giả chưa được hé lộ.","nguon":["@c0507"]},{"id":"than-thu-thai-duong","name":"Thần thụ Thái dương","cn":"","category":"khac","categoryLabel":"Thần thụ","phamCap":"Di tích thần thoại","soHuu":[],"trangThai":"Hiện ra trong dị tượng tại biển Kim Ô","blurb":"Thần thụ màu vàng khổng lồ cắm rễ giữa biển Kim Ô, có nhật nguyệt tinh thần vờn quanh.","detail":"Thần lực sâu trong biển Kim Ô hóa thành hình ảnh một cây cổ thụ che trời, toàn thân vàng óng và được nhật nguyệt tinh thần bao quanh. Dị tượng này gắn với di tích thuộc thời đại thần thoại khởi nguyên và khiến những kỳ tài thượng giới chấn động.","nguon":["@c0507"]},{"id":"cung-dien-bat-hu-trong-bien-kim-o","name":"Cung điện bất hủ trong biển Kim Ô","cn":"","category":"khac","categoryLabel":"Cung điện","phamCap":"Di tích thần thoại","soHuu":[],"trangThai":"Ẩn hiện trong dị tượng tại biển Kim Ô","blurb":"Tòa cung điện khổng lồ tỏa hào quang bất hủ, xuất hiện bên cạnh Thần thụ Thái dương trong biển Kim Ô.","detail":"Cung điện hiện ra khi thần lực trong biển Kim Ô tái hiện cảnh tượng cổ xưa. Sự xuất hiện của nó cùng Thần thụ Thái dương khiến các kỳ tài thượng giới nhận định di tích của thời đại thần thoại khởi nguyên đã tái hiện.","nguon":["@c0507"]},{"id":"khoi-than-cot-cua-ngan-su","name":"Khối thần cốt của Ngân sư","cn":"","category":"nguyen-lieu","categoryLabel":"Thần cốt","phamCap":"Không rõ","soHuu":["Ngân sư"],"trangThai":"Nguyên vẹn","blurb":"Khối thần cốt không bị hư hao khi tiếp xúc với biển dung nham, được Ngân sư dùng làm phương tiện vượt biển.","detail":"Ngân sư cùng hai người khác đứng trên khối thần cốt để phá biển tiến về phía thần thụ. Vật này chịu được sức nóng có thể nung chảy pháp khí thông thường của biển dung nham.","nguon":["@c0508"]},{"id":"phap-truong-to-khi-toc-thiet-huyet","name":"Pháp trượng tổ khí tộc Thiết huyết","cn":"","category":"than-khi","categoryLabel":"Tổ khí","phamCap":"Không rõ","soHuu":["Cổ thụ Thiết huyết"],"trangThai":"Đang được sử dụng","blurb":"Tổ khí màu đỏ đậm của tộc Thiết huyết, có thể phóng lớn để chở Cổ thụ Thiết huyết vượt biển dung nham.","detail":"Sau khi một phần rễ bị biển lửa đốt cháy đen, Cổ thụ Thiết huyết lấy pháp trượng ra làm phương tiện. Pháp trượng đỏ đậm trong suốt, lưu chuyển thần hà và khi phóng lớn trông như một khúc gỗ khổng lồ.","nguon":["@c0508"]},{"id":"ba-bao-thuyen-than-linh","name":"Ba bảo thuyền thần linh","cn":"","category":"phap-bao","categoryLabel":"Pháp khí thần linh","phamCap":"Cấp thần linh","soHuu":[],"trangThai":"Đang được sử dụng","blurb":"Ba pháp khí thần linh hóa thành thuyền, chở nhóm kỳ tài thượng giới vượt qua biển dung nham.","detail":"Các bảo thuyền tỏa ráng lành để bảo vệ những người ngồi trên và duy trì đội hình khi tiến vào biển đỏ. Một thuyền chở Thạch Hạo, Lam Vũ, Thủy Nguyệt, Hồng Hoàng cùng hai kỳ tài khác.","nguon":["@c0508"]},{"id":"thuyen-xuong-kim-o","name":"Thuyền xương Kim ô","cn":"","category":"phap-bao","categoryLabel":"Pháp khí dạng thuyền","phamCap":"Không rõ","soHuu":["Tộc Kim ô"],"trangThai":"Đang được sử dụng","blurb":"Chiếc thuyền luyện từ xương Kim ô, có ưu thế tự nhiên khi di chuyển trong biển lửa.","detail":"Thuyền có thể xé sóng dung nham và lao đi với tốc độ lớn. Nó từng áp sát để cảnh cáo nhóm kỳ tài thượng giới, tạo ra sóng nóng suýt lật ba bảo thuyền thần linh.","nguon":["@c0508"]},{"id":"cau-da-cua-tuyen-minh","name":"Cầu đá của Tuyên Minh","cn":"","category":"phap-bao","categoryLabel":"Bí bảo không gian","phamCap":"Không rõ","soHuu":["Tuyên Minh"],"trangThai":"Đang được sử dụng","blurb":"Bí bảo hình cầu đá nhỏ có thể mở một con đường xuyên qua hư không ngay trong khu vực cấm không.","detail":"Khi được Tuyên Minh vận dụng, cây cầu đá hóa thành một luồng cầu vồng nối tới nơi sâu nhất của biển lửa. Ba bảo thuyền đi dọc theo cây cầu và thoát khỏi vòng vây của thuyền ma cùng vô số bạch cốt.","nguon":["@c0508"]},{"id":"chuong-dong-cua-lam-long","name":"Chuông đồng của Lam Long","cn":"","category":"than-khi","categoryLabel":"Thần khí","phamCap":"Không rõ","soHuu":["Lam Long"],"trangThai":"Đang được sử dụng","blurb":"Thần khí lơ lửng trên đầu Lam Long, có khả năng gia trì bảo thuật.","detail":"Tiếng chuông giúp bảo thuật của Lam Long hợp nhất và tăng uy lực lên nhiều lần, tạo thành đòn công kích mạnh vào đoàn thiên tài thượng giới.","nguon":["@c0509"]},{"id":"than-hoan-chin-mau","name":"Thần hoàn chín màu","cn":"","category":"phap-bao","categoryLabel":"Pháp bảo","phamCap":"Bí bảo","soHuu":["Rắn chín đầu"],"trangThai":"Đang được sử dụng","blurb":"Bí bảo chín màu do Rắn chín đầu điều khiển, từng được Thần linh tế luyện.","detail":"Thần hoàn có uy năng mạnh, phối hợp với thần mang từ chín đầu của Rắn chín đầu để ép nhiều thiên tài thượng giới phải lui lại.","nguon":["@c0509"]},{"id":"bao-cu-sung-huou","name":"Bảo cụ sừng hươu","cn":"","category":"phap-bao","categoryLabel":"Pháp bảo","phamCap":"Bảo cụ","soHuu":["Hươu chín màu"],"trangThai":"Đang được sử dụng","blurb":"Bảo cụ chế từ sừng hươu, lưu chuyển ánh sáng năm màu và được dùng để công kích trực diện.","detail":"Hươu chín màu dùng bảo cụ này đánh Thạch Hạo, nhưng kiếm khí của cậu khiến nó chệch quỹ đạo và lao xuống biển dung nham.","nguon":["@c0509"]},{"id":"hon-da-tieu-the-gioi-hu-hao","name":"Hòn đá tiểu thế giới hư hao","cn":"","category":"khac","categoryLabel":"Vật phẩm không gian","phamCap":"Không rõ","soHuu":["Oánh Oánh"],"trangThai":"Đã hư hao","blurb":"Hòn đá lấp lánh đã vỡ một phần, bên trong chứa một tiểu thế giới hư hao.","detail":"Oánh Oánh lấy vật này ra để cung cấp sức mạnh tiểu thế giới, phối hợp mở cấm chế hoàng kim quanh cây Thái dương.","nguon":["@c0509"]},{"id":"tinh-hoa-do-re-hoang-kim-luyen-hoa","name":"Tinh hoa do rễ hoàng kim luyện hóa","cn":"","category":"nguyen-lieu","categoryLabel":"Linh dịch","phamCap":"Gần đạt thần dịch","soHuu":["Thạch Hạo"],"trangThai":"Đã được hấp thu","blurb":"Linh dịch hiếm có do rễ hoàng kim luyện hóa từ địa hỏa dịch, có hiệu quả vượt xa phần linh dịch thông thường.","detail":"Chất lỏng đỏ đậm phát ra hào quang bất hủ, xuất hiện với số lượng ít bên cạnh các rễ hoàng kim. Tuy chưa phải thần dịch, tinh hoa này đã giúp Chí tôn cốt của Thạch Hạo vượt qua điểm then chốt trong quá trình tái sinh.","nguon":["@c0510"]},{"id":"hop-bau-dong-thau","name":"Hộp báu đồng thau","cn":"","category":"phap-bao","categoryLabel":"Pháp bảo không gian","phamCap":"Chưa rõ","soHuu":["Thạch Hạo"],"trangThai":"Đang được sử dụng","blurb":"Pháp bảo không gian có Thế giới hộp báu bên trong, có thể chứa người và thu giữ linh dịch nóng rực.","detail":"Thạch Hạo từng để Nguyệt Thiền trong hộp. Tại biển dung nham, nó đưa nàng ra ngoài rồi dùng không gian bên trong hộp thu một lượng lớn địa hỏa dịch; dung lượng tuy hữu hạn nhưng phù hợp để chứa loại linh dịch quá nóng này.","nguon":["@c0511"]},{"id":"sung-huou-nam-mau","name":"Sừng hươu năm màu","cn":"","category":"linh-khi","categoryLabel":"Pháp khí","phamCap":"Mang uy lực cấp Tôn giả","soHuu":["Hươu năm màu"],"trangThai":"Đã rạn nứt","blurb":"Pháp khí được Hươu năm màu dùng để đánh lén Thạch Hạo, có thể phóng ra thác sáng năm màu.","detail":"Sừng hươu mang uy lực cấp Tôn giả, được sử dụng trong trận chiến trên Hoàng kim thụ. Khi đối đầu vòng phù văn hộ thể của Thạch Hạo, pháp khí này bắt đầu rạn nứt.","nguon":["@c0511"]},{"id":"nui-the-gioi","name":"Núi Thế giới","cn":"","category":"nguyen-lieu","categoryLabel":"Nguyên liệu","phamCap":"Phôi thô chí bảo Hỗn độn","soHuu":[],"trangThai":"Bất hủ, chưa được luyện hóa","blurb":"Vật liệu sinh ra khi khai thiên, mang pháp tắc bản nguyên thiên địa và có thể được luyện thành chí bảo Hỗn độn.","detail":"Núi Thế giới có màu nâu đen, lơ lửng phía trên Hoàng kim thụ và được sương mù Hỗn độn bao phủ. Ngọn núi cực kỳ nặng và cứng, đến thần khí cũng khó làm tổn hại; nếu được luyện hóa, khắc Đạo và tế thành binh khí thì có thể trở thành chí bảo có sức phá hoại một giới.","nguon":["@c0512"]},{"id":"than-hoa-thai-duong","name":"Thần hoa Thái dương","cn":"","category":"nguyen-lieu","categoryLabel":"Nguyên liệu","phamCap":"Thần hoa","soHuu":[],"trangThai":"Đang sinh trưởng trên Thái dương thụ","blurb":"Đóa thần hoa vàng óng có thể sinh bảo dịch và tiếp tục phát triển thành Quả thế giới.","detail":"Thần hoa mọc trên một nhánh Thái dương thụ gần đỉnh Núi Thế giới. Hoa chịu ảnh hưởng từ pháp tắc của ngọn núi, có thể tự phóng xích thần trật tự để phá hủy pháp khí, chặt đứt sừng hươu năm màu và xuyên thủng Tôn giả; trong chương, hoa tiết ra ba giọt bảo dịch hoàng kim.","nguon":["@c0512"]},{"id":"bao-dich-hoang-kim","name":"Bảo dịch hoàng kim","cn":"","category":"nguyen-lieu","categoryLabel":"Nguyên liệu","phamCap":"Thần dịch","soHuu":["Thạch Hạo"],"trangThai":"Ba giọt đã bị Thạch Hạo đoạt lấy","blurb":"Chất lỏng vàng thơm ngát do Thần hoa Thái dương tiết ra, khiến kỳ tài thượng giới và các Tôn giả tranh đoạt quyết liệt.","detail":"Ba giọt bảo dịch chảy ra từ Thần hoa Thái dương và rơi vào một ngọc đỉnh giữa lúc các phe hỗn chiến. Thạch Hạo xông qua chiến trường, va Người khổng lồ hoàng kim lảo đảo rồi cướp lấy ngọc đỉnh chứa trọn ba giọt.","nguon":["@c0512"]},{"id":"ngoc-dinh-chua-hoang-kim-dich","name":"Ngọc đỉnh chứa hoàng kim dịch","cn":"","category":"khac","categoryLabel":"Vật chứa thần dịch","phamCap":"","soHuu":["Thạch Hạo"],"trangThai":"Được Thạch Hạo cất giữ","blurb":"Một ngọc đỉnh trắng noãn nhỏ bằng nắm tay, dùng để chứa ba giọt hoàng kim dịch.","detail":"Thạch Hạo đoạt được ngọc đỉnh giữa cuộc tranh giành trên núi Thế giới, lập tức đậy nắp và cất đi để hương thơm của thần dịch không phát tán. Bên trong đỉnh có ba giọt hoàng kim dịch đang lăn tròn.","nguon":["@c0513"]},{"id":"than-dich-thai-duong","name":"Thần dịch Thái dương","cn":"","category":"dan-duoc","categoryLabel":"Thần dịch","phamCap":"","soHuu":["Thạch Hạo"],"trangThai":"Ba giọt được cất trong ngọc đỉnh","blurb":"Ba giọt dịch vàng có hương thơm mãnh liệt, đủ khiến các Tôn giả tranh đoạt và đánh giết lẫn nhau.","detail":"Thần dịch tỏa hương khiến người ngửi cảm thấy nhẹ nhàng như sắp vũ hóa phi thăng. Thạch Hạo giành được cả ba giọt rồi niêm kín chúng trong ngọc đỉnh để tránh thất thoát hương thơm.","nguon":["@c0513"]},{"id":"qua-trung-trong-hoa-thai-duong","name":"Quả trứng trong hoa Thái dương","cn":"","category":"khac","categoryLabel":"Vật thể thai nghén sinh linh","phamCap":"","soHuu":[],"trangThai":"Đang hấp thu thần dịch và tinh hoa thần dược","blurb":"Một quả trứng óng ánh gần như trong suốt xuất hiện khi hoa Thái dương nở, bên trong chứa một cô gái tóc vàng.","detail":"Quả trứng liên tục hút chất lỏng vàng cùng tinh hoa thần dược từ hoa Thái dương. Lớp vỏ gần như trong suốt để lộ sinh linh hình người đang nhắm mắt và tỏa ánh vàng bên trong.","nguon":["@c0513"]},{"id":"than-dich-hoang-kim","name":"Thần dịch hoàng kim","cn":"","category":"khac","categoryLabel":"Thần dịch","phamCap":"Vô giá","soHuu":["Thạch Hạo"],"trangThai":"Thạch Hạo giữ ba giọt","blurb":"Thần dịch hoàng kim có khả năng giúp người chết sống lại và được xem là thần dịch vô giá.","detail":"Thạch Hạo nắm giữ ba giọt thần dịch hoàng kim. Triệu Khải và Trác Vân từng yêu cầu hắn giao hai giọt để những người trong cùng trận doanh dùng hộ mệnh, nhưng hắn từ chối.","nguon":["@c0514"]},{"id":"phap-kiem-mau-vang","name":"Pháp kiếm màu vàng","cn":"","category":"phap-bao","categoryLabel":"Pháp kiếm","phamCap":"Chưa xác định","soHuu":["Thạch Hạo"],"trangThai":"Đang được sử dụng","blurb":"Pháp kiếm màu vàng là binh khí được Thạch Hạo sử dụng trong cuộc giao chiến với Trác Vân và ba đồng bạn.","detail":"Thạch Hạo rút pháp kiếm màu vàng khi giao chiến, phối hợp với Chí tôn cốt để nhanh chóng áp đảo đối phương. Sau khi Trác Vân bị Luân hồi làm suy yếu, pháp kiếm được dùng để chém đứt đầu hắn.","nguon":["@c0514"]},{"id":"hai-quyen-cot-thu-hon-don","name":"Hai quyển cốt thư Hỗn Độn","cn":"","category":"khac","categoryLabel":"Kinh thư","phamCap":"Kinh thư vô thượng","soHuu":[],"trangThai":"Chưa thể tiếp cận","blurb":"Hai quyển cốt thư cổ xưa tỏa ra khí hỗn độn, được đặt trên bàn đá và giá sách đá trong cung điện Hỗn Độn.","detail":"Một quyển cốt thư nằm trên bàn đá, quyển còn lại nằm trên giá sách đá. Nhóm trẻ tuổi nhận định đây là kinh thư vô thượng, nhưng lực lượng bao quanh đã đánh bật những người thử tiếp cận.","nguon":["@c0514"]},{"id":"doan-mau-bang-xuong-hu-khong-thu","name":"Đoản mâu bằng xương Hư không thú","cn":"","category":"phap-bao","categoryLabel":"Pháp bảo","phamCap":"Bí bảo","soHuu":["Thanh niên tóc tím","Thạch Hạo"],"trangThai":"Đã bị phá hủy","blurb":"Bí bảo bằng xương Hư không thú, có khả năng hỗ trợ người sử dụng ẩn mình và di chuyển trong hư không.","detail":"Thanh niên tóc tím dùng đoản mâu để ẩn trong hư không và ám sát Thạch Hạo. Sau khi chủ nhân bị chém đầu, Thạch Hạo đoạt lấy nó nhưng nhanh chóng phát hiện bí bảo đang bốc cháy và nứt vỡ; khi Kim lang chụp được, đoản mâu phát nổ, tạo thành một cơn bão năng lượng và khiến Kim lang trọng thương.","nguon":["@c0516"]},{"id":"than-son-thai-co-mau-vang","name":"Thần sơn thái cổ màu vàng","cn":"","category":"phap-bao","categoryLabel":"Pháp khí thần linh","phamCap":"Thần linh","soHuu":["Người khổng lồ hoàng kim"],"trangThai":"Đang được sử dụng","blurb":"Một tòa Thần sơn thái cổ do tổ tiên Người khổng lồ hoàng kim luyện hóa, có thể phóng lớn để trấn áp đối thủ.","detail":"Pháp khí này được Người khổng lồ hoàng kim dùng để công kích Thạch Hạo và đánh Rắn chín đầu hộc máu trong cuộc tranh đoạt cốt thư.","nguon":["@c0517"]},{"id":"luc-lac-cua-lam-long","name":"Lục lạc của Lam long","cn":"","category":"phap-bao","categoryLabel":"Pháp khí thần hồn","phamCap":"Chưa rõ","soHuu":["Lam long"],"trangThai":"Nứt vỡ sau khi chống lại lực Luân hồi","blurb":"Lục lạc có thể phóng lớn như chuông; tiếng rung của nó khiến thần hồn đối phương muốn rời khỏi thân thể.","detail":"Lam long dùng lục lạc ép nguyên thần Thạch Hạo thoát xác. Khi đối đầu lực Luân hồi, pháp khí bị đánh văng và xuất hiện dày đặc vết nứt.","nguon":["@c0517"]},{"id":"luoi-sao-troi-cua-thuy-nguyet","name":"Lưới sao trời của Thủy Nguyệt","cn":"","category":"phap-bao","categoryLabel":"Bí bảo","phamCap":"Chưa rõ","soHuu":["Thủy Nguyệt"],"trangThai":"Đang được sử dụng","blurb":"Một tấm lưới lớn lấp lánh như sao trời, có khả năng trói buộc cả cường giả cấp Tôn giả.","detail":"Thủy Nguyệt phủ lưới xuống Rắn chín đầu, giữ chặt đối phương và khiến nó nhất thời không thể thoát ra trong cuộc tranh đoạt cốt thư.","nguon":["@c0517"]},{"id":"bao-phien-do-tham","name":"Bảo phiến đỏ thẫm","cn":"","category":"phap-bao","categoryLabel":"Pháp khí","phamCap":"Chưa rõ","soHuu":["Hồng Hoàng"],"trangThai":"Đang được sử dụng","blurb":"Cây bảo phiến màu đỏ thẫm có thể tạo ra cuồng phong và ánh lửa mang thần năng mạnh mẽ.","detail":"Hồng Hoàng dùng bảo phiến đánh Kiến tử kim lăn ra ngoài. Xung kích từ đòn đánh cũng khiến Tuyên Minh mất thăng bằng và rơi khỏi cầu đá.","nguon":["@c0517"]},{"id":"bua-nho-mau-tim","name":"Búa nhỏ màu tím","cn":"","category":"phap-bao","categoryLabel":"Pháp khí","phamCap":"Chưa rõ","soHuu":["Kiến tử kim"],"trangThai":"Đang được sử dụng","blurb":"Một chiếc búa nhỏ màu tím được Kiến tử kim phun ra trong cuộc tranh đoạt cốt thư thứ hai.","detail":"Pháp khí được dùng để đánh vỡ màn ánh sáng bảo vệ cây cầu đá khi Tuyên Minh đang tiếp cận cốt thư.","nguon":["@c0517"]},{"id":"cot-thu-thu-hai","name":"Cốt thư thứ hai","cn":"","category":"khac","categoryLabel":"Cổ kinh","phamCap":"Chưa xác định","soHuu":["Thạch Hạo"],"trangThai":"Đã bị Thạch Hạo đoạt đi","blurb":"Cốt thư được trận pháp nâng khỏi giá sách đá sau khi hấp thu tinh huyết của các cường giả.","detail":"Cốt thư lần lượt tuột khỏi tay Tuyên Minh, bị Lam long ngậm lấy rồi bị Thạch Hạo đoạt đi. Thạch Hạo nghi ngờ vật này ghi thiên “Siêu thoát” của Nguyên thủy chân giải, nhưng nội dung chưa được xác nhận.","nguon":["@c0517"]},{"id":"bo-doan-tren-dao-dai","name":"Bồ đoàn trên đạo đài","cn":"","category":"khac","categoryLabel":"Kỳ vật","phamCap":"Chưa rõ","soHuu":[],"trangThai":"Lơ lửng trong cổ điện Hỗn độn","blurb":"Chiếc bồ đoàn trên đạo đài phát sáng, hiện ra một bóng người mang khí tức vô thượng và thu hồi cốt thư.","detail":"Khi cốt thư sắp bị mang khỏi cổ điện, bồ đoàn đột ngột sáng rực và hiện lên một bóng người nhàn nhạt. Lực lượng phát ra từ nơi này nghiền nát đuôi Rắn chín đầu đang giữ cốt thư, sau đó khiến cốt thư bay về lơ lửng phía trên bồ đoàn.","nguon":["@c0518"]},{"id":"chien-dao-toc-nguoi-khong-lo-hoang-kim","name":"Chiến đảo tộc Người khổng lồ hoàng kim","cn":"","category":"khac","categoryLabel":"Công cụ chiến tranh","phamCap":"Đại sát khí trấn tộc","soHuu":["Tộc Người khổng lồ hoàng kim"],"trangThai":"Đã rút khỏi chiến trường","blurb":"Một hòn đảo màu vàng mang theo nhiều người khổng lồ, được điều tới vây giết Thạch Hạo.","detail":"Chiến đảo đóng vai trò pháo đài và công cụ chiến tranh của tộc Người khổng lồ hoàng kim. Nó phóng chùm kim quang có sức phá nát đất đá xuống chiến trường, đồng thời tham gia thế trận Ngũ hành nhằm bao vây và sát thương Thạch Hạo; lực lượng trên đảo về sau rút lui khi các cao thủ chủ chốt lần lượt bị giết.","nguon":["@c0519"]},{"id":"nui-ran-cong-cu-chien-tranh","name":"Núi Rắn","cn":"","category":"khac","categoryLabel":"Công cụ chiến tranh","phamCap":"Đại sát khí trấn tộc","soHuu":["Bộ tộc Rắn chín đầu"],"trangThai":"Đã rút khỏi chiến trường","blurb":"Ngọn núi đen phủ kín phù văn, được bộ tộc Rắn chín đầu đưa tới làm pháo đài chiến tranh và sát trận.","detail":"Theo hiệu lệnh của Rắn chín đầu, Núi Rắn tỏa ánh đen và phóng những chùm sáng hình rắn có uy lực đáng sợ về phía Thạch Hạo. Sau khi các Tôn giả chủ chốt bị tiêu diệt, lực lượng của Núi Rắn rút khỏi cuộc chiến để tránh gia tăng thương vong.","nguon":["@c0519"]},{"id":"to-kien-thien-thach","name":"Tổ kiến thiên thạch","cn":"","category":"khac","categoryLabel":"Pháo đài chiến tranh","phamCap":"Đại sát khí trấn tộc","soHuu":["Tộc Kiến"],"trangThai":"Đã rút khỏi chiến trường","blurb":"Một khối thiên thạch bị khoét rỗng, bên trong chứa nhiều kiến có cánh và sát trận của tộc Kiến.","detail":"Tổ kiến thiên thạch được dùng làm pháo đài chiến tranh để bao vây Thạch Hạo. Khi sát trận vận chuyển, vô số ký hiệu thần bí hóa thành đàn kiến có khả năng xuyên kim liệt thạch; lực lượng tại đây về sau rút lui khi tiếp tục giao chiến không còn ý nghĩa.","nguon":["@c0519"]},{"id":"phap-ky-cua-tieu-thap","name":"Pháp kỳ của Tiểu Tháp","cn":"","category":"phap-bao","categoryLabel":"Pháp bảo","phamCap":"","soHuu":["Tiểu Tháp"],"trangThai":"Đã được thu hồi","blurb":"Trận kỳ được Tiểu Tháp dùng để vận hành trận pháp hỗn độn bảo vệ vùng núi nơi gia đình Thạch Hạo trú ẩn.","detail":"Khi trở về, Tiểu Tháp thu lại pháp kỳ, hấp thu khí hỗn độn và giải bỏ trận pháp bao phủ vùng núi.","nguon":["@c0520"]},{"id":"tran-than-chau","name":"Trấn thần châu","cn":"","category":"phap-bao","categoryLabel":"Pháp bảo","phamCap":"Không rõ","soHuu":["Ma nữ"],"trangThai":"Được mang tới để trấn giữ thứ thân Nguyệt Thiền","blurb":"Pháp bảo có thể trấn giữ thứ thân Nguyệt Thiền, khiến nàng không thể chống lại hoặc tự hủy.","detail":"Ma nữ mang Trấn thần châu tới trong một hộp đá nhằm khống chế thứ thân Nguyệt Thiền. Pháp bảo này được dùng để ngăn thứ thân phản kháng, tự hủy hoặc dùng cái chết để giải thoát qua cơ chế phục sinh của chủ thân.","nguon":["@c0521"]},{"id":"nhan-hoang-an","name":"Nhân hoàng ấn","cn":"","category":"phap-bao","categoryLabel":"Pháp bảo","phamCap":"Chí bảo quốc vận","soHuu":["Thạch Hạo","Thạch quốc"],"trangThai":"Được đặt lại trên Long án thư","blurb":"Nhân Hoàng ấn là bảo ấn hội tụ số mệnh Thạch quốc, có thể buông xuống long khí hộ thân và phát huy sức trấn áp mạnh trong hoàng cung. Trước khi rời Thạch quốc, Thạch Hạo đã đặt bảo ấn trở lại trên Long án thư @c0572.","detail":"Nhân Hoàng ấn từng hiện trên đầu Thạch Hạo khi thần hồn hắn tiến vào biển ý thức của Nguyệt Thiền. Bảo ấn bao hàm số mệnh của Thạch quốc, dùng long khí bảo vệ Thạch Hạo và giúp hắn chiếm ưu thế trấn áp khi ở trong hoàng cung Thạch quốc. Đến lúc rời Thạch quốc, Thạch Hạo đặt Nhân Hoàng ấn lại trên Long án thư @c0572.","nguon":["@c0522","@c0572"],"tabs":{"tienTrinh":[{"chuong":"@c0572","loai":"đổi chủ","importance":"major","giaiDoan":"Được để lại tại hoàng cung","text":"Thạch Hạo đặt Nhân Hoàng ấn lại trên Long án thư trước khi rời Thạch quốc.","anchor":"có thể trấn áp số mệnh của một quốc gia, uy lực vô song","phamCap":"Không rõ"}]},"congNang":["Trấn áp số mệnh quốc gia.","Buông xuống long khí để hộ thân.","Gia tăng sức trấn áp trong hoàng cung Thạch quốc."],"chuSoHuu":[{"ten":"Thạch quốc","tuChuong":"@c0572","denChuong":"","cachCoDuoc":"Bảo ấn quốc gia được Thạch Hạo để lại trên Long án thư","trangThai":"đang lưu giữ"}],"uyLuc":"Trong hoàng cung Thạch quốc, Nhân Hoàng ấn giúp Thạch Hạo chiếm ưu thế trấn áp nhờ số mệnh quốc gia và long khí.","dacDiem":"Bảo ấn bao hàm số mệnh Thạch quốc, gắn với long khí và hoàng cung của quốc gia này."},{"id":"hoang-kim-dich","name":"Hoàng kim dịch","cn":"","category":"khac","categoryLabel":"Linh dịch","phamCap":"Chưa rõ","soHuu":["Thạch Hạo"],"trangThai":"Được Thạch Hạo cất giữ","blurb":"Một loại linh dịch được Thạch Hạo nhắc đến trong đêm tân hôn với Nguyệt Thiền.","detail":"Khi giả vờ nghi ngờ thân thể Nguyệt Thiền có vấn đề, Thạch Hạo nói mình có Hoàng kim dịch và có thể dùng nó để chữa trị. Công hiệu này mới chỉ xuất hiện trong lời trêu chọc của Thạch Hạo, chưa được thực tế kiểm chứng trong chương.","nguon":["@c0526"]},{"id":"bi-bao-trieu-hoan-thien-thach","name":"Bí bảo triệu hoán thiên thạch","cn":"","category":"phap-bao","categoryLabel":"Bí bảo","phamCap":"Chưa rõ","soHuu":["Nguyệt Thiền tiên tử"],"trangThai":"Đang được sử dụng","blurb":"Bí bảo của chủ thân Nguyệt Thiền có thể gia trì thân thể và triệu hoán thiên thạch.","detail":"Bí bảo phát sáng trong tay chủ thân Nguyệt Thiền khi nàng giao chiến trên tầng mây. Thạch Hạo nhận định vật này có khả năng triệu hoán thiên thạch để công kích hoàng cung Thạch quốc.","nguon":["@c0529"]},{"id":"buc-hoa-hoa-diem","name":"Bức họa hỏa diễm","cn":"","category":"phap-bao","categoryLabel":"Bí bảo","phamCap":"Bí bảo mạnh mẽ","soHuu":["Nguyệt Thiền chủ thân"],"trangThai":"Đã bị hủy","blurb":"Một bức họa chứa hỏa diễm, được chủ thân Nguyệt Thiền dùng để chặn bảo thuật của Thạch Hạo và thoát khỏi cận chiến.","detail":"Khi được kích phát, bức họa phóng ra hỏa diễm bao phủ thiên địa, thiêu tan chim thần màu vàng do Thạch Hạo diễn hóa. Sau khi hoàn thành tác dụng ngăn cản đối phương, toàn bộ bức họa bốc cháy thành tro và bị hủy hoàn toàn.","nguon":["@c0530"]},{"id":"dinh-nho-hoang-kim","name":"Đỉnh nhỏ hoàng kim","cn":"","category":"phap-bao","categoryLabel":"Chí bảo","phamCap":"Chí bảo","soHuu":["Nguyệt Thiền chủ thân"],"trangThai":"Nguyên vẹn, được lực Luân hồi làm trẻ hóa","blurb":"Một chiếc đỉnh cổ xưa hiện trên đầu chủ thân Nguyệt Thiền để chống lại lực Luân hồi của Chí tôn cốt.","detail":"Chiếc đỉnh không bị lực Luân hồi phá hủy mà mượn chính sức mạnh ấy để phục hồi trạng thái gần với lúc vừa được tế luyện, trở nên trong suốt và rực rỡ hơn. Khả năng chịu đựng rồi lợi dụng lực Luân hồi cho thấy đây là một chí bảo có lai lịch phi phàm.","nguon":["@c0530"]},{"id":"ngoc-ty-cua-thach-hao","name":"Ngọc tỷ của Thạch Hạo","cn":"","category":"phap-bao","categoryLabel":"Pháp bảo","phamCap":"Chưa rõ","soHuu":["Thạch Hạo"],"trangThai":"Nguyên vẹn","blurb":"Ngọc tỷ có thể giải phóng nhiều thiên long khổng lồ.","detail":"Trong cuộc chiến với chủ thân Nguyệt Thiền, ngọc tỷ phát ra tiếng rồng gầm và phóng thích nhiều thiên long nhập vào kim liên đại đạo để tăng cường sức công phạt.","hinhDang":"Ngọc tỷ","congNang":["Phóng thích nhiều thiên long để gia trì kim liên đại đạo."],"chuHienThoi":"Thạch Hạo","chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c0531","denChuong":"","cachCoDuoc":"","trangThai":"đang sở hữu"}],"tabs":{"tienTrinh":[{"chuong":"@c0531","loai":"dùng","importance":"normal","giaiDoan":"Gia trì kim liên","text":"Ngọc tỷ giải phóng nhiều thiên long nhập vào kim liên đại đạo của Thạch Hạo.","anchor":"không biết có bao nhiêu con thiên long lao ra ngoài, từng con to lớn vô cùng tiến vào trong kim liên","phamCap":"Chưa rõ"}]},"capNhatToi":"@c0531","nguon":["@c0531"]},{"id":"chi-ton-cot-bao-cot","name":"Chí tôn cốt","cn":"","category":"nguyen-lieu","categoryLabel":"Bảo cốt","phamCap":"Chưa rõ","soHuu":["Thạch Hạo"],"trangThai":"Dung hợp trong ngực Thạch Hạo","blurb":"Khối bảo cốt trong ngực Thạch Hạo phát ra ánh sáng vô lượng và thần uy Chí tôn.","detail":"Trên Chí tôn cốt có một bóng người nhỏ ngồi xếp bằng, có thể đứng lên, hóa lớn và mang hình dáng Thạch Hạo đánh tới. Bóng người này còn được dùng làm thế thân để đánh lừa tám tòa đại trận cấp Thần.","phanLoaiPhu":"Bảo cốt thiên phú","hinhDang":"Khối cốt nằm trong ngực Thạch Hạo","uyLuc":"Tạo bóng người mang thần uy Chí tôn phát động công kích.","dacDiem":"Bóng người trên khối cốt có thể được dùng làm thế thân đánh lừa đối thủ.","congNang":["Tạo bóng người thế thân mang hình dáng Thạch Hạo.","Phát động công kích mang thần uy Chí tôn."],"chuHienThoi":"Thạch Hạo","chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c0531","denChuong":"","cachCoDuoc":"Dung hợp trong cơ thể","trangThai":"đang sở hữu"}],"tabs":{"tienTrinh":[{"chuong":"@c0531","loai":"dùng","importance":"normal","giaiDoan":"Thế thân và phản kích","text":"Thạch Hạo dùng bóng người trên Chí tôn cốt làm thế thân chịu sát trận rồi phát động đòn phản kích mang thần uy Chí tôn.","anchor":"bên trên là một người tí hon đang xếp bằng đang từ từ đứng lên, đồng thời nhanh chóng hóa lớn giống như đúc Thạch Hạo với thần uy Chí tôn đánh tới","phamCap":"Chưa rõ"}]},"capNhatToi":"@c0531","nguon":["@c0531"]},{"id":"dai-phap-ky-cap-than","name":"Đại pháp kỳ cấp Thần","cn":"","category":"phap-bao","categoryLabel":"Trận kỳ","phamCap":"Cấp Thần","soHuu":["Chủ thân Nguyệt Thiền"],"trangThai":"Đã được thu hồi","blurb":"Các trận kỳ cấu thành tám tòa đại trận cấp Thần của chủ thân Nguyệt Thiền.","detail":"Nhiều đại pháp kỳ được giấu lẫn trong thiên thạch quanh trận địa. Sau khi tưởng Thạch Hạo đã bị tiêu diệt, chủ thân Nguyệt Thiền lần lượt thu hồi chúng.","phanLoaiPhu":"Trận kỳ","dacDiem":"Được giấu lẫn trong các khối thiên thạch.","congNang":["Bố trí và duy trì đại trận cấp Thần."],"chuHienThoi":"Chủ thân Nguyệt Thiền","chuSoHuu":[{"ten":"Chủ thân Nguyệt Thiền","tuChuong":"@c0531","denChuong":"","cachCoDuoc":"","trangThai":"đang sở hữu"}],"tabs":{"tienTrinh":[{"chuong":"@c0531","loai":"dùng","importance":"normal","giaiDoan":"Bố trí sát trận","text":"Các đại pháp kỳ được giấu trong thiên thạch để cấu thành sát trận cấp Thần rồi được chủ thân Nguyệt Thiền thu hồi.","anchor":"rút lại những đại pháp kỳ của trận pháp cấp Thần, có rất nhiều pháp kỳ lẫn ở bên trong thiên thạch","phamCap":"Cấp Thần"}]},"capNhatToi":"@c0531","nguon":["@c0531"]},{"id":"hoang-kim-dinh","name":"Hoàng kim đỉnh","cn":"","aliases":["Đỉnh nhỏ hoàng kim của chủ thân Nguyệt Thiền"],"category":"phap-bao","categoryLabel":"Chí bảo thượng cổ","phanLoaiPhu":"Đỉnh hộ chủ","phamCap":"Chí bảo thượng cổ","soHuu":["Chủ thân Nguyệt Thiền"],"chuHienThoi":"Chủ thân Nguyệt Thiền","trangThai":"Đã thức tỉnh để hộ chủ","blurb":"Hoàng kim đỉnh là chí bảo thượng cổ thường trầm miên bên chủ thân Nguyệt Thiền và không nghe điều khiển. Khi Nguyệt Thiền đứng trước nguy cơ mất mạng, đỉnh tự thức tỉnh, bảo vệ nàng rồi xuyên qua hư không rời khỏi chiến trường.","detail":"Hoàng kim đỉnh giao hòa với chân huyết Phượng hoàng. Trong lúc chủ thân Nguyệt Thiền sắp chết, pháp bảo tự thức tỉnh, hóa lớn để thu nàng vào trong, chịu đựng các đòn công kích liên tiếp của Thạch Hạo, sau đó xuyên qua hư không thoát khỏi chiến trường. @c0532","uyLuc":"Có thể chịu đựng các đòn công kích liên tiếp của Thạch Hạo trong lúc bảo vệ chủ nhân.","dacDiem":"Chí bảo thượng cổ giao hòa với chân huyết Phượng hoàng; thường ngày trầm miên và không nghe điều khiển, nhưng sẽ tự thức tỉnh khi chủ thân Nguyệt Thiền lâm nguy.","congNang":["Tự động thức tỉnh và hộ chủ khi chủ thân Nguyệt Thiền đứng trước nguy cơ mất mạng. @c0532","Hóa lớn để thu chủ nhân vào trong. @c0532","Xuyên qua hư không để đưa chủ nhân rời khỏi chiến trường. @c0532"],"chuSoHuu":[{"ten":"Chủ thân Nguyệt Thiền","tuChuong":"@c0532","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"Đang sở hữu"}],"capNhatToi":"@c0532","tabs":{"tienTrinh":[{"chuong":"@c0532","loai":"khai phong","importance":"major","giaiDoan":"Thức tỉnh hộ chủ","text":"Hoàng kim đỉnh thức tỉnh khi chủ thân Nguyệt Thiền sắp chết, thu nàng vào trong rồi xuyên qua hư không thoát khỏi sự truy kích của Thạch Hạo.","phamCap":"Chí bảo thượng cổ","anchor":"Hoàng kim đỉnh này là chí bảo thượng cổ, chỉ là ngày thường luôn trầm miên không thèm để ý tới nàng"}]},"nguon":["@c0532"]},{"id":"chan-huyet-phuong-hoang","name":"Chân huyết Phượng hoàng","cn":"","aliases":[],"category":"nguyen-lieu","categoryLabel":"Chân huyết","phamCap":"Không rõ","soHuu":["Chủ thân Nguyệt Thiền"],"trangThai":"Đã dung hợp","blurb":"Một giọt chân huyết tỏa ráng tím được cất trong bình ngọc bên trong cơ thể chủ thân Nguyệt Thiền. Khi bình vỡ, giọt máu dung hợp với nàng và giao hòa cùng Hoàng kim đỉnh.","detail":"Thạch Hạo nhận định giọt máu mang khí tức sinh tồn vô tận này là chân huyết Phượng hoàng. Nó xuất hiện khi chủ thân Nguyệt Thiền bị đánh tới gần chết.","dacDiem":"Tỏa ráng tím ngất trời và mang khí tức sinh tồn mạnh mẽ.","congNang":["Dung hợp với thân thể chủ thân Nguyệt Thiền khi nàng trọng thương.","Giao hòa với Hoàng kim đỉnh trong lúc chí bảo thức tỉnh."],"chuSoHuu":[{"ten":"Chủ thân Nguyệt Thiền","tuChuong":"@c0532","denChuong":"@c0532","cachCoDuoc":"Được cất trong một bình ngọc bên trong cơ thể","trangThai":"Đã dung hợp"}],"capNhatToi":"@c0532","tabs":{"tienTrinh":[{"chuong":"@c0532","loai":"dùng","importance":"normal","giaiDoan":"Dung hợp cứu chủ","text":"Chân huyết Phượng hoàng rơi khỏi bình ngọc bị vỡ, dung hợp với chủ thân Nguyệt Thiền và giao hòa cùng Hoàng kim đỉnh.","phamCap":"Không rõ","anchor":"nơi đó rơi ra một giọt máu có ráng tím ngất trời"}]},"nguon":["@c0532"]},{"id":"hop-quy-dong-thau","name":"Hộp quý đồng thau","cn":"","aliases":["Hộp báu đồng thau"],"category":"khac","categoryLabel":"Hộp quý","phamCap":"Không rõ","soHuu":["Thạch Hạo"],"chuHienThoi":"Thạch Hạo","trangThai":"Đã đổi chủ","blurb":"Hộp quý đồng thau vốn thuộc số vật phẩm của chủ thân Nguyệt Thiền. Khi nàng bị trọng thương, hộp rơi ra và được Thạch Hạo thu lấy; công dụng của nó chưa được thể hiện.","detail":"Hộp quý đồng thau ban đầu do chủ thân Nguyệt Thiền mang theo. Trong lúc nàng trọng thương, vật này rơi khỏi người và được Thạch Hạo thu lấy, qua đó đổi chủ @c0532. Hồ sơ chưa ghi nhận nguồn gốc sâu hơn, công năng hay uy lực của hộp.","chuSoHuu":[{"ten":"Chủ thân Nguyệt Thiền","tuChuong":"@c0532","denChuong":"@c0532","cachCoDuoc":"Không rõ","trangThai":"Đã mất"},{"ten":"Thạch Hạo","tuChuong":"@c0532","denChuong":"","cachCoDuoc":"Thu lấy khi vật phẩm rơi khỏi người chủ thân Nguyệt Thiền","trangThai":"Đang sở hữu"}],"capNhatToi":"@c0532","tabs":{"tienTrinh":[{"chuong":"@c0532","loai":"đổi chủ","importance":"major","giaiDoan":"Rơi vào tay Thạch Hạo","text":"Hộp quý đồng thau rơi khỏi người chủ thân Nguyệt Thiền khi nàng trọng thương và bị Thạch Hạo thu lấy.","phamCap":"Không rõ","anchor":"nó thu lại toàn bộ pháp khí bảo dược mà Nguyệt Thiền làm rớt ra, bao gồm cả Hộp quý đồng thau"}]},"nguon":["@c0532"],"dacDiem":"Một hộp quý bằng đồng thau."},{"id":"ngan-hoang-vu","name":"Ngân hoàng vũ","cn":"","aliases":[],"category":"nguyen-lieu","categoryLabel":"Nguyên liệu","phanLoaiPhu":"Chân vũ nguyên thủy","phamCap":"Trân phẩm","soHuu":["Thạch Hạo"],"trangThai":"Đang được sở hữu","blurb":"Chân vũ nguyên thủy của ngân hoàng, một hậu duệ của phượng hoàng Thái Cổ.","detail":"Cọng lông chim có màu bạc trắng bóng, tỏa thần năng mạnh mẽ và có thể dễ dàng cắt đứt sắt đá. Thạch Hạo thu được nó từ chiến lợi phẩm để làm vật liệu tế luyện Quạt Ngũ Cầm.","hinhDang":"Một cọng lông chim bạc trắng bóng.","vatLieu":"Chân vũ nguyên thủy của ngân hoàng.","nguonGoc":"Thu được từ chiến lợi phẩm sau trận chiến tại hoàng cung.","uyLuc":"Thần năng tỏa ra đủ sức dễ dàng cắt đứt sắt đá.","dacDiem":"Thuộc về ngân hoàng, hậu duệ của phượng hoàng Thái Cổ.","chuHienThoi":"Thạch Hạo","chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c0533","denChuong":"","cachCoDuoc":"Thu được khi kiểm kê chiến lợi phẩm","trangThai":"Đang sở hữu"}],"congNang":["Có thể cắt đứt sắt đá.","Dùng làm vật liệu tế luyện Quạt Ngũ Cầm."],"capNhatToi":"@c0533","tabs":{"tienTrinh":[{"chuong":"@c0533","loai":"xuất hiện","importance":"normal","giaiDoan":"Rơi vào tay Thạch Hạo","text":"Thạch Hạo tìm thấy Ngân hoàng vũ trong chiến lợi phẩm và giữ lại làm vật liệu tế luyện Quạt Ngũ Cầm.","phamCap":"Trân phẩm","anchor":"Lông chim màu bạc này cứ như ánh lửa nhảy múa, tản ra thần năng đầy mạnh mẽ"}]},"nguon":["@c0533"]},{"id":"bo-thien-dan","name":"Bổ Thiên Đan","cn":"","aliases":[],"category":"dan-duoc","categoryLabel":"Đan dược","phanLoaiPhu":"Thánh đan chữa thương","phamCap":"Thánh vật quý nhất Bổ Thiên giáo","soHuu":["Thạch Hạo"],"trangThai":"Đang được sở hữu","blurb":"Bổ Thiên Đan là thánh vật của Bổ Thiên giáo, được Thạch Hạo phát hiện trong một bình ngọc rạn nứt khi kiểm kê chiến lợi phẩm rồi giữ lại. Viên thánh đan có thể cứu sống người vẫn còn một hơi thở; ngay cả khí tức tỏa ra cũng giúp thương thế chuyển biến tốt.","detail":"Bổ Thiên Đan là một viên thánh đan lớn bằng ngón tay, tỏa hào quang vàng và lấy thánh dược làm chủ dược. Thạch Hạo tìm thấy nó trong một bình ngọc rạn nứt giữa số chiến lợi phẩm và quyết định giữ lại; chỉ hít khí tức của đan cũng đã khiến thương thế của hắn chuyển biến tốt. @c0533","hinhDang":"Viên đan lớn bằng ngón tay, tỏa hào quang màu vàng.","vatLieu":"Lấy thánh dược làm chủ dược.","nguonGoc":"Thánh vật của Bổ Thiên giáo, được Thạch Hạo thu từ chiến lợi phẩm.","uyLuc":"Có thể cứu sống người dùng nếu người đó vẫn còn một hơi thở.","dacDiem":"Viên đan lớn bằng ngón tay, tỏa hào quang vàng, được cất trong một bình ngọc rạn nứt và lấy thánh dược làm chủ dược.","chuHienThoi":"Thạch Hạo","chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c0533","denChuong":"","cachCoDuoc":"Thu được khi kiểm kê chiến lợi phẩm","trangThai":"Đang sở hữu"}],"congNang":["Cứu sống người dùng nếu người đó vẫn còn một hơi thở.","Khí tức tỏa ra có thể giúp thương thế chuyển biến tốt. @c0533"],"capNhatToi":"@c0533","tabs":{"tienTrinh":[{"chuong":"@c0533","loai":"xuất hiện","importance":"major","giaiDoan":"Được Thạch Hạo thu giữ","text":"Thạch Hạo phát hiện Bổ Thiên Đan trong một bình ngọc rạn nứt khi kiểm kê chiến lợi phẩm và giữ viên thánh đan có khả năng cứu mạng này.","phamCap":"Thánh vật quý nhất Bổ Thiên giáo","anchor":"chỉ cần còn một hơi thở thì nuốt vào bảo đảm sẽ sống lại lần nữa"}]},"nguon":["@c0533"]},{"id":"chien-vuc-than-ma","name":"Chiến vực Thần ma","cn":"","category":"phap-bao","categoryLabel":"Pháp khí không gian","phamCap":"Hi hữu ở thế gian","soHuu":[],"trangThai":"Hoàn chỉnh","blurb":"Pháp khí không gian tạo thành một chiến trường khép kín, được dùng cho cuộc giao chiến giữa Bóng Lông và Con chim đỏ nhỏ.","detail":"Pháp khí diễn hóa sơn hà làm chiến trường, ngăn sức phá hoại lan tới Đại hoang. Cảnh vật bị phá hủy bên trong có thể tự phục hồi.","phanLoaiPhu":"Pháp khí không gian","hinhDang":"Một vùng sơn hà được diễn hóa thành chiến trường.","uyLuc":"Có thể phong tỏa sức phá hoại từ cuộc chiến của hai sinh linh đã bước đầu nhen nhóm Thần hỏa.","dacDiem":"Sơn hà bị phá hủy trong chiến trường có thể phục hồi.","congNang":["Diễn hóa một chiến trường không gian khép kín.","Phong tỏa sức phá hoại để không lan tới Đại hoang.","Phục hồi cảnh vật bị phá hủy trong chiến trường."],"tabs":{"tienTrinh":[{"chuong":"@c0535","loai":"dùng","importance":"normal","giaiDoan":"Làm chiến trường","text":"Chiến vực Thần ma bao bọc cuộc chiến giữa Bóng Lông và Con chim đỏ nhỏ, giữ sức phá hoại không lan ra Đại hoang.","anchor":"Chiến trường của hai bọn nó là một pháp khí hi hữu ở thế gian","phamCap":"Hi hữu ở thế gian"}]},"capNhatToi":"@c0535","nguon":["@c0535"]},{"id":"hoa-dich","name":"Hỏa dịch","cn":"","category":"nguyen-lieu","categoryLabel":"Tài nguyên tu luyện","phamCap":"Không rõ","soHuu":["Thạch Hạo","Dân làng Thạch thôn"],"trangThai":"Được phân phát tại Thạch thôn","blurb":"Tài nguyên tu luyện được Thạch Hạo mang về Thạch thôn với số lượng rất lớn.","detail":"Thạch Hạo phân phát lượng lớn hỏa dịch cho dân làng trong đêm đoàn tụ, khiến những người chứng kiến đều kinh ngạc.","dacDiem":"Được mang về với số lượng rất lớn.","congNang":["Dùng làm tài nguyên tu luyện."],"chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c0535","denChuong":"@c0535","cachCoDuoc":"Mang về Thạch thôn","trangThai":"đã phân phát"},{"ten":"Dân làng Thạch thôn","tuChuong":"@c0535","denChuong":"","cachCoDuoc":"Được Thạch Hạo phân phát","trangThai":"đang có"}],"tabs":{"tienTrinh":[{"chuong":"@c0535","loai":"đổi chủ","importance":"normal","giaiDoan":"Phân phát trong thôn","text":"Thạch Hạo mang về và phân phát một lượng lớn hỏa dịch cho dân làng Thạch thôn.","anchor":"Đặc biệt nó mang về một lượng lớn hỏa dịch","phamCap":"Không rõ"}]},"capNhatToi":"@c0535","nguon":["@c0535"]},{"id":"linh-can-de-nhat-thuong-gioi","name":"Linh căn đệ nhất thượng giới","cn":"","aliases":[],"category":"khac","categoryLabel":"Kỳ dược và sinh linh biến hóa","phamCap":"Không rõ","soHuu":[],"trangThai":"Được bảo vệ gần Dược đô","blurb":"Linh căn gần Dược đô vốn là một sinh linh đáng sợ từng sống sót trở về từ khu vực thần bí của thượng giới.","detail":"Sinh linh này từng cùng hai bá chủ tiến vào vùng bí hiểm nhưng là kẻ duy nhất thoát chết, sau đó hóa thành cây dược. Linh căn được vô số trận pháp bảo vệ.","phanLoaiPhu":"Kỳ dược do sinh linh biến hóa","nguonGoc":"Sinh linh đáng sợ trở về từ khu vực thần bí thượng giới","dacDiem":"Được vô số trận pháp bảo vệ.","congNang":[],"capNhatToi":"@c0536","tabs":{"tienTrinh":[{"chuong":"@c0536","loai":"xuất hiện","importance":"normal","giaiDoan":"Hé lộ nguồn gốc","text":"Nguồn gốc của linh căn được tiết lộ là một sinh linh đáng sợ sống sót sau chuyến thăm dò vùng thần bí rồi hóa thành cây dược.","anchor":"sau đó nó hóa thành cây dược này"}]},"nguon":["@c0536"]},{"id":"trung-da-chan-long","name":"Trứng đá chân long","cn":"","aliases":[],"category":"khac","categoryLabel":"Trứng sinh linh","phamCap":"Không rõ","soHuu":[],"trangThai":"Không rõ","blurb":"Quả trứng đá lượn lờ khí hỗn độn được nhận định có khả năng nở ra chân long.","detail":"Người phát hiện quả trứng đã dùng bí pháp cầu viện môn phái. Đoàn tiếp ứng sau đó chết sạch khi đi qua một vũng bùn nhỏ trên đường rút lui.","phanLoaiPhu":"Trứng sinh linh","hinhDang":"Quả trứng bằng đá","dacDiem":"Có khí hỗn độn lượn lờ xung quanh.","congNang":["Có thể nở ra chân long."],"capNhatToi":"@c0536","tabs":{"tienTrinh":[{"chuong":"@c0536","loai":"xuất hiện","importance":"normal","giaiDoan":"Được phát hiện","text":"Quả trứng đá lượn lờ khí hỗn độn được phát hiện và nhận định có thể nở ra chân long.","anchor":"đó là một quả trứng có thể nở ra chân long"}]},"nguon":["@c0536"]},{"id":"canh-cua-nguyen-thuy-phap-khi","name":"Cánh cửa nguyên thủy","cn":"","aliases":[],"category":"khac","categoryLabel":"Cửa ngõ thần bí","phamCap":"Không rõ","soHuu":[],"trangThai":"Tồn tại và chưa rõ đích đến","blurb":"Cửa ngõ thần bí được Liễu Thần nghi ngờ có thể dẫn tới nơi sâu trong khu vực bí hiểm.","detail":"Những người từng bước qua cánh cửa chỉ để lại máu chảy ra rồi không còn tái hiện. Trải nghiệm của Liễu Thần thời thái cổ làm tăng khả năng cánh cửa nối với vùng sâu nguy hiểm của thượng giới.","phanLoaiPhu":"Cửa ngõ không gian thần bí","dacDiem":"Người bước qua không trở lại, chỉ có máu chảy ra.","congNang":["Có khả năng dẫn tới nơi sâu trong khu vực thần bí."],"capNhatToi":"@c0536","tabs":{"tienTrinh":[{"chuong":"@c0536","loai":"nhắc tới","importance":"normal","giaiDoan":"Hé lộ đích đến khả nghi","text":"Liễu Thần nêu khả năng cánh cửa nguyên thủy dẫn tới nơi sâu trong khu vực thần bí.","anchor":"khi xuyên qua cánh cửa nguyên thủy thì khả năng sẽ tiến vào nơi sâu trong khu vực thần bí"}]},"nguon":["@c0536"]},{"id":"chien-y-bat-diet-kim-than","name":"Chiến y Bất diệt kim thân","cn":"","category":"phap-bao","categoryLabel":"Chiến y","phamCap":"Không rõ","soHuu":["Thạch Hạo"],"trangThai":"nguyên vẹn","blurb":"Chiến y bị vỡ thành hàng chục mảnh trong trận chiến, nhưng bộ phận trọng yếu vẫn nguyên vẹn. (+) Chiến y hộ thân được Thạch Hạo mặc khi giao đấu với Bóng Lông. [CAN-SOAT-GOP]","detail":"Chiến y giúp bảo vệ Thạch Hạo, nhưng không thể hoàn toàn triệt tiêu sức mạnh thần hỏa truyền qua thiết côn của Bóng Lông.","phanLoaiPhu":"Chiến y hộ thân","congNang":["Bảo vệ thân thể người mặc trong giao chiến."],"uyLuc":"Không hoàn toàn triệt tiêu được lực đánh mang sức mạnh thần hỏa của Bóng Lông.","chuHienThoi":"Thạch Hạo","chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c0537","denChuong":"","cachCoDuoc":"Không nêu trong chương","trangThai":"đang sở hữu"}],"tabs":{"tienTrinh":[{"chuong":"@c0537","loai":"dùng","importance":"normal","giaiDoan":"Dùng trong giao đấu","text":"Thạch Hạo mặc chiến y Bất diệt kim thân khi giao đấu với Bóng Lông nhưng vẫn chịu chấn động từ sức mạnh thần hỏa.","anchor":"dù đã mặc vào chiến y Bất diệt kim thân thế nhưng cũng cảm thấy hơi chịu không nổi","phamCap":"Không rõ"}]},"capNhatToi":"@c0537","nguon":["@c0537","@c0608"]},{"id":"thiet-con-mau-den-cua-bong-long","name":"Thiết côn màu đen của Bóng Lông","cn":"","category":"phap-bao","categoryLabel":"Binh khí","phamCap":"Không rõ","soHuu":["Bóng Lông"],"trangThai":"nguyên vẹn","blurb":"Thiết côn màu đen được Bóng Lông sử dụng khi giao đấu với Thạch Hạo.","detail":"Binh khí truyền sức mạnh thần hỏa của Bóng Lông qua đòn đánh, khiến Thạch Hạo vẫn chịu chấn động dù đang mặc chiến y Bất diệt kim thân.","phanLoaiPhu":"Thiết côn","hinhDang":"Côn bằng kim loại màu đen.","congNang":["Truyền lực công kích và sức mạnh thần hỏa của người sử dụng."],"chuHienThoi":"Bóng Lông","chuSoHuu":[{"ten":"Bóng Lông","tuChuong":"@c0537","denChuong":"","cachCoDuoc":"Không nêu trong chương","trangThai":"đang sở hữu"}],"tabs":{"tienTrinh":[{"chuong":"@c0537","loai":"dùng","importance":"normal","giaiDoan":"Dùng trong giao đấu","text":"Bóng Lông dùng thiết côn màu đen truyền sức mạnh thần hỏa vào Thạch Hạo.","anchor":"Thần hỏa đã nhen nhóm này đã xuyên thấy qua thiết côn màu đen nơi tay của Bóng Lông truyền tới","phamCap":"Không rõ"}]},"capNhatToi":"@c0537","nguon":["@c0537"]},{"id":"vien-trung-dong","name":"Viên Trùng đồng","cn":"","category":"khac","categoryLabel":"Dị bảo","phamCap":"Không rõ","soHuu":["Thạch Hạo"],"trangThai":"đang được sử dụng","blurb":"Dị bảo thị giác được Thạch Hạo mượn dùng để nhìn xuyên hư ảo và quan sát từ khoảng cách xa. (+) Một viên Trùng Đồng được cất trong hộp bảo đồng thau của Thạch Hạo. [CAN-SOAT-GOP]","detail":"Viên Trùng đồng giúp Thạch Hạo tìm ra chân thân Bóng Lông giữa vô số phân thân và nhìn rõ các bóng người trong khe nứt trên trời. Việc phải dựa vào vật ngoại lai khiến nó quyết tâm tự tu thành Thiên nhãn.","phanLoaiPhu":"Dị bảo thị giác","congNang":["Nhìn xuyên hư ảo để nhận ra chân thân ẩn giữa các phân thân.","Quan sát mục tiêu ở khoảng cách xa."],"dacDiem":"Là vật ngoại lai được Thạch Hạo mượn dùng thay vì năng lực thị giác do bản thân tu thành.","chuHienThoi":"Thạch Hạo","chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c0537","denChuong":"","cachCoDuoc":"Mượn dùng","trangThai":"đang sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c0537","loai":"dùng","importance":"normal","giaiDoan":"Nhìn xuyên hư ảo","text":"Thạch Hạo dùng viên Trùng đồng tìm ra chân thân Bóng Lông và quan sát dị tượng trên trời.","anchor":"bởi vì nó vận dụng con mắt Trùng đồng có thể nhìn xuyên hư vô","phamCap":"Không rõ"}]},"capNhatToi":"@c0537","nguon":["@c0537","@c0602"]},{"id":"than-thap-hai-tang-cua-tieu-thap","name":"Thân tháp hai tầng của Tiểu Tháp","cn":"","aliases":["Tòa tháp hai tầng","Thân tháp tầng thứ hai của Tiểu Tháp","Thân tháp hai tầng"],"category":"phap-bao","categoryLabel":"Mảnh thân tháp","phamCap":"","soHuu":["Tiểu Tháp"],"trangThai":"Đang dung hợp với Tiểu Tháp","blurb":"Thân tháp hai tầng là bộ phận thân thể còn thiếu mà Tiểu Tháp muốn đoạt lại để khôi phục sức mạnh. Trong cuộc tranh đoạt, ý chí phản kháng bên trong bị nhiều cường giả đánh tan, sau đó thân tháp được Liễu Thần đoạt khỏi chiếc chuông cổ @c0540.","detail":"Tiểu Tháp xác định thân tháp tầng thứ hai là mục tiêu trọng yếu trong cuộc tranh đoạt sắp tới và xin Liễu Thần trợ giúp thu hồi @c0538. Khi cuộc tranh đoạt diễn ra, ý chí phản kháng trong thân tháp bị nhiều cường giả đánh tan; Liễu Thần sau đó đoạt được nó từ chiếc chuông cổ @c0540. Đây là phần thân thể còn thiếu, có thể giúp Tiểu Tháp khôi phục sức mạnh sau khi dung hợp.","phanLoaiPhu":"Bộ phận thân thể của Tiểu Tháp","chuHienThoi":"","congNang":["Là bộ phận thân thể còn thiếu của Tiểu Tháp.","Có thể giúp Tiểu Tháp khôi phục sức mạnh sau khi dung hợp.","Có thể phóng khí âm dương để chống lại những người tranh đoạt."],"chuSoHuu":[{"ten":"Tiểu Tháp","tuChuong":"@c0538","denChuong":"","cachCoDuoc":"Được Liễu Thần đoạt lại và trao trả.","trangThai":"đang dung hợp"},{"ten":"Đạo nhân Âm dương","tuChuong":"","denChuong":"@c0540","cachCoDuoc":"Chiếm giữ và bồi dưỡng ý chí mới trong thân tháp.","trangThai":"đã mất"}],"dinhDanh":"goc","capNhatToi":"@c0538","tabs":{"tienTrinh":[{"chuong":"@c0538","loai":"nhắc tới","importance":"normal","giaiDoan":"Chuẩn bị thu hồi","text":"Tiểu Tháp xin Liễu Thần trợ giúp đoạt lại thân tháp tầng thứ hai trong cuộc tranh đoạt sắp tới.","anchor":"Tới lúc đó, kính xin hãy giúp tao đoạt lại thân tháp tầng thứ hai","phamCap":""},{"chuong":"@c0540","loai":"đổi chủ","importance":"major","giaiDoan":"Trở về với Tiểu Tháp","text":"Ý chí phản kháng trong thân tháp bị nhiều cường giả đánh tan, sau đó Liễu Thần đoạt nó khỏi chiếc chuông cổ và trao cho Tiểu Tháp bắt đầu dung hợp.","anchor":"đây chính là thân thể mà nó đã bị mất đi trong cuộc chiến thái cổ, hiện tại chính là thời cơ tốt nhất để dung hợp","phamCap":"Chí bảo"}]},"nguon":["@c0538","@c0540"],"dacDiem":"Là thân tháp tầng thứ hai của Tiểu Tháp, bên trong từng tồn tại ý chí phản kháng trước khi bị nhiều cường giả đánh tan @c0540."},{"id":"hai-khoi-cot-cua-nguyen-thuy-chan-giai","name":"Hai khối cốt của Nguyên thủy chân giải","cn":"","aliases":[],"category":"khac","categoryLabel":"Cốt thư","phamCap":"","soHuu":["Thạch Hạo"],"trangThai":"đang do Thạch Hạo nắm giữ","blurb":"Hai mảnh cốt trắng có thể ghép lại với nhau nhưng tổng thể vẫn thiếu một góc.","detail":"Thạch Hạo lần lượt lấy hai khối cốt tại Thạch đô và bảo khố Bất Lão sơn. Chúng có cùng chất liệu và ghép được với nhau, nhưng chưa thể bổ toàn thiên Thần dẫn vì còn thiếu Vạn linh đồ.","hinhDang":"Hai khối cốt trắng nõn trong suốt có thể ghép lại.","dacDiem":"Hai mảnh ghép được nhưng tổng thể vẫn thiếu một góc.","chuHienThoi":"Thạch Hạo","congNang":["Ghi lại phần hiện có của Nguyên thủy chân giải."],"chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c0538","denChuong":"","cachCoDuoc":"Lần lượt đoạt được tại Thạch đô và tìm thấy trong bảo khố Bất Lão sơn.","trangThai":"đang sở hữu"}],"dinhDanh":"goc","capNhatToi":"@c0538","tabs":{"tienTrinh":[{"chuong":"@c0538","loai":"xuất hiện","importance":"normal","giaiDoan":"Ghép hai mảnh cốt","text":"Thạch Hạo lấy hai khối cốt trắng cho Liễu Thần xem và xác nhận chúng có thể ghép lại với nhau.","anchor":"Nó lấy ra hai khối cốt trắng noãn trong suốt, hai khối có thể ghép lại với nhau","phamCap":""}]},"nguon":["@c0538"]},{"id":"nguyen-thuy-chan-giai-van-linh-do","name":"Nguyên Thủy Chân Giải – Vạn Linh đồ","cn":"","aliases":["Nguyên Thủy Chân Cốt","Vạn Linh đồ"],"category":"khac","categoryLabel":"Đồ khắc trên Thiên cốt","phamCap":"","soHuu":[],"trangThai":"đã vỡ nát trên Thiên cốt","blurb":"Vạn Linh đồ là bộ phận còn thiếu thuộc thiên Thần dẫn của Nguyên Thủy Chân Giải, có vai trò bổ toàn chân nghĩa của thiên này. Theo xác nhận của Liễu Thần, Vạn Linh đồ đã vỡ nát trên Thiên cốt. @c0538","detail":"Vạn Linh đồ thuộc thiên Thần dẫn của Nguyên Thủy Chân Giải, là phần cần thiết để bổ toàn phần chân nghĩa vốn khó được lĩnh hội đầy đủ khi thiếu nó. Liễu Thần xác nhận Vạn Linh đồ đã vỡ nát trên Thiên cốt. @c0538","nguonGoc":"Thuộc thiên Thần dẫn của Nguyên thủy chân giải.","dacDiem":"Là bộ phận còn thiếu của thiên Thần dẫn trong Nguyên Thủy Chân Giải; đã vỡ nát trên Thiên cốt. @c0538","congNang":["Bổ toàn chân nghĩa của thiên Thần dẫn, giúp lĩnh hội phần chân nghĩa vốn khó đạt đến đầy đủ khi thiếu Vạn Linh đồ. @c0538"],"dinhDanh":"goc","capNhatToi":"@c0538","tabs":{"tienTrinh":[{"chuong":"@c0538","loai":"xuất hiện","importance":"major","giaiDoan":"Hé lộ phần còn thiếu","text":"Liễu Thần xác nhận Vạn linh đồ đã vỡ trên Thiên cốt và là bộ phận còn thiếu của thiên Thần dẫn.","anchor":"còn có một bức Vạn linh đồ, đã vỡ nát trên Thiên cốt","phamCap":""}]},"nguon":["@c0538","@c0779"]},{"id":"hat-giong-ho-lo-cua-te-linh-bo-thien-cac","name":"Hạt giống hồ lô của Tế Linh Bổ Thiên các","cn":"","aliases":[],"category":"khac","categoryLabel":"Hạt giống truyền thừa","phamCap":"","soHuu":["Tế Linh"],"trangThai":"đã nảy thành dây leo","blurb":"Quả hồ lô cuối cùng do Tế Linh Bổ Thiên các để lại đã phát triển thành một dây leo hồ lô xanh tốt tại di chỉ Bổ Thiên các. Được Liễu Thần tìm thấy và bố trí trận pháp bảo vệ, nó gánh giữ hạt giống truyền thừa còn sót lại của Bổ Thiên các.","detail":"Trong trận chiến diệt môn của Bổ Thiên các, quả hồ lô cuối cùng của Tế Linh đã phá không trốn đi và lưu lại tại di chỉ. Liễu Thần suy diễn ra vị trí của nó, khi ấy hạt giống đã sinh trưởng thành dây leo hồ lô xanh tốt, rồi bố trí trận pháp bảo vệ nhằm giữ lại cơ hội tái sinh truyền thừa Bổ Thiên các. @c0538","phanLoaiPhu":"Hạt giống truyền thừa","hinhDang":"Dây leo hồ lô xanh tốt mọc trong một bụi gai.","nguonGoc":"Quả hồ lô cuối cùng do Tế Linh Bổ Thiên các để lại.","congNang":["Gánh giữ hạt giống truyền thừa và cơ hội tái sinh của Bổ Thiên các. @c0538"],"chuHienThoi":"Truyền thừa Bổ Thiên các","chuSoHuu":[{"ten":"Tế Linh","tuChuong":"@c0538","denChuong":"","cachCoDuoc":"Quả hồ lô do Tế Linh để lại trước khi tiêu hao hết sinh mệnh.","trangThai":"di vật truyền thừa"}],"dinhDanh":"goc","capNhatToi":"@c0538","tabs":{"tienTrinh":[{"chuong":"@c0538","loai":"khai phong","importance":"major","giaiDoan":"Khôi phục hạt giống","text":"Liễu Thần tìm thấy dây leo hồ lô đã sinh trưởng xanh tốt tại di chỉ Bổ Thiên các và bố trí trận pháp bảo vệ.","anchor":"trong một bụi gai có một dây leo Hồ lô xanh mơn mỡn, đang phát triển vô cùng tươi tốt","phamCap":""}]},"nguon":["@c0538"],"dacDiem":"Đã sinh trưởng thành dây leo hồ lô xanh tốt tại di chỉ Bổ Thiên các và được trận pháp do Liễu Thần bố trí bảo vệ. @c0538"},{"id":"cay-lieu-xanh-mot-thuoc","name":"Cây liễu xanh một thước","cn":"","category":"phap-bao","categoryLabel":"Pháp bảo","phamCap":"Không rõ","soHuu":["Liễu Thần"],"trangThai":"dang-co","blurb":"Cây liễu xanh biếc cao một thước treo trên đầu Liễu Thần khi hóa thân người, liên tục buông khí hỗn độn bảo vệ thân thể.","detail":"Cây liễu màu xanh biếc chỉ cao một thước treo lơ lửng trên đầu Liễu Thần khi hóa thành hình người, liên tục buông khí hỗn độn hộ thể.","congNang":["Buông khí hỗn độn bảo vệ thân thể"],"tabs":{"tienTrinh":[{"chuong":"@c0539","loai":"xuat hien","importance":"normal","giaiDoan":"Xuất hiện cùng Liễu Thần","text":"Treo trên đầu Liễu Thần khi hóa thân người rời hoàng cung, buông khí hỗn độn hộ thể.","anchor":"một cây liễu màu xanh biếc chỉ cao một thước treo lơ lững trên đầu nó"}]},"nguon":["@c0539"]},{"id":"bao-luan-minh-gioi","name":"Bảo luân Minh giới","cn":"宝轮冥界","category":"phap-bao","categoryLabel":"Pháp bảo","phamCap":"Không rõ","soHuu":["Hỗn độn thi"],"trangThai":"hong","blurb":"Bảo luân Minh giới là pháp khí được Hỗn độn thi triển khai để phóng tử khí trấn áp đối thủ. Trong cuộc đối đầu với Liễu Thần, bảo luân bị đánh văng ra vực ngoại.","detail":"Hỗn độn thi từng triển khai Bảo luân Minh giới, dùng pháp khí này phóng ra tử khí nhằm trấn áp. Tuy nhiên, Liễu Thần đã đánh văng bảo luân ra vực ngoại. @c0539","congNang":["Phóng tử khí để trấn áp đối thủ. @c0539"],"chuSoHuu":[{"ten":"Hỗn độn thi","tuChuong":"@c0539","denChuong":"","cachCoDuoc":"Tự tế luyện vô số năm","trangThai":"hong"}],"tabs":{"tienTrinh":[{"chuong":"@c0539","loai":"dung","importance":"major","giaiDoan":"Triển khai trong trận với Liễu Thần rồi bị phá hủy","phamCap":"Không rõ","text":"Hỗn độn thi triển khai Bảo luân Minh giới phóng tử khí trấn áp, bị Liễu Thần đánh văng ra vực ngoại rồi bị một trăm lẻ tám cành hoàng kim xuyên thủng tạo nhiều lỗ hổng.","anchor":"kể cả pháp khí cũng bị đâm xuyên tạo nên mấy lỗ hổng"}]},"nguon":["@c0539"]},{"id":"thien-kiem-bat-lao-thien-ton","name":"Thiên kiếm của Bất lão Thiên tôn","cn":"","category":"phap-bao","categoryLabel":"Pháp bảo","phamCap":"Không rõ","soHuu":["Bất lão Thiên tôn"],"trangThai":"dang-co","blurb":"Thần kiếm phóng kiếm khí bạch kim chiếu sáng trời cao, bị Liễu Thần dùng một ngón tay đánh văng.","detail":"Thần kiếm của Bất lão Thiên tôn phóng kiếm khí bạch kim soi sáng trời cao dùng để tập kích Liễu Thần, nhưng bị Liễu Thần chỉ dùng một ngón tay đánh văng, khiến người cầm kiếm phải lui lại.","congNang":["Phóng kiếm khí bạch kim sắc bén chiếu rọi trời cao"],"tabs":{"tienTrinh":[{"chuong":"@c0539","loai":"dung","importance":"normal","giaiDoan":"Tập kích Liễu Thần, bị đánh văng","text":"Bất lão Thiên tôn phóng thiên kiếm tập kích Liễu Thần nhưng bị một ngón tay đánh văng.","anchor":"Liễu Thần dùng một ngón tay đánh văng thần kiếm sáng rực kia"}]},"nguon":["@c0539"]},{"id":"toa-thap-hai-tang-dao-nhan-am-duong","name":"Tòa tháp hai tầng của đạo nhân Âm dương","cn":"","category":"phap-bao","categoryLabel":"Pháp bảo","phamCap":"Không rõ","soHuu":["Đạo nhân Âm dương"],"trangThai":"dang-co","blurb":"Tòa tháp hai tầng trắng như ngọc, treo trên đầu đạo nhân Âm dương và buông khí âm dương trấn áp thiên địa. Khi pháp bảo xuất hiện, Tiểu Tháp lập tức xông tới nghênh chiến với ý muốn đoạt lại.","detail":"Tòa tháp có cấu trúc hai tầng, toàn thân trắng như ngọc và được đạo nhân Âm dương treo trên đầu khi giao chiến. Nó buông xuống hai loại khí âm dương để trấn áp thiên địa. Tiểu Tháp từng chủ động xông tới tranh đoạt, cho thấy giữa hai bên có liên hệ trong quá khứ, nhưng quan hệ cụ thể và nguồn gốc của tòa tháp chưa được làm rõ. @c0539","congNang":["Buông hai loại khí âm dương trấn áp thiên địa. @c0539"],"chuSoHuu":[{"ten":"Đạo nhân Âm dương","tuChuong":"@c0539","denChuong":"","cachCoDuoc":"","trangThai":"bị Tiểu Tháp tranh đoạt"}],"tabs":{"tienTrinh":[{"chuong":"@c0539","loai":"xuat hien","importance":"major","giaiDoan":"Xuất hiện cùng đạo nhân Âm dương, bị Tiểu Tháp tranh đoạt","text":"Treo trên đầu đạo nhân Âm dương buông khí âm dương, Tiểu Tháp xông tới nghênh chiến muốn đoạt lại.","anchor":"tòa tháp hai tầng trên đầu buông xuống hai loại khí âm dương"}]},"nguon":["@c0539"],"uyLuc":"Khí âm dương do tòa tháp buông xuống có thể trấn áp thiên địa. @c0539","dacDiem":"Tòa tháp gồm hai tầng, trắng như ngọc và được treo trên đầu đạo nhân Âm dương. @c0539"},{"id":"luan-hoi-ban","name":"Luân Hồi Bàn","cn":"","aliases":[],"category":"than-khi","categoryLabel":"Chí bảo không trọn vẹn","phamCap":"Chí bảo không trọn vẹn","soHuu":["Bóng người mơ hồ cầm Luân Hồi Bàn"],"trangThai":"Không trọn vẹn","blurb":"Một thần bàn không trọn vẹn nhưng vẫn mang uy thế kinh người, được bóng người mơ hồ sử dụng trong cuộc tranh đoạt thân tháp hai tầng. (+) Một góc đĩa cổ được chàng trai từ hạ giới mang vào Tiên cổ và đánh thức bằng máu. [CAN-SOAT-GOP] (+) Một pháp khí liên quan tới Lục Đạo Luân Hồi Tiên vương, hiện đã vỡ thành nhiều mảnh. [CAN-SOAT-GOP]","detail":"Luân Hồi Bàn được dùng để trấn áp thân tháp và trực tiếp đối kháng Tiểu Tháp. Tiểu Tháp đặc biệt cảnh giác vì phần thân thể của mình có thể bị cuốn vào luân hồi nếu rơi vào tay người nắm giữ thần bàn.","phanLoaiPhu":"Thần bàn","uyLuc":"Dù không trọn vẹn vẫn có uy thế kinh người.","dacDiem":"Thiếu sót nghiêm trọng và có liên hệ với Sinh tử giới cùng luân hồi.","chuHienThoi":"Bóng người mơ hồ cầm Luân Hồi Bàn","congNang":["Trấn áp mục tiêu.","Có khả năng khiến sinh linh hoặc bảo vật rơi vào luân hồi."],"chuSoHuu":[{"ten":"Bóng người mơ hồ cầm Luân Hồi Bàn","tuChuong":"@c0540","denChuong":"","cachCoDuoc":"Không rõ.","trangThai":"đang sở hữu"}],"dinhDanh":"goc","capNhatToi":"@c0540","tabs":{"tienTrinh":[{"chuong":"@c0540","loai":"dùng","importance":"normal","giaiDoan":"Trấn áp thân tháp","text":"Bóng người mơ hồ lấy Luân Hồi Bàn không trọn vẹn ra để trấn áp thân tháp hai tầng và đối kháng Tiểu Tháp.","anchor":"thần bàn được lấy ra, tuy không trọn vẹn thế nhưng uy thế lại kinh người","phamCap":"Chí bảo không trọn vẹn"}]},"nguon":["@c0540","@c0969","@c1038"]},{"id":"chuong-co-chu-khong","name":"Chuông cổ chữ Không","cn":"","aliases":[],"category":"than-khi","categoryLabel":"Chí bảo","phamCap":"Chí bảo hoàn chỉnh","soHuu":["Chủ nhân chiếc chuông lớn"],"trangThai":"Đang được sử dụng","blurb":"Chiếc chuông cổ hoàn chỉnh có hai chữ trên thân, trong đó một chữ được nhìn rõ là Không. Nó được dùng để trấn áp và hút thân tháp hai tầng vào bên trong.","detail":"Sóng chuông có thể nghiền nát sao ngoài vực. Liễu Thần dùng một chưởng đánh lõm thân chuông, nhưng vết lõm nhanh chóng tự khôi phục; sau đó thần thụ xanh biếc xuyên vào miệng chuông và kéo thân tháp ra ngoài.","phanLoaiPhu":"Chuông cổ","hinhDang":"Chuông lớn cổ xưa có hai chữ trên thân, một chữ rõ ràng là Không.","uyLuc":"Sóng chuông có thể nghiền nát sao ngoài vực.","dacDiem":"Là chí bảo hoàn chỉnh và có thể tự khôi phục vết lõm do chưởng lực gây ra.","chuHienThoi":"Chủ nhân chiếc chuông lớn","congNang":["Phát sóng chuông trấn áp và nghiền nát mục tiêu.","Hút vật thể vào bên trong chuông.","Tự khôi phục vết lõm trên thân chuông."],"chuSoHuu":[{"ten":"Chủ nhân chiếc chuông lớn","tuChuong":"@c0540","denChuong":"","cachCoDuoc":"Không rõ.","trangThai":"đang sở hữu"}],"dinhDanh":"goc","capNhatToi":"@c0540","tabs":{"tienTrinh":[{"chuong":"@c0540","loai":"dùng","importance":"normal","giaiDoan":"Thu giữ thân tháp","text":"Chiếc chuông cổ hút thân tháp hai tầng vào trong, bị Liễu Thần đánh lõm rồi bị thần thụ xuyên qua miệng chuông để đoạt mất thân tháp.","anchor":"Bên trên chuông lớn xuất hiện hai chữ, một trong hai chữ đó rất rõ, chính là chữ \"Không\"","phamCap":"Chí bảo hoàn chỉnh"}]},"nguon":["@c0540"]},{"id":"than-thu-xanh-biec","name":"Thần thụ xanh biếc","cn":"","aliases":[],"category":"khac","categoryLabel":"Linh căn","phamCap":"Không rõ","soHuu":["Liễu Thần"],"trangThai":"Đang được Liễu Thần sử dụng","blurb":"Một cây nhỏ xanh biếc cao một tấc lơ lửng trên đầu Liễu Thần. Nó có thể nhanh chóng vươn ra hàng chục cành để xâm nhập pháp bảo và đoạt vật.","detail":"Trong cuộc tranh đoạt thân tháp, thần thụ vươn hàng chục cành xuyên thẳng vào miệng chiếc chuông cổ, hỗ trợ Liễu Thần cưỡng ép kéo thân tháp hai tầng ra ngoài.","phanLoaiPhu":"Thần thụ hoặc linh căn","hinhDang":"Cây nhỏ xanh biếc cao một tấc.","uyLuc":"Có thể xuyên cành vào trong một chí bảo hoàn chỉnh để tranh đoạt vật bị thu giữ.","dacDiem":"Lơ lửng trên đầu Liễu Thần và có thể nhanh chóng mọc ra hàng chục cành.","chuHienThoi":"Liễu Thần","congNang":["Vươn cành xâm nhập vào bên trong pháp bảo.","Cưỡng ép kéo vật bị thu giữ ra ngoài."],"chuSoHuu":[{"ten":"Liễu Thần","tuChuong":"@c0540","denChuong":"","cachCoDuoc":"Không rõ.","trangThai":"đang sở hữu"}],"dinhDanh":"goc","capNhatToi":"@c0540","tabs":{"tienTrinh":[{"chuong":"@c0540","loai":"dùng","importance":"normal","giaiDoan":"Xâm nhập chuông cổ","text":"Thần thụ xanh biếc mọc ra hàng chục cành xuyên vào miệng chuông, giúp Liễu Thần kéo thân tháp hai tầng ra ngoài.","anchor":"gốc cây này nhanh chóng lao ra mấy chục cành cây tiến thẳng vào trong miệng chuông.","phamCap":"Không rõ"}]},"nguon":["@c0540"]},{"id":"canh-cua-nguyen-thuy-vat-than-bi","name":"Cánh cửa nguyên thủy","cn":"","category":"khac","categoryLabel":"Vật thần bí","phamCap":"Không rõ","soHuu":["Liễu Thần"],"trangThai":"Theo Liễu Thần tiến vào hỗn độn","blurb":"Cánh cửa thần bí xuất hiện bên Liễu Thần, có thể thu nhận công kích, tinh khí và sinh linh.","detail":"Cánh cửa ngăn uy thế của sát trận thứ tư và thu nhận toàn bộ luồng sáng giết chóc lao tới. Sau khi hấp thu tinh khí người chết và một bá chủ sống, cửa phát ra tiên quang, tiếng tụng kinh cùng dao động thần bí.","phanLoaiPhu":"Cánh cửa thần bí","hinhDang":"Một cánh cửa mờ ảo được bao phủ bởi khí hỗn độn và tiên quang.","uyLuc":"Có thể khắc chế và thu nhận công kích của sát trận thứ tư.","dacDiem":"Phát ra tiên quang, tiếng tụng kinh và dao động có thể khiến người ở gần nảy sinh cảm giác ngộ đạo.","congNang":["Thu nhận các luồng sáng giết chóc của sát trận thứ tư.","Hấp thu tinh khí của người chết.","Thu nhận sinh linh bị Liễu Thần ném vào bên trong."],"chuHienThoi":"Liễu Thần","chuSoHuu":[{"ten":"Liễu Thần","tuChuong":"@c0541","denChuong":"","cachCoDuoc":"Triệu hiện trong cuộc chiến với các bá chủ thượng giới","trangThai":"Đang nắm giữ"}],"capNhatToi":"@c0541","tabs":{"tienTrinh":[{"chuong":"@c0541","loai":"dùng","importance":"normal","giaiDoan":"Chống sát trận thứ tư","phamCap":"Không rõ","text":"Cánh cửa nguyên thủy thu nhận các luồng sáng giết chóc của sát trận thứ tư, đồng thời nuốt tinh khí và một bá chủ bị Liễu Thần bắt giữ.","anchor":"Rất nhiều ánh sáng giết chóc lao thẳng tới Liễu Thần và tiểu Tháp đang đứng cạnh cánh cửa nguyên thủy kia, thế nhưng tất cả đều tiến vào bên trong cánh cửa"}]},"nguon":["@c0541"]},{"id":"xuong-nho-cua-hu-khong-thu","name":"Xương nhỏ của Hư không thú","cn":"","category":"nguyen-lieu","categoryLabel":"Vật liệu truyền tin","phamCap":"Không rõ","soHuu":[],"trangThai":"Được chế thành thư mời","blurb":"Mảnh xương quý của Hư không thú được dùng làm phong thư gửi tới Thạch Hạo.","detail":"Một con quạ mang mảnh xương đã được chế thành phong thư vào Thạch đô để chuyển lời mời Thạch Hạo tới cuộc tụ hội trên đạo sơn. Giá trị của mảnh xương được mô tả là khó ước lượng.","phanLoaiPhu":"Xương thú","vatLieu":"Xương Hư không thú","congNang":["Được chế thành phong thư truyền lời mời."],"dacDiem":"Là vật liệu có giá trị khó ước lượng.","capNhatToi":"@c0541","tabs":{"tienTrinh":[{"chuong":"@c0541","loai":"xuất hiện","importance":"normal","giaiDoan":"Thư mời dự hội","phamCap":"Không rõ","text":"Mảnh xương Hư không thú được chế thành phong thư và mang tới Thạch Hạo để mời dự cuộc tụ hội.","anchor":"Một khối xương nhỏ của Hư không thú?"}]},"nguon":["@c0541"]},{"id":"coi-xay-bac","name":"Cối xay bạc","cn":"","category":"phap-bao","categoryLabel":"Pháp bảo","phamCap":"Không rõ","soHuu":["Vị Thần mang tinh khí ngũ hành"],"trangThai":"đang sử dụng","blurb":"Pháp bảo màu bạc của vị Thần Bất Lão sơn, có thể hóa lớn và đối kháng pháp trượng màu vàng.","detail":"Cối xay bạc đánh tan minh hỏa cùng tia chớp đỏ của thần phó Minh thổ. Khi giao chiến tăng lên, nó nhanh chóng hóa lớn để trấn áp pháp trượng màu vàng.","phanLoaiPhu":"Pháp bảo chiến đấu","hinhDang":"Cối xay màu bạc có thể biến lớn","uyLuc":"Đánh tan minh hỏa, lôi điện đỏ và trực tiếp đối kháng pháp trượng màu vàng.","dacDiem":"Có thể nhanh chóng hóa lớn trong lúc giao chiến.","chuHienThoi":"Vị Thần mang tinh khí ngũ hành","congNang":["Đánh tan minh hỏa và tia chớp đỏ. @c0544","Hóa lớn để trấn áp pháp trượng của đối thủ. @c0544"],"chuSoHuu":[{"ten":"Vị Thần mang tinh khí ngũ hành","tuChuong":"@c0544","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"đang sở hữu"}],"tabs":{"tienTrinh":[{"chuong":"@c0544","loai":"dùng","importance":"normal","giaiDoan":"Đối kháng pháp trượng","text":"Vị Thần Bất Lão sơn dùng cối xay bạc đánh tan minh hỏa, tia chớp đỏ rồi hóa lớn để đối kháng pháp trượng màu vàng.","anchor":"cối xay bạc trong lòng bàn tay run bần bật rồi nhanh chóng hóa lớn","phamCap":"Không rõ"}]},"capNhatToi":"@c0544","nguon":["@c0544"]},{"id":"phap-truong-mau-vang","name":"Pháp trượng màu vàng","cn":"","category":"phap-bao","categoryLabel":"Pháp bảo","phamCap":"Không rõ","soHuu":["Thần phó xương khô có cánh"],"trangThai":"đang sử dụng","blurb":"Pháp trượng của thần phó Minh thổ, có thể phóng tia chớp đỏ và phá không công kích.","detail":"Thần phó xương khô triệu pháp trượng màu vàng trong cuộc giao chiến với vị Thần Bất Lão sơn. Pháp trượng phóng tia chớp đỏ, sau đó rời tay phá không để va chạm trực tiếp với cối xay bạc.","phanLoaiPhu":"Pháp bảo chiến đấu","hinhDang":"Pháp trượng màu vàng","uyLuc":"Có thể đối kháng trực tiếp cối xay bạc của vị Thần Bất Lão sơn.","dacDiem":"Phóng tia chớp đỏ và có thể tự phá không lao tới.","chuHienThoi":"Thần phó xương khô có cánh","congNang":["Phóng tia chớp đỏ để công kích. @c0544","Phá không bay khỏi tay và va chạm trực tiếp với pháp bảo đối phương. @c0544"],"chuSoHuu":[{"ten":"Thần phó xương khô có cánh","tuChuong":"@c0544","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"đang sở hữu"}],"tabs":{"tienTrinh":[{"chuong":"@c0544","loai":"dùng","importance":"normal","giaiDoan":"Đối kháng cối xay bạc","text":"Thần phó Minh thổ dùng pháp trượng phóng tia chớp đỏ rồi phá không va chạm với cối xay bạc.","anchor":"pháp trượng màu vàng trong tay phá không bay đi va chạm với cối xay bạc","phamCap":"Không rõ"}]},"capNhatToi":"@c0544","nguon":["@c0544"]},{"id":"thien-cot-cua-thach-hao","name":"Thiên cốt của Thạch Hạo","cn":"","category":"khac","categoryLabel":"Bảo cốt","phamCap":"Không rõ","soHuu":["Thạch Hạo"],"trangThai":"đang sở hữu","blurb":"Khối thiên cốt trong cơ thể Thạch Hạo, trở thành mục tiêu tranh đoạt của nhiều thế lực thượng giới. Bảo thuật phát động từ cốt có thể khiến nhiều mục tiêu nhanh chóng già yếu.","detail":"Minh thổ, Bất Lão sơn và Ma Quỳ viên đều tranh quyền xử trí Thạch Hạo vì thiên cốt. Khi Thạch Hạo tế cốt và triển khai bảo thuật, ba truyền nhân trẻ tuổi đồng thời bị bao phủ, tóc bạc và suy kiệt.","phanLoaiPhu":"Bảo cốt","nguonGoc":"Trong cơ thể Thạch Hạo","uyLuc":"Phát động bảo thuật bao phủ đồng thời ba truyền nhân thượng giới và khiến họ già yếu.","dacDiem":"Có tiềm lực chiến lược khiến nhiều thế lực thượng giới muốn chiêu dụ hoặc đoạt lấy.","chuHienThoi":"Thạch Hạo","congNang":["Phát động bảo thuật khiến mục tiêu nhanh chóng già yếu và suy kiệt. @c0544"],"chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c0544","denChuong":"","cachCoDuoc":"Nằm trong cơ thể","trangThai":"đang sở hữu"}],"tabs":{"tienTrinh":[{"chuong":"@c0544","loai":"dùng","importance":"normal","giaiDoan":"Phát động bảo thuật","text":"Thạch Hạo tế thiên cốt, triển khai bảo thuật bao phủ ba truyền nhân và khiến họ nhanh chóng già yếu.","anchor":"tế thiên cốt của mình ra, triển khai bảo thuật, trong nháy mắt công kích bắt đầu bao phủ","phamCap":"Không rõ"}]},"capNhatToi":"@c0544","nguon":["@c0544"]},{"id":"hat-huong-duong-ma-quy","name":"Hạt hướng dương Ma quỳ","cn":"","category":"dan-duoc","categoryLabel":"Linh dược tự nhiên","phamCap":"Không rõ","soHuu":["Thạch Hạo"],"trangThai":"đang được Thạch Hạo thu giữ","blurb":"Hạt của Ma quỳ có vỏ đen bóng, nhân trắng và chứa lượng thần lực dồi dào.","detail":"Thạch Hạo ăn thử và xác nhận chỉ ba đến bốn hạt đã có thể nhanh chóng bổ sung đầy đủ tinh khí tiêu hao. Sau đó, hắn thu thêm toàn bộ hạt của cây Ma quỳ đã nhen nhóm Thần hỏa.","phanLoaiPhu":"Hạt linh dược","hinhDang":"Hạt vỏ đen bóng, bên trong có nhân trắng","uyLuc":"Ba đến bốn hạt có thể nhanh chóng bổ sung đầy đủ tinh khí đã tiêu hao.","dacDiem":"Có mùi thơm và chứa nhiều thần lực.","chuHienThoi":"Thạch Hạo","congNang":["Nhanh chóng bổ sung tinh khí đã tiêu hao."],"chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c0545","denChuong":"","cachCoDuoc":"Lấy từ cô gái áo đen và cây Ma quỳ đã nhen nhóm Thần hỏa.","trangThai":"đang giữ"}],"tabs":{"tienTrinh":[{"chuong":"@c0545","loai":"xuất hiện","importance":"normal","giaiDoan":"Phát hiện công dụng","phamCap":"Không rõ","text":"Thạch Hạo ăn thử hạt Ma quỳ và phát hiện chỉ vài hạt đã có thể nhanh chóng bổ sung tinh khí.","anchor":"chỉ cần ba tới bốn hạt là có thể nhanh chóng bổ sung đầy đủ tinh khí"}]},"capNhatToi":"@c0545","nguon":["@c0545"]},{"id":"dinh-than-phu","name":"Định thần phù","cn":"","category":"khac","categoryLabel":"Phù lục","phamCap":"Bí phù thượng cổ","soHuu":["Thạch Hạo"],"trangThai":"Đã cháy thành tro","blurb":"Tấm phù ố vàng được truyền tụng là có thể cố định thần linh.","detail":"Thạch Hạo ném Định thần phù về phía cây dây nho xanh. Tấm phù chỉ đốt cháy một đoạn dây leo cùng vài chiếc lá rồi hóa thành tro, không thể làm tổn thương chủ thể.","hinhDang":"Tấm phù ố vàng","dacDiem":"Vật phẩm dùng một lần và cháy thành tro sau khi kích hoạt.","congNang":["Được truyền tụng là có thể cố định thần linh.","Tấm phù được sử dụng chỉ đốt cháy một đoạn dây leo và vài chiếc lá."],"chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c0546","denChuong":"@c0546","cachCoDuoc":"Thuộc số bảo vật chủ thân Nguyệt Thiền từng đánh mất.","trangThai":"Đã sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c0546","loai":"dùng","importance":"normal","giaiDoan":"Thiêu cháy rồi hóa tro","text":"Thạch Hạo tung Định thần phù vào cây dây nho, nhưng phù chỉ đốt một phần dây lá rồi cháy thành tro.","anchor":"trong tay xuất hiện một tấm phù ố vàng đánh về bên dưới","phamCap":"Bí phù thượng cổ"}]},"capNhatToi":"@c0546","nguon":["@c0546"]},{"id":"pha-khong-phu","name":"Phá không phù","cn":"","category":"khac","categoryLabel":"Phù lục","phamCap":"Không rõ","soHuu":["Cường giả Thần hỏa"],"trangThai":"Đã sử dụng","blurb":"Lá phù được người của Tiên điện chuẩn bị nhằm cưỡng ép đưa Thạch Hạo ra khỏi Quang Minh thành. (+) Phù lục đào thoát có thể đưa người sử dụng chạy xa vạn dặm. [CAN-SOAT-GOP]","detail":"Một cường giả Thần hỏa sử dụng Phá không phù để rời xa chiến trường, nhưng vẫn bị bàn tay vàng của Sinh linh Bất diệt giam cầm và bắt trở lại.","congNang":["Phá không đưa người sử dụng đào thoát xa vạn dặm."],"chuSoHuu":[{"ten":"Cường giả Thần hỏa","tuChuong":"@c0546","denChuong":"@c0546","cachCoDuoc":"","trangThai":"Đã sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c0546","loai":"dùng","importance":"normal","giaiDoan":"Đào thoát thất bại","text":"Một cường giả dùng Phá không phù chạy xa vạn dặm nhưng vẫn bị Sinh linh Bất diệt bắt lại.","anchor":"một người trong số đó sớm đã vận dụng một tấm Phá không phù","phamCap":"Không rõ"}]},"capNhatToi":"@c0546","nguon":["@c0546","@c0827"]},{"id":"tran-dai-dao-thoat","name":"Trận đài đào thoát","cn":"","category":"phap-bao","categoryLabel":"Trận đài","phamCap":"Không rõ","soHuu":["Các cường giả Thần hỏa"],"trangThai":"Đã sử dụng","blurb":"Trận đài phá không được các chân thân Thần hỏa dùng để giữ mạng.","detail":"Khi các linh thân bị cố định, những chân thân Thần hỏa đồng loạt lấy trận đài ra và phá không rời đi. Bàn tay vàng của Sinh linh Bất diệt vẫn ép họ hiện thân rồi bắt trở lại.","congNang":["Phá không đưa người sử dụng nhanh chóng rời chiến trường."],"chuSoHuu":[{"ten":"Các cường giả Thần hỏa","tuChuong":"@c0546","denChuong":"@c0546","cachCoDuoc":"","trangThai":"Đã sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c0546","loai":"dùng","importance":"normal","giaiDoan":"Phá không giữ mạng","text":"Các chân thân Thần hỏa dùng trận đài phá không bỏ trốn nhưng vẫn bị bắt lại.","anchor":"tất cả đều lấy ra trận dài, chớp mắt đã phá không rời đi xa","phamCap":"Không rõ"}]},"capNhatToi":"@c0546","nguon":["@c0546"]},{"id":"kim-dan-mau-tim-cua-cay-day-nho","name":"Kim đan màu tím của cây dây nho","cn":"","category":"phap-bao","categoryLabel":"Vật phẩm công kích","phamCap":"Không rõ","soHuu":["Cây dây nho xanh"],"trangThai":"Không rõ","blurb":"Viên kim đan màu tím được cây dây nho dùng để truy kích Thạch Hạo.","detail":"Kim đan bay như một quả cầu ánh sáng, liên tục bùng nổ phù văn và đánh tan mây nhằm ngăn Thạch Hạo né khỏi vòng vây.","hinhDang":"Viên cầu ánh sáng màu tím","congNang":["Phóng ánh tím và làm nổ phù văn để công kích mục tiêu."],"chuSoHuu":[{"ten":"Cây dây nho xanh","tuChuong":"@c0546","denChuong":"","cachCoDuoc":"","trangThai":"Sử dụng trong chiến đấu"}],"tabs":{"tienTrinh":[{"chuong":"@c0546","loai":"dùng","importance":"normal","giaiDoan":"Truy kích Thạch Hạo","text":"Cây dây nho điều khiển kim đan tím truy kích và chặn đường né tránh của Thạch Hạo.","anchor":"một viên kim đan màu tím cứ như là quả cầu ánh sáng bay tới","phamCap":"Không rõ"}]},"capNhatToi":"@c0546","nguon":["@c0546"]},{"id":"hon-don-bao-giam","name":"Hỗn độn bảo giám","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Kỳ bảo","phanLoaiPhu":"Mảnh vỡ","phamCap":"Không rõ","soHuu":["Sinh linh Bất diệt"],"trangThai":"Mảnh vỡ đang được sử dụng","hinhDang":"Mảnh tinh phiến trắng bóng, óng ánh như ngọc.","nguonGoc":"Mảnh kỳ bảo do Liễu Thần đưa ra.","blurb":"Một mảnh vỡ của Hỗn độn bảo giám được Sinh linh Bất diệt dùng để tìm kiếm những cường giả thượng giới ẩn náu trong tám vực.","detail":"Bản hoàn chỉnh được mô tả có thể quan sát trời đất và cửu thiên thập địa. Mảnh vỡ hiện có vẫn đủ sức soi chiếu tám vực và dò tìm sinh linh đã nhen nhóm Thần hỏa, nhưng khó tìm kiếm những cơ duyên có tính thông linh.","uyLuc":"Có thể hỗ trợ thanh tra phạm vi rộng khắp tám vực.","dacDiem":"Chỉ là một mảnh vỡ nhưng vẫn giữ năng lực dò tìm sinh linh mạnh mẽ.","chuHienThoi":"Sinh linh Bất diệt","congNang":["Soi chiếu tám vực và dò tìm những sinh linh đã nhen nhóm Thần hỏa."],"chuSoHuu":[{"ten":"Sinh linh Bất diệt","tuChuong":"@c0547","denChuong":"","cachCoDuoc":"Nhận mảnh kỳ bảo do Liễu Thần đưa ra.","trangThai":"Đang sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c0547","loai":"dùng","importance":"normal","giaiDoan":"Dò tìm thần linh trong tám vực","text":"Sinh linh Bất diệt khống chế mảnh Hỗn độn bảo giám để tìm những sinh linh đã nhen nhóm Thần hỏa đang ẩn náu.","anchor":"Sinh linh Bất diệt khống chế miếng tinh phiến trắng bóng này, tìm kiếm sinh linh đã nhen nhóm Thần hỏa","phamCap":"Mảnh vỡ"}]},"dinhDanh":"goc","capNhatToi":"@c0547","nguon":["@c0547"]},{"id":"chien-xa-hoang-cung-thach-quoc","name":"Chiến xa hoàng cung Thạch quốc","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Chí bảo phi hành","phamCap":"Chí bảo","soHuu":["Hoàng cung Thạch quốc","Thạch Hạo"],"trangThai":"Đang sử dụng","blurb":"Chiến xa phi hành thuộc hoàng cung Thạch quốc, được Thạch Hạo dùng để chuyên chở đoàn người.","detail":"Chiến xa có thể bay nhanh như tia chớp, đưa Thạch Hạo và các đồng môn tới học viện Trục Lộc rồi tiến về Thác Bạt gia.","phanLoaiPhu":"Pháp bảo chuyên chở","congNang":["Phi hành với tốc độ nhanh như tia chớp.","Chuyên chở nhiều người giữa các địa điểm."],"dacDiem":"Là chí bảo của hoàng cung Thạch quốc.","chuHienThoi":"Hoàng cung Thạch quốc","chuSoHuu":[{"ten":"Hoàng cung Thạch quốc","tuChuong":"@c0549","denChuong":"","cachCoDuoc":"Chí bảo thuộc hoàng cung","trangThai":"Sở hữu"},{"ten":"Thạch Hạo","tuChuong":"@c0549","denChuong":"","cachCoDuoc":"Điều khiển để di chuyển","trangThai":"Đang sử dụng"}],"capNhatToi":"@c0549","tabs":{"tienTrinh":[{"chuong":"@c0549","loai":"dùng","importance":"normal","giaiDoan":"Chuyên chở đoàn người","text":"Thạch Hạo điều khiển chiến xa đưa đoàn người tới học viện Trục Lộc rồi tiến về Thác Bạt gia.","phamCap":"Chí bảo","anchor":"Mọi người phân tách, với thủ đoạn hiện tại của Thạch Hạo thì có thể nhanh chóng rời đi, nó điều khiển một chiếc chiến xa, đây chính là chí bảo của hoàng cung Thạch quốc, có thể bay nhanh như tia chớp."}]},"nguon":["@c0549"]},{"id":"phap-kiem-than-linh-cua-thach-quoc","name":"Pháp kiếm thần linh của Thạch quốc","cn":"","category":"than-khi","categoryLabel":"Thần khí","phamCap":"Cấp thần linh","soHuu":["Thạch Hạo","Thạch quốc"],"trangThai":"Còn nguyên","blurb":"Thần kiếm của Thạch quốc được Thạch Hạo sử dụng trong cuộc công phá Thác Bạt tộc.","detail":"Pháp kiếm xé mở đại trận Tinh đấu, nghiền ép vật cản, chém chết lão tổ Thác Bạt và được Thạch Hạo thu hồi sau trận.","phanLoaiPhu":"Pháp kiếm","chuHienThoi":"Thạch Hạo","congNang":["Phá trận và phát kiếm khí công kích mục tiêu. @c0550"],"uyLuc":"Phá đại trận Tinh đấu và chém lão tổ Thác Bạt thành ánh sáng.","chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c0550","denChuong":"","cachCoDuoc":"Thần khí của Thạch quốc được sử dụng khi công phá Thác Bạt tộc.","trangThai":"đang giữ"}],"capNhatToi":"@c0550","tabs":{"tienTrinh":[{"chuong":"@c0550","loai":"dùng","importance":"normal","giaiDoan":"Công phá Thác Bạt","phamCap":"Cấp thần linh","text":"Thạch Hạo dùng pháp kiếm phá đại trận Tinh đấu và chém chết lão tổ Thác Bạt.","anchor":"pháp kiếm thần linh mà nó cầm trong tay chém thẳng về trước"}]},"nguon":["@c0550"]},{"id":"muoi-tam-vien-cot-chau","name":"Mười tám viên cốt châu","cn":"","category":"phap-bao","categoryLabel":"Bộ pháp khí","phamCap":"Không rõ","soHuu":["Tam hắc"],"trangThai":"Nguyên vẹn","blurb":"Bộ mười tám cốt châu xanh biếc do Tam hắc sử dụng trong trận chiến với Thạch Hạo.","detail":"Các viên cốt châu được phóng ra trong luồng ánh đen hóa thành đầm nước, đồng loạt phát sáng để tạo thế trấn áp đối thủ. Tam hắc thu lại chúng sau khi đầu hàng.","phanLoaiPhu":"Bộ gồm mười tám viên","hinhDang":"Mười tám viên cốt châu xanh biếc óng ánh","congNang":["Đồng loạt phát sáng và phối hợp tạo thế trấn áp đối thủ."],"chuHienThoi":"Tam hắc","chuSoHuu":[{"ten":"Tam hắc","tuChuong":"@c0551","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"Đang sở hữu"}],"tabs":{"tienTrinh":[{"chuong":"@c0551","loai":"dùng","importance":"normal","giaiDoan":"Giao chiến với Thạch Hạo","text":"Tam hắc phóng mười tám viên cốt châu để phối hợp trấn áp Thạch Hạo rồi thu lại khi đầu hàng.","anchor":"bên trong có mười tám viên cốt châu xanh biếc óng ánh cùng phát sáng","phamCap":"Không rõ"}]},"capNhatToi":"@c0551","nguon":["@c0551"]},{"id":"chien-xa-than-khi","name":"Chiến xa thần khí","cn":"","category":"than-khi","categoryLabel":"Thần khí","phamCap":"Thần khí","soHuu":["Thạch Hạo"],"trangThai":"Nguyên vẹn","blurb":"Chiến xa cấp thần khí được Thạch Hạo dùng làm phương tiện vượt biển sương mù tại Thần sơn Nam Vẫn.","detail":"Thạch Hạo lấy chiến xa ra để chở đoàn người di chuyển trong biển sương mù dày đặc của Nam Vẫn.","congNang":["Chuyên chở người và di chuyển trong biển sương mù Nam Vẫn."],"chuHienThoi":"Thạch Hạo","chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c0551","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"Đang sở hữu"}],"tabs":{"tienTrinh":[{"chuong":"@c0551","loai":"dùng","importance":"normal","giaiDoan":"Vượt biển sương mù","text":"Thạch Hạo dùng chiến xa thần khí đưa đoàn người di chuyển qua biển sương mù của Nam Vẫn.","anchor":"Thạch Hạo lấy ra chiến xa, đây là thần khí nên di chuyển trong biển sương mù này","phamCap":"Thần khí"}]},"capNhatToi":"@c0551","nguon":["@c0551"]},{"id":"hoang-van-thach","name":"Hoàng Văn Thạch","cn":"","aliases":[],"category":"nguyen-lieu","categoryLabel":"Luyện khí thần liệu","phamCap":"Chí bảo hiếm gặp tại thượng giới","soHuu":["Thạch Hạo"],"trangThai":"dang-co","blurb":"Hoàng Văn Thạch là khối thần liệu đỏ đậm, có những vết giống lông phượng hoàng, được Nam Vẫn tặng cho Thạch Hạo. Vật liệu cực hiếm này có thể giúp bảo cụ lột xác hoặc niết bàn khi dung hợp.","detail":"Nam Vẫn tặng cho Thạch Hạo một khối Hoàng Văn Thạch cỡ nắm tay để dung hợp với chiến y Bất Diệt Kim Thân. Đây là vật liệu cực kỳ hiếm, có giá trị lớn và được xem là chí bảo khó tìm ngay cả tại thượng giới.","phanLoaiPhu":"Luyện khí thần liệu","hinhDang":"Khối đá đỏ đậm cỡ nắm tay, có vết giống lông phượng hoàng","uyLuc":"Có thể hỗ trợ bảo cụ lột xác hoặc niết bàn khi dung hợp.","dacDiem":"Khối thần liệu cỡ nắm tay, màu đỏ đậm, có những vết giống lông phượng hoàng; cực hiếm và có giá trị lớn ngay cả tại thượng giới.","chuHienThoi":"Thạch Hạo","capNhatToi":"@c0552","congNang":["Dung hợp với bảo cụ để giúp bảo cụ lột xác hoặc niết bàn @c0552"],"chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c0552","denChuong":"","cachCoDuoc":"Được Nam Vẫn tặng","trangThai":"dang-co"}],"tabs":{"tienTrinh":[{"chuong":"@c0552","loai":"đổi chủ","importance":"major","giaiDoan":"Được trao cho Thạch Hạo","phamCap":"Chí bảo hiếm gặp tại thượng giới","text":"Nam Vẫn tặng Hoàng Văn Thạch cho Thạch Hạo để dung hợp với chiến y Bất Diệt Kim Thân.","anchor":"chỗ ta có một khối Hoàng Văn Thạch, thôi thì tặng cho tiểu hữu để dung hợp với chiến y này."}]},"nguon":["@c0552"]},{"id":"tinh-thach-ghi-hinh-dai-kiep","name":"Tinh thạch ghi hình đại kiếp","cn":"","aliases":[],"category":"khac","categoryLabel":"Vật phẩm lưu ảnh","phamCap":"Không rõ","soHuu":["Nam Vẫn"],"trangThai":"dang-co","blurb":"Tinh thạch đặc biệt do Nam Vẫn sử dụng để tái hiện hình ảnh đại kiếp năm xưa.","detail":"Nam Vẫn lấy tinh thạch ra cho đoàn người xem toàn bộ hình ảnh đại kiếp, qua đó xác nhận số phận của cường giả Thần sơn từng tấn công Bổ Thiên các.","chuHienThoi":"Nam Vẫn","capNhatToi":"@c0552","congNang":["Ghi giữ và tái hiện hình ảnh của đại kiếp @c0552"],"chuSoHuu":[{"ten":"Nam Vẫn","tuChuong":"@c0552","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"dang-co"}],"tabs":{"tienTrinh":[{"chuong":"@c0552","loai":"dùng","importance":"normal","giaiDoan":"Tái hiện đại kiếp","text":"Nam Vẫn dùng tinh thạch cho đoàn người xem hình ảnh đại kiếp năm đó.","anchor":"rồi lấy ra một tinh thạch đặc biệt ghi lại toàn bộ hình ảnh của đại kiếp nạn năm đó."}]},"nguon":["@c0552"]},{"id":"thiem-dien-qua","name":"Thiểm Điện quả","cn":"","aliases":[],"category":"dan-duoc","categoryLabel":"Bảo dược","phanLoaiPhu":"Quả của Thiểm Điện thụ","phamCap":"Không rõ","soHuu":["Tam hắc","Thạch Hạo"],"chuHienThoi":"Nhóm Thạch Hạo","trangThai":"Chưa sử dụng","hinhDang":"Quả phát sáng như mặt trời nhỏ và có tia điện lượn lờ.","blurb":"Quả kết trên Thiểm Điện thụ trong Tây Lăng Giới. Tam hắc lấy được bốn quả sau khi kinh động đàn Thiểm Điện trùng.","detail":"Thiểm Điện quả được cho là có thể giúp người ăn phát ra thiểm điện và, nếu đủ vận may, lĩnh ngộ pháp tắc Lôi Đình. Do được lấy từ một thế giới nửa hư nửa thật, cả nhóm chưa xác định chúng có thể ăn hay không.","congNang":["Có thể giúp người ăn phát ra thiểm điện.","Người có đủ vận may có khả năng nắm giữ pháp tắc Lôi Đình."],"dacDiem":"Phát sáng mạnh và tỏa ra những tia chớp.","chuSoHuu":[{"ten":"Tam hắc","tuChuong":"@c0553","denChuong":"","cachCoDuoc":"Hái bốn quả từ Thiểm Điện thụ.","trangThai":"Đã lấy được"}],"capNhatToi":"@c0553","tabs":{"tienTrinh":[{"chuong":"@c0553","loai":"xuất hiện","importance":"normal","giaiDoan":"Bốn quả được lấy khỏi cây","text":"Tam hắc hái bốn Thiểm Điện quả và kinh động đàn Thiểm Điện trùng bảo vệ cây. Sau khi thoát nạn, cả nhóm chưa xác định những quả lấy từ Tây Lăng Giới có thể ăn hay không.","anchor":"Vật này có thể ăn không? Mọi người đồng thời nhìn về mấy viên Thiểm Điện quả.","phamCap":"Không rõ"}]},"nguon":["@c0553"]},{"id":"hat-ma-quy","name":"Hạt Ma Quỳ","cn":"","category":"dan-duoc","categoryLabel":"Dược vật","phamCap":"Không rõ","soHuu":["Thạch Hạo","Tam hắc"],"trangThai":"Đã sử dụng","blurb":"Dược vật của Ma Quỳ viên có khả năng nhanh chóng bổ sung thần lực và chữa trị thương thế.","detail":"Thạch Hạo ăn ba bốn hạt rồi đưa Tam hắc bốn năm hạt sau khi cả hai trốn vào hộp quý đồng thau. Dược lực khiến toàn thân họ phát sáng, thần lực phục hồi và thương thế nhanh chóng ổn định.","nguonGoc":"Ma Quỳ viên tại thượng giới","congNang":["Bổ sung thần lực và nhanh chóng chữa trị thương thế.","Bổ sung thần năng đã tiêu hao."],"chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c0555","denChuong":"@c0577","cachCoDuoc":"Không rõ","trangThai":"Đã dùng"},{"ten":"Tam hắc","tuChuong":"@c0555","denChuong":"","cachCoDuoc":"Được Thạch Hạo đưa bốn năm hạt","trangThai":"Đã sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c0555","loai":"dùng","importance":"normal","giaiDoan":"Chữa thương","text":"Thạch Hạo và Tam hắc dùng hạt Ma Quỳ để khôi phục thần lực và chữa thương trong hộp quý đồng thau.","anchor":"trong phút chốc toàn thân nó phát sáng, thần lực mãnh liệt, nhanh chóng chữa trị thương thế","phamCap":"Không rõ"},{"chuong":"@c0577","loai":"dùng","importance":"normal","giaiDoan":"Bổ sung thần năng","text":"Thạch Hạo dùng hạt Ma quỳ để duy trì thần năng trong cuộc chạy trốn kéo dài.","anchor":"trong lúc ấy thì Thạch Hạo lấy hạt Ma quỳ để bổ sung thần năng","phamCap":"Không rõ"}]},"capNhatToi":"@c0555","nguon":["@c0555","@c0577"]},{"id":"xuong-so-thuy-tinh","name":"Xương sọ thủy tinh","cn":"","category":"nguyen-lieu","categoryLabel":"Dị cốt","phamCap":"Không rõ","soHuu":[],"trangThai":"Rút lui vào Tây Lăng","blurb":"Dị cốt trong suốt trên tế đàn Tây Lăng, có khả năng uy hiếp linh hồn và cắn phá hộp quý đồng thau.","detail":"Xương sọ thủy tinh khiến người nhìn vào hốc mắt có cảm giác linh hồn muốn lìa khỏi xác. Nó truy đuổi Thạch Hạo, há miệng cắn hộp quý đồng thau và chỉ rút lui sau khi Vạn Linh đồ tự hiển hóa.","phanLoaiPhu":"Dị cốt","hinhDang":"Xương sọ trong suốt như thủy tinh","uyLuc":"Có thể uy hiếp tiểu thế giới bên trong hộp quý đồng thau.","dacDiem":"Hốc mắt gây cảm giác linh hồn muốn lìa khỏi thể xác.","congNang":["Uy hiếp linh hồn của sinh linh nhìn vào hốc mắt.","Há miệng cắn phá hộp quý đồng thau."],"tabs":{"tienTrinh":[{"chuong":"@c0555","loai":"dùng","importance":"normal","giaiDoan":"Cắn phá hộp báu","text":"Xương sọ thủy tinh truy đuổi rồi cắn xé hộp quý đồng thau cho đến khi Vạn Linh đồ phát uy.","anchor":"một xương sọ như thủy tinh đang há miệng cắn xé hộp báu đồng thau này","phamCap":"Không rõ"}]},"capNhatToi":"@c0555","nguon":["@c0555"]},{"id":"trong-mat-dinh-mau","name":"Tròng mắt dính máu","cn":"","category":"khac","categoryLabel":"Dị vật","phamCap":"Không rõ","soHuu":[],"trangThai":"Còn tại Tây Lăng","blurb":"Tròng mắt không thuộc loài người, còn dính máu tươi và có thể chuyển động để nhìn chằm chằm vào linh hồn.","detail":"Sau khi mảnh chân cốt bị lấy khỏi tế đàn, tròng mắt dính máu chuyển động nhìn về phía Thạch Hạo và Tam hắc. Ánh nhìn của nó khiến cả hai cảm thấy linh hồn bị canh chừng và có thể bị tiêu diệt.","phanLoaiPhu":"Dị vật","hinhDang":"Tròng mắt lớn còn dính máu","dacDiem":"Máu tươi vẫn chưa khô dù đã trải qua thời gian dài.","congNang":["Chuyển động quan sát và gây uy hiếp trực tiếp tới linh hồn."],"tabs":{"tienTrinh":[{"chuong":"@c0555","loai":"xuất hiện","importance":"normal","giaiDoan":"Thức tỉnh trên tế đàn","text":"Tròng mắt dính máu chuyển động nhìn Thạch Hạo và Tam hắc sau khi mảnh chân cốt bị lấy đi.","anchor":"viên tròng mắt đầy máu ở bên cạnh lại chuyển động nhìn về phía nó","phamCap":"Không rõ"}]},"capNhatToi":"@c0555","nguon":["@c0555"]},{"id":"te-dan-co-bat-lao-son","name":"Tế đàn cổ Bất Lão sơn","cn":"","category":"khac","categoryLabel":"Tế đàn","phamCap":"Không rõ","soHuu":["Bất Lão sơn"],"trangThai":"Đã được tái thiết và đang phát sáng","blurb":"Tế đàn cổ nằm sâu trong Bất Lão sơn, được xây dựng lại để duy trì liên hệ với thượng giới. Khi Tần Hạo ngồi trên tế đàn, nó phát sáng và tẩm bổ bảo cốt vô thượng trong cơ thể hắn.","detail":"Tế đàn cổ của Bất Lão sơn từng được dọn dẹp và xây dựng lại. Sau khi khai phong, tế đàn phát sáng, vừa dùng để liên hệ với thượng giới, vừa tẩm bổ bảo cốt vô thượng trong cơ thể Tần Hạo. @c0556","phanLoaiPhu":"Tế đàn liên giới","nguonGoc":"Bất Lão sơn","uyLuc":"Có thể đồng thời duy trì liên hệ với thượng giới và tẩm bổ bảo cốt vô thượng trong cơ thể Tần Hạo. @c0556","dacDiem":"Tế đàn cổ thuộc Bất Lão sơn, phát sáng khi Tần Hạo ngồi tại đó. @c0556","chuHienThoi":"Bất Lão sơn","congNang":["Liên hệ với thượng giới. @c0556","Tẩm bổ bảo cốt vô thượng trong cơ thể Tần Hạo. @c0556"],"chuSoHuu":[{"ten":"Bất Lão sơn","tuChuong":"@c0556","denChuong":"","cachCoDuoc":"Được đặt trong khu vực trọng yếu của Bất Lão sơn","trangThai":"đang quản lý"}],"capNhatToi":"@c0556","tabs":{"tienTrinh":[{"chuong":"@c0556","loai":"khai phong","importance":"major","giaiDoan":"Khôi phục liên hệ thượng giới","text":"Tế đàn cổ được xây dựng lại và phát sáng, vừa liên hệ thượng giới vừa tẩm bổ bảo cốt trong cơ thể Tần Hạo.","anchor":"có thể liên hệ với thượng giới, tẩm bổ bảo cốt vô thượng trong cơ thể của Tần Hạo","phamCap":"Không rõ"}]},"nguon":["@c0556"]},{"id":"to-te-dan-thach-quoc","name":"Tổ tế đàn Thạch quốc","cn":"","category":"khac","categoryLabel":"Tế đàn truyền tống","phamCap":"Không rõ","soHuu":["Thạch quốc"],"trangThai":"Có thể sử dụng","blurb":"Tế đàn truyền tống của Thạch quốc có khả năng phá không và đưa người vượt qua quãng đường xa.","detail":"Thạch Hạo mở tổ tế đàn, mang theo Huyền Quy rời Thạch quốc và tiến tới Huyền vực để tìm Tần Hạo.","phanLoaiPhu":"Tế đàn phá không","nguonGoc":"Thạch quốc","uyLuc":"Có thể phá không di chuyển qua quãng đường dài và vượt sang vực khác.","chuHienThoi":"Thạch quốc","congNang":["Phá không để di chuyển đường dài."],"chuSoHuu":[{"ten":"Thạch quốc","tuChuong":"@c0556","denChuong":"","cachCoDuoc":"Tế đàn thuộc Thạch quốc","trangThai":"đang quản lý"}],"capNhatToi":"@c0556","tabs":{"tienTrinh":[{"chuong":"@c0556","loai":"dùng","importance":"normal","giaiDoan":"Đưa Thạch Hạo tới Huyền vực","text":"Thạch Hạo mở tổ tế đàn, mang Huyền Quy phá không rời đi và tiến về phía Bất Lão sơn.","anchor":"mở ra tổ tế đàn phá không rời đi","phamCap":"Không rõ"}]},"nguon":["@c0556"]},{"id":"khoi-cot-than-bi-bat-lao-son","name":"Khối cốt thần bí của Bất Lão sơn","cn":"","aliases":[],"category":"khac","categoryLabel":"Tiên cốt nghi vấn","phanLoaiPhu":"Khối cốt còn hoạt tính","phamCap":"Chưa xác định, được suy đoán là Trường Sinh cốt hoặc Tiên cốt","soHuu":["Bất Lão Thiên Tôn"],"trangThai":"Đang được nuôi cấy trong Tần Hạo qua hình chiếu","blurb":"Khối cốt thần bí được Bất Lão Thiên Tôn lấy từ một tế đàn cổ trong khu vực không người thần bí. Trải qua vô số năm, nó vẫn duy trì hoạt tính và máu tươi, đồng thời được dùng để nuôi dưỡng Tần Hạo từ khi còn là phôi thai. Nếu hoàn toàn phát uy, khối cốt có thể lập tức tiêu diệt cả Bất Lão Thiên Tôn.","detail":"Bất Lão Thiên Tôn lấy khối cốt từ một tế đàn cổ trong khu vực không người thần bí rồi dùng nó trong kế hoạch bồi dưỡng Tần Hạo. Máu trên khối cốt được luyện vào Tần Hạo từ khi hắn còn là phôi thai, có tác dụng tẩm bổ huyết nhục và xương cốt. Hình chiếu của khối cốt được cấy vào ngực hắn mỗi ngày, giao hòa với cơ thể và dần từ hư hóa thực, nhằm chuẩn bị cho việc cấy bản thể; đến khi nguồn gốc và kế hoạch nuôi cấy được hé lộ, quá trình này đã gần hoàn thành. Khối cốt còn ẩn chứa cốt văn mà ngay cả Bất Lão Thiên Tôn cũng chưa thể thăm dò. @c0557","hinhDang":"Một khối cốt còn tơ máu","nguonGoc":"Được Bất Lão Thiên Tôn lấy từ tế đàn cổ trong khu vực không người thần bí","uyLuc":"Nếu hoàn toàn phát uy, khối cốt có thể lập tức tiêu diệt cả Bất Lão Thiên Tôn.","dacDiem":"Duy trì hoạt tính và máu tươi qua vô số năm, thần công cũng khó làm tổn hại.","chuHienThoi":"Bất Lão Thiên Tôn","congNang":["Tẩm bổ huyết nhục và xương cốt của Tần Hạo.","Dùng hình chiếu giao hòa với cơ thể Tần Hạo, dần từ hư hóa thực để chuẩn bị cho việc cấy bản thể. @c0557","Ẩn chứa cốt văn mà Bất Lão Thiên Tôn chưa thể thăm dò."],"chuSoHuu":[{"ten":"Bất Lão Thiên Tôn","tuChuong":"@c0557","denChuong":"","cachCoDuoc":"Cửu tử nhất sinh lấy từ tế đàn cổ trong khu vực không người","trangThai":"đang nắm giữ bản thể"},{"ten":"Tần Hạo","tuChuong":"@c0557","denChuong":"","cachCoDuoc":"Được cấy máu và hình chiếu của khối cốt từ khi còn là phôi thai","trangThai":"đang thích ứng"}],"capNhatToi":"@c0557","tabs":{"tienTrinh":[{"chuong":"@c0557","loai":"khai phong","importance":"major","giaiDoan":"Hình chiếu gần hóa thực","phamCap":"Tiên cốt nghi vấn","text":"Nguồn gốc và kế hoạch nuôi cấy khối cốt được hé lộ. Hình chiếu cấy trong Tần Hạo đã gần hoàn thành quá trình từ hư hóa thực.","anchor":"Hơn nữa, không ngừng cấy hình chiếu của khối cốt này vào trong cơ thể khiến cho nó càng thêm rõ ràng, từ hư dần hóa thành thực, gần như sắp thành công rồi."}]},"nguon":["@c0557"]},{"id":"te-dan-do-tham-tan-hao","name":"Tế đàn đỏ thắm của Tần Hạo","cn":"","aliases":[],"category":"khac","categoryLabel":"Tế đàn hiến tế","phanLoaiPhu":"Tế đàn liên hệ thượng giới","phamCap":"","soHuu":["Tần Hạo","Bất Lão sơn"],"trangThai":"Đang vận hành","blurb":"Tế đàn đỏ thắm có nhiều rãnh và lưu mùi máu do thường xuyên cần sinh mệnh hiến tế.","detail":"Tế đàn nối với thượng giới và dẫn hình chiếu khối cốt giao hòa với Tần Hạo. Liên hệ này không đủ để người ở thượng giới trực tiếp giáng xuống hạ giới.","hinhDang":"Tế đàn màu đỏ thắm, bên trên có nhiều rãnh","dacDiem":"Cần hiến tế lượng lớn sinh mệnh và còn lưu mùi máu.","chuHienThoi":"Bất Lão sơn","congNang":["Khơi thông liên hệ với thượng giới.","Dẫn hình chiếu khối cốt giao hòa với Tần Hạo."],"chuSoHuu":[{"ten":"Bất Lão sơn","tuChuong":"@c0557","denChuong":"","cachCoDuoc":"Dùng để thực hiện kế hoạch nuôi cấy khối cốt","trangThai":"đang vận hành"}],"capNhatToi":"@c0557","tabs":{"tienTrinh":[{"chuong":"@c0557","loai":"xuất hiện","importance":"normal","giaiDoan":"Dẫn hình chiếu khối cốt","phamCap":"","text":"Tế đàn được xác nhận cần sinh mệnh hiến tế và đang duy trì liên hệ với thượng giới để dẫn hình chiếu khối cốt vào Tần Hạo.","anchor":"Toàn bộ tế đàn màu đỏ thắm, bên trên có rất nhiều rãnh, bình thường đều cần hiến tế nên mùi máu vẫn thoang thoảng"}]},"nguon":["@c0557"]},{"id":"duoc-dinh-mau-bac-cua-thach-quoc","name":"Dược đỉnh màu bạc của Thạch quốc","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Pháp khí luyện dược","phamCap":"Thần","soHuu":["Thạch quốc"],"trangThai":"Đang được sử dụng","blurb":"Dược đỉnh màu bạc được Thạch Hạo tế ra trong trận đánh Tôn Giả Bất Lão Sơn. Nó bao phủ đối phương và thu mất pháp khí thần linh đang nằm trong tay lão. (+) Dược đỉnh cấp Thần có từ thượng cổ, tích lũy dược tính lâu năm và đã sinh linh tính. [CAN-SOAT-GOP]","detail":"Dược đỉnh giúp tăng tỷ lệ thành đan và giữ lại tinh hoa dược liệu. Khi Thạch Hạo luyện Tiểu Niết Bàn đan, phù văn trên đỉnh lưu chuyển và bên trong hiện ra hư ảnh người vàng tụng kinh.","phanLoaiPhu":"Dược đỉnh","nguonGoc":"Bảo vật của Thạch quốc có từ thượng cổ","uyLuc":"Tăng tỷ lệ luyện thành đan và bảo lưu dược tính của nguyên liệu.","dacDiem":"Đã có linh tính và có thể hiện ra hư ảnh người vàng tụng kinh.","chuHienThoi":"Thạch quốc","capNhatToi":"@c0558","congNang":["Tăng tỷ lệ luyện thành đan.","Giữ lại tinh hoa và dược tính của nguyên liệu."],"chuSoHuu":[{"ten":"Thạch quốc","tuChuong":"@c0558","denChuong":"","cachCoDuoc":"Bảo vật được lưu truyền từ thượng cổ","trangThai":"đang sở hữu"}],"tabs":{"tienTrinh":[{"chuong":"@c0558","loai":"dùng","importance":"normal","giaiDoan":"Luyện Tiểu Niết Bàn đan","phamCap":"Thần","text":"Được Thạch Hạo dùng để luyện hai lò Tiểu Niết Bàn đan, qua đó bộc lộ phẩm cấp Thần và linh tính tích lũy lâu năm.","anchor":"dược đỉnh quả nhiên mạnh mẽ, là bảo vật cấp Thần chân chính"}]},"nguon":["@c0558","@c0611"]},{"id":"huyet-hoang-dang","name":"Huyết Hoàng đằng","cn":"","aliases":[],"category":"nguyen-lieu","categoryLabel":"Bảo dược","phamCap":"Bảo dược","soHuu":["Thạch quốc"],"trangThai":"Một đoạn đã được dùng luyện đan","blurb":"Bảo dược đỏ thẫm cực kỳ hiếm, có khả năng tiến hóa thành Thánh dược.","detail":"Một đoạn Huyết Hoàng đằng được đưa vào lò Tiểu Niết Bàn đan và gây ra dị tượng phượng hoàng máu. Toàn hạ giới được nói là không có quá vài gốc.","hinhDang":"Dây leo đỏ thẫm","dacDiem":"Có khả năng tiến hóa thành Thánh dược.","capNhatToi":"@c0558","congNang":["Dùng làm nguyên liệu luyện Tiểu Niết Bàn đan."],"tabs":{"tienTrinh":[{"chuong":"@c0558","loai":"dùng","importance":"normal","giaiDoan":"Đưa vào lò luyện đan","text":"Một đoạn Huyết Hoàng đằng được Thạch Hạo dùng làm nguyên liệu luyện Tiểu Niết Bàn đan và phát sinh dị tượng phượng hoàng máu.","anchor":"Huyết Hoàng đằng, vô cùng hiếm thấy trong thiên địa, toàn bộ hạ giới không quá ba năm gốc"}]},"nguon":["@c0558"]},{"id":"ngu-nguyen-thu","name":"Ngũ Nguyên thụ","cn":"","aliases":[],"category":"nguyen-lieu","categoryLabel":"Thánh dược","phamCap":"Thánh dược","soHuu":["Thạch Hạo"],"trangThai":"Ủ rũ","blurb":"Thánh dược được mang về từ Bất Lão sơn nhưng đang trong trạng thái ủ rũ.","detail":"Thạch Hạo không hái lá Ngũ Nguyên thụ để luyện Tiểu Niết Bàn đan vì cây vẫn chưa khôi phục trạng thái.","nguonGoc":"Được mang về từ Bất Lão sơn","dacDiem":"Đang ủ rũ nên chưa thích hợp để hái lá.","chuHienThoi":"Thạch Hạo","capNhatToi":"@c0558","chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c0558","denChuong":"","cachCoDuoc":"Mang về từ Bất Lão sơn","trangThai":"đang giữ"}],"tabs":{"tienTrinh":[{"chuong":"@c0558","loai":"nhắc tới","importance":"bridge","giaiDoan":"Chưa thể dùng luyện đan","text":"Ngũ Nguyên thụ vẫn ủ rũ nên Thạch Hạo không hái lá của cây để luyện đan.","anchor":"cây thánh dược Ngũ Nguyên thụ vẫn ủ rủ, nếu không có thể ngắt lấy mấy lá rồi"}]},"nguon":["@c0558"]},{"id":"manh-vo-dong-thau","name":"Mảnh vỡ đồng thau","cn":"","aliases":[],"category":"khac","categoryLabel":"Vật phẩm truyền thừa","phamCap":"Không rõ","soHuu":["Thạch Hạo"],"trangThai":"Đã thu thập tám trên mười mảnh","blurb":"Những mảnh đồng thau liên quan tới phần thưởng là một bảo thuật cái thế khi tập hợp đủ mười mảnh.","detail":"Thạch Hạo đã có tám mảnh và trở lại Hư Thần giới với ý định phá thêm kỷ lục để nhận hai mảnh còn thiếu.","chuHienThoi":"Thạch Hạo","capNhatToi":"@c0558","congNang":["Tập hợp đủ mười mảnh có thể nhận được một bảo thuật cái thế."],"chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c0558","denChuong":"","cachCoDuoc":"Đã thu thập được tám mảnh","trangThai":"đang giữ"}],"tabs":{"tienTrinh":[{"chuong":"@c0558","loai":"nhắc tới","importance":"normal","giaiDoan":"Còn thiếu hai mảnh","text":"Thạch Hạo xác nhận đã có tám mảnh và dự định phá kỷ lục tại Hư Thần giới để tìm hai mảnh cuối.","anchor":"Ta có tám mảnh vỡ đồng thau, còn có hai khối nữa thì sẽ đạt được một bảo thuật cái thế"}]},"nguon":["@c0558"]},{"id":"hai-khoi-dong-thau-cuoi","name":"Hai khối đồng thau cuối","cn":"","aliases":[],"category":"khac","categoryLabel":"Vật phẩm","phamCap":"Không rõ","soHuu":[],"trangThai":"Chưa xuất hiện","blurb":"Phần thưởng chỉ xuất hiện sau khi người khiêu chiến vượt thiên lộ và đánh bại toàn bộ đối thủ.","detail":"Hai khối đồng thau cuối không thể thu được bằng cách tiếp tục phá kỷ lục tại Hư Thần giới. Người khiêu chiến phải tiến lên thiên lộ và chiến thắng tất cả đối thủ thì chúng mới tự động xuất hiện.","dinhDanh":"goc","congNang":["Tự động xuất hiện như phần thưởng sau khi người khiêu chiến đánh bại toàn bộ đối thủ trên thiên lộ."],"dacDiem":"Điều kiện xuất hiện gắn với việc hoàn thành toàn bộ thử thách trên thiên lộ.","chuSoHuu":[],"capNhatToi":"@c0560","tabs":{"tienTrinh":[{"chuong":"@c0560","loai":"nhắc tới","importance":"normal","giaiDoan":"Hé lộ điều kiện xuất hiện","text":"Điểu gia cho biết hai khối đồng thau cuối sẽ tự động xuất hiện sau khi Thạch Hạo đánh bại toàn bộ đối thủ trên thiên lộ.","anchor":"chiến bại hết mọi đối thủ, khối đồng thau sẽ tự động xuất hiện thôi"}]},"nguon":["@c0560"]},{"id":"tieu-kiem-cua-phuong-vu","name":"Tiểu kiếm của Phượng Vũ","cn":"","aliases":["Thanh tiểu kiếm do Phượng Vũ binh giải để lại","Tiên kiếm của Phượng Vũ"],"category":"khac","categoryLabel":"Vật phẩm chưa rõ bản chất","phamCap":"Không rõ","soHuu":["Phượng Vũ","Thạch Hạo"],"trangThai":"Trong tay Thạch Hạo","blurb":"Thanh tiểu kiếm xuất hiện sau khi Phượng Vũ dùng Binh giải để rời khỏi Hư Thần giới. Khi thân thể nàng hóa thành mưa ánh sáng và trở về hiện thực, tiểu kiếm còn lại trong tay Thạch Hạo.","detail":"Tiểu kiếm vốn do Phượng Vũ nắm giữ, chỉ dài bằng ngón tay, có vẻ ngoài sáng bóng, lấp lánh, tỏa hào quang và biểu hiện linh tính. Sau khi Phượng Vũ hóa thành mưa ánh sáng để trở về hiện thực, vật này không biến mất theo nàng mà lưu lại trong tay Thạch Hạo, qua đó đổi chủ tại Hư Thần giới. Bản chất, phẩm cấp và nguồn gốc cụ thể của tiểu kiếm chưa được xác định. @c0562","phanLoaiPhu":"Tiểu kiếm","hinhDang":"Dài bằng ngón tay và sáng bóng","dacDiem":"Chỉ dài bằng ngón tay, sáng bóng, lấp lánh, tỏa hào quang và có linh tính.","chuHienThoi":"Thạch Hạo","chuSoHuu":[{"ten":"Phượng Vũ","tuChuong":"@c0562","denChuong":"@c0562","cachCoDuoc":"Mang theo trước khi Binh giải","trangThai":"Đã để lại"},{"ten":"Thạch Hạo","tuChuong":"@c0562","denChuong":"","cachCoDuoc":"Còn lại trong tay sau khi Phượng Vũ Binh giải","trangThai":"Đang giữ"}],"capNhatToi":"@c0562","tabs":{"tienTrinh":[{"chuong":"@c0562","loai":"đổi chủ","importance":"major","giaiDoan":"Rơi vào tay Thạch Hạo","text":"Tiểu kiếm còn lại trong tay Thạch Hạo sau khi Phượng Vũ hóa thành mưa ánh sáng và trở về hiện thực.","anchor":"Trong tay nó còn sót lại một thanh tiểu kiếm lấp lánh","phamCap":"Không rõ"}]},"nguon":["@c0562"]},{"id":"thien-la-tan","name":"Thiên La Tán","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Pháp khí hình ô","phamCap":"Không rõ","soHuu":[],"trangThai":"Bị phá hủy","blurb":"Thiên La Tán là pháp khí hình ô, có thể phóng ánh đen công kích hồn phách. Khi được dùng để tập kích Thạch Hạo trên đàn Đồng Tước, pháp khí này bị tiểu kiếm của Phượng Vũ chém đứt đôi chỉ trong một đòn. (+) Một chiếc bảo tán được dùng trong cuộc tập kích Thạch Hạo tại khu vực thứ mười của thiên kiếp. [CAN-SOAT-GOP]","detail":"Nguồn gốc của Thiên La Tán chưa được làm rõ. Pháp khí này từng phóng ánh đen nhằm công kích hồn phách của Thạch Hạo trên đàn Đồng Tước, nhưng đòn tập kích không thành và bản thân Thiên La Tán bị tiểu kiếm của Phượng Vũ chém đứt đôi. @c0563","phanLoaiPhu":"Pháp khí công kích hồn phách","hinhDang":"Hình ô","congNang":["Phóng ánh đen có khả năng công kích, tiêu diệt hồn phách của mục tiêu. @c0563"],"uyLuc":"Có thể trực tiếp uy hiếp và tiêu diệt hồn phách của mục tiêu.","chuSoHuu":[],"tabs":{"tienTrinh":[{"chuong":"@c0563","loai":"hư tổn/tu bổ","importance":"major","giaiDoan":"Bị phá hủy","text":"Thiên La Tán phóng ánh đen công kích Thạch Hạo nhưng bị tiểu kiếm chém đứt đôi.","anchor":"xoẹt một tiếng, cắt đứt đôi Thiên La Tán kia","phamCap":"Không rõ"}]},"capNhatToi":"@c0563","nguon":["@c0563","@c0951"],"dacDiem":"Pháp khí có hình dáng một chiếc ô; đã bị tiểu kiếm của Phượng Vũ chém đứt đôi. @c0563"},{"id":"quyen-truc-xuyen-khong","name":"Quyển trục xuyên không","cn":"","aliases":[],"category":"khac","categoryLabel":"Vật phẩm đào thoát","phamCap":"Không rõ","soHuu":["Lão Viên Hỏa Vân Động"],"trangThai":"Đã sử dụng","blurb":"Quyển trục có khả năng chọc thủng không gian để giúp người sử dụng thoát khỏi chiến trường.","detail":"Lão Viên của Hỏa Vân Động sử dụng quyển trục khi Thạch Hạo áp sát, nhờ đó xuyên qua không gian và trốn thoát.","congNang":["Chọc thủng không gian để đưa người sử dụng rời khỏi nơi giao chiến."],"chuSoHuu":[{"ten":"Lão Viên Hỏa Vân Động","tuChuong":"@c0563","denChuong":"@c0563","cachCoDuoc":"Không rõ","trangThai":"Đã sử dụng để đào thoát"}],"tabs":{"tienTrinh":[{"chuong":"@c0563","loai":"dùng","importance":"normal","giaiDoan":"Đào thoát","text":"Lão Viên dùng quyển trục chọc thủng không gian và thoát khỏi Thạch Hạo.","anchor":"tên này nhờ vào một quyển trục để chọc thủng không gian mà bỏ chạy","phamCap":"Không rõ"}]},"capNhatToi":"@c0563","nguon":["@c0563"]},{"id":"doa-hoa-bach-ngan","name":"Đóa hoa Bạch ngân","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Bí bảo","phamCap":"","soHuu":["Tộc Bạch Ngân"],"trangThai":"không rõ sau khi đội ngũ tộc Bạch Ngân đại bại","blurb":"Bí bảo của tộc Bạch Ngân có khí hồn được đưa vào Linh giới. Nhiều người có thể hợp lực điều khiển nó để niêm phong hư không và áp chế mục tiêu.","detail":"Đóa hoa tỏa ánh bạc như một mặt trời màu bạc, được đội ngũ tộc Bạch Ngân điều khiển bằng cách cùng tụng kinh. Nó phong tỏa khu vực quanh Thạch Hạo, nhưng thế áp chế bị cưỡng ép phá vỡ khi đội hình điều khiển bí bảo tan rã.","phanLoaiPhu":"Bí bảo phong tỏa","nguonGoc":"Do lão tổ tộc Bạch Ngân dùng ngân tinh của bản thân luyện hóa","uyLuc":"Có thể niêm phong hư không và áp chế hành động của mục tiêu.","dacDiem":"Khi vận chuyển tỏa sáng như một mặt trời màu bạc.","chuHienThoi":"Tộc Bạch Ngân","congNang":["Niêm phong hư không quanh mục tiêu.","Tạo sức áp chế để đồng đội tiến hành công kích."],"chuSoHuu":[{"ten":"Tộc Bạch Ngân","tuChuong":"@c0564","denChuong":"","cachCoDuoc":"Bí bảo do lão tổ của tộc luyện hóa","trangThai":"sở hữu"}],"capNhatToi":"@c0564","tabs":{"tienTrinh":[{"chuong":"@c0564","loai":"dùng","importance":"normal","giaiDoan":"Phong tỏa đàn Đồng Tước","text":"Đội ngũ tộc Bạch Ngân hợp lực điều khiển Đóa hoa Bạch ngân để niêm phong hư không và áp chế Thạch Hạo.","anchor":"thứ đó cứ như là một mặt trời màu bạc niêm phong nơi đây lại","phamCap":""}]},"nguon":["@c0564"]},{"id":"dan-dong-tuoc-te-dan","name":"Đàn Đồng Tước","cn":"","aliases":[],"category":"khac","categoryLabel":"Tế đàn","phamCap":"Không rõ","soHuu":[],"trangThai":"Nguyên vẹn","blurb":"Tế đàn có phù văn cổ tước tự phong tỏa chiến trường khi năng lượng giao chiến đe dọa người quan chiến.","detail":"Trong trận chiến giữa Thạch Hạo và Đằng Nhất, đàn Đồng Tước phát sáng và diễn hóa một con cổ tước bằng phù văn. Cổ tước phong ấn vùng hư không, ngăn năng lượng chiến đấu lan ra ngoài.","phanLoaiPhu":"Tế đàn phòng hộ","hinhDang":"Tế đàn có thể diễn hóa cổ tước bằng phù văn.","congNang":["Phong ấn vùng hư không quanh chiến trường.","Ngăn năng lượng chiến đấu lan tới người quan chiến."],"tabs":{"tienTrinh":[{"chuong":"@c0565","loai":"dùng","importance":"normal","giaiDoan":"Phong tỏa chiến trường","text":"Đàn Đồng Tước phát sáng, diễn hóa cổ tước bằng phù văn và phong ấn vùng hư không quanh trận chiến.","anchor":"đàn Đồng Tước phát sáng, một con cổ tước bay lên, đó là do phù văn biến thành không ngừng giương cánh kích thiên, phong ấn vùng hư không này lại","phamCap":"Không rõ"}]},"capNhatToi":"@c0565","nguon":["@c0565"]},{"id":"binh-bat-cua-ton-gia-tay-phuong-giao","name":"Bình bát của Tôn giả Tây Phương giáo","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Bảo cụ","phamCap":"Bảo cụ chí cường","soHuu":["Tôn giả vân du Tây Phương giáo","Thạch Hạo"],"trangThai":"Bị Thạch Hạo tạm thời khống chế rồi dùng để giam giữ chủ nhân","blurb":"Bình bát vốn thuộc về một Tôn giả Tây Phương giáo, có khả năng tấn công và giam giữ sinh linh. Khi được dùng để đối phó Thạch Hạo, bảo cụ bị hình thái Côn Bằng của hắn hàng phục, đổi chủ rồi trở thành vật giam giữ chính vị Tôn giả.","detail":"Bình bát được một Tôn giả Tây Phương giáo sử dụng để đối phó Thạch Hạo. Dù được mô tả là bảo cụ chí cường, nó vẫn bị móng vuốt Côn Bằng của Thạch Hạo áp chế và hàng phục, khiến toàn bộ hào quang cùng sát khí tiêu tán. Sau khi đoạt được bình bát, Thạch Hạo dùng chính bảo cụ này để giam giữ vị Tôn giả Tây Phương giáo. @c0567","phanLoaiPhu":"Bình bát","hinhDang":"Bình bát","uyLuc":"Được mô tả là bảo cụ chí cường nhưng bị hình thái Côn Bằng của Thạch Hạo áp chế.","dacDiem":"Sau khi bị Thạch Hạo hóa thành Côn Bằng hàng phục, toàn bộ hào quang và sát khí của bình bát đều tiêu tán.","chuHienThoi":"Thạch Hạo tạm thời khống chế","congNang":["Tấn công đối thủ.","Giam giữ sinh linh; sau khi hàng phục bảo cụ, Thạch Hạo đã dùng nó nhốt chính vị Tôn giả Tây Phương giáo. @c0567"],"chuSoHuu":[{"ten":"Tôn giả vân du Tây Phương giáo","tuChuong":"@c0567","denChuong":"@c0567","cachCoDuoc":"Chủ nhân ban đầu","trangThai":"Bị tước quyền khống chế tạm thời"},{"ten":"Thạch Hạo","tuChuong":"@c0567","denChuong":"","cachCoDuoc":"Hàng phục bảo cụ trong giao chiến","trangThai":"Tạm thời khống chế"}],"capNhatToi":"@c0567","tabs":{"tienTrinh":[{"chuong":"@c0567","loai":"đổi chủ","importance":"major","giaiDoan":"Bị hàng phục","phamCap":"Bảo cụ chí cường","text":"Bình bát bị Thạch Hạo hóa thành Côn Bằng hàng phục rồi được dùng để giam giữ chính vị Tôn giả Tây Phương giáo.","anchor":"Móng vuốt của nó hạ xuống, hàng phục lấy chiếc bình bát - bảo cụ chí cường kia, lúc này toàn bộ hào quang đều dập tắt, sát khí tiêu tán."}]},"nguon":["@c0567"]},{"id":"khoi-sach-quy-dong-thau-thu-chin","name":"Khối sách quý đồng thau thứ chín","cn":"","aliases":[],"category":"khac","categoryLabel":"Mảnh sách quý","phamCap":"Không rõ","soHuu":["Thạch Hạo"],"trangThai":"Đang thuộc Thạch Hạo","blurb":"Khối sách quý đồng thau thứ chín rơi vào tay Thạch Hạo, nâng số khối nó tập hợp được lên chín trong tổng số mười khối. Đây là một bộ phận của bộ mười khối sách quý cần được thu thập đầy đủ.","detail":"Khối đồng thau rơi vào tay Thạch Hạo, giúp nó tập hợp được chín trong tổng số mười khối sách quý. Hồ sơ chưa ghi nhận thêm nguồn gốc, uy lực hay tác dụng độc lập của riêng khối này.","phanLoaiPhu":"Mảnh thứ chín trong bộ sách đồng thau","dacDiem":"Là khối thứ chín trong tổng số mười khối cần tập hợp.","chuHienThoi":"Thạch Hạo","capNhatToi":"@c0568","congNang":["Hợp thành bộ mười khối sách quý khi được tập hợp đầy đủ."],"chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c0568","denChuong":"","cachCoDuoc":"Được Hư Thần giới ban sau hành trình vào Linh giới","trangThai":"Đang sở hữu"}],"tabs":{"tienTrinh":[{"chuong":"@c0568","loai":"đổi chủ","importance":"major","giaiDoan":"Mảnh thứ chín","text":"Khối đồng thau rơi vào tay Thạch Hạo, giúp nó tập hợp được chín trong tổng số mười khối.","anchor":"Một khối đồng thau rơi xuống, hiện trong lòng bàn tay của Thạch Hạo","phamCap":"Không rõ"}]},"nguon":["@c0568"]},{"id":"cot-thu-truyen-tin-bien-gioi-phia-tay","name":"Cốt thư truyền tin biên giới phía Tây","cn":"","aliases":[],"category":"khac","categoryLabel":"Vật truyền tin","phamCap":"Không rõ","soHuu":["Thạch Hằng"],"trangThai":"Đã được gửi tới hoàng cung","blurb":"Cốt thư dùng để truyền tin khẩn từ biên giới phía Tây tới hoàng cung Thạch quốc. Hai lần truyền tin về Thôn Thiên tước đã dẫn Thạch Hạo tới nơi Thạch Hằng bố trí bẫy.","detail":"Cốt thư xuất hiện qua tổ tế đàn trong trường hợp khẩn cấp, mang tin Thôn Thiên tước tàn sát sinh linh và gần nhen nhóm Thần hỏa. Những tin báo này trở thành mồi nhử khiến Thạch Hạo đích thân tới biên giới phía Tây.","phanLoaiPhu":"Cốt thư truyền tin khẩn","congNang":["Truyền tin khẩn qua tổ tế đàn giữa biên giới phía Tây và hoàng cung Thạch quốc."],"dacDiem":"Được sử dụng hai lần để chuyển tin về thảm họa tại biên giới.","chuHienThoi":"Thạch Hằng","capNhatToi":"@c0568","chuSoHuu":[{"ten":"Thạch Hằng","tuChuong":"@c0568","denChuong":"","cachCoDuoc":"Dùng làm phương tiện gửi tin từ biên giới","trangThai":"Đã sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c0568","loai":"dùng","importance":"normal","giaiDoan":"Truyền tin biên giới","text":"Hai cốt thư được gửi qua tổ tế đàn để báo tin khẩn và dẫn Thạch Hạo tới biên giới phía Tây.","anchor":"một cốt thư xuất hiện, nếu không phải việc rất khẩn cấp thì sẽ không dùng phương thức này","phamCap":"Không rõ"}]},"nguon":["@c0568"]},{"id":"chien-xa-hoang-kim-cua-thach-hao","name":"Chiến xa Hoàng kim của Thạch Hạo","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Chiến xa","phamCap":"Không rõ","soHuu":["Thạch Hạo"],"trangThai":"Đang sử dụng","blurb":"Chiến xa Hoàng kim được Thạch Hạo dùng để nhanh chóng vượt qua khu vực biên giới phía Tây. Nó đưa Nhân Hoàng tới thành trì do Thạch Hằng trấn thủ.","detail":"Sau khi tới vùng tuyệt địa vạn dặm, Thạch Hạo leo lên chiến xa Hoàng kim và nhanh chóng tiến về thành trì ở biên giới để tìm hiểu tình hình.","phanLoaiPhu":"Pháp bảo di chuyển","hinhDang":"Chiến xa màu vàng kim","congNang":["Di chuyển với tốc độ cao qua khu vực biên giới rộng lớn."],"chuHienThoi":"Thạch Hạo","capNhatToi":"@c0568","chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c0568","denChuong":"","cachCoDuoc":"Đã thuộc quyền sử dụng của Thạch Hạo khi tới biên giới","trangThai":"Đang sở hữu"}],"tabs":{"tienTrinh":[{"chuong":"@c0568","loai":"dùng","importance":"normal","giaiDoan":"Tiến vào biên giới","text":"Thạch Hạo dùng chiến xa Hoàng kim để nhanh chóng tới thành trì của Thạch Hằng.","anchor":"leo lên chiến xa Hoàng kim nhanh chóng đuổi tới","phamCap":"Không rõ"}]},"nguon":["@c0568"]},{"id":"trang-bi-chan-than-bao-kho-thach-quoc","name":"Pháp khí và giáp trụ Chân Thần của bảo khố Thạch quốc","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Bộ pháp khí","phanLoaiPhu":"Trang bị Chân Thần","phamCap":"Pháp khí Chân Thần","soHuu":["Thạch Hạo","Tiểu Hồng","Bóng Lông"],"trangThai":"đang sử dụng","blurb":"Bộ giáp trụ và binh khí thần thánh được Thạch Hạo lấy từ bảo khố Thạch quốc rồi giao cho Tiểu Hồng cùng Bóng Lông.","detail":"Trang bị giúp hai sinh linh đã nhen nhóm Thần hỏa tăng mạnh chiến lực, từ thế bị áp chế chuyển sang áp đảo tượng thần mạ vàng.","laBo":true,"thanhVien":[{"id":"phap-kiem-chan-than-cua-tieu-hong","vaiTro":"Binh khí của Tiểu Hồng"},{"id":"than-kich-tran-quoc","vaiTro":"Binh khí được Bóng Lông sử dụng"}],"nguonGoc":"Bảo khố Thạch quốc","uyLuc":"Giúp cường giả đã nhen nhóm Thần hỏa tăng mạnh chiến lực.","congNang":["Cung cấp giáp trụ và binh khí Chân Thần cho Tiểu Hồng cùng Bóng Lông."],"chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c0570","denChuong":"","cachCoDuoc":"Lấy từ bảo khố Thạch quốc","trangThai":"chủ sở hữu"},{"ten":"Tiểu Hồng","tuChuong":"@c0570","denChuong":"","cachCoDuoc":"Được Thạch Hạo giao sử dụng","trangThai":"đang sử dụng"},{"ten":"Bóng Lông","tuChuong":"@c0570","denChuong":"","cachCoDuoc":"Được Thạch Hạo giao sử dụng","trangThai":"đang sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c0570","loai":"dùng","importance":"normal","giaiDoan":"Trang bị cho hai cường giả Thần hỏa","text":"Tiểu Hồng và Bóng Lông mặc giáp trụ, sử dụng binh khí Chân Thần rồi đảo ngược thế trận trước tượng thần mạ vàng.","anchor":"Đây chính là pháp khí và giáp trụ mà Thạch Hạo lấy từ trong bảo khố Thạch quốc","phamCap":"Pháp khí Chân Thần"}]},"capNhatToi":"@c0570","nguon":["@c0570"]},{"id":"phap-kiem-chan-than-cua-tieu-hong","name":"Pháp kiếm Chân Thần của Tiểu Hồng","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Pháp khí","phanLoaiPhu":"Kiếm","phamCap":"Pháp khí Chân Thần","soHuu":["Tiểu Hồng"],"trangThai":"đang sử dụng","blurb":"Pháp kiếm Chân Thần được Tiểu Hồng sử dụng khi hóa thành hình người.","detail":"Thanh kiếm chém đứt hàng chục cánh tay thuộc Thiên thủ và cuối cùng chém đầu tượng thần mạ vàng.","boCha":"trang-bi-chan-than-bao-kho-thach-quoc","uyLuc":"Có thể chém phá Thiên thủ được kim thân gia trì.","congNang":["Chém đứt nhiều cánh tay của tượng thần mạ vàng.","Chém đầu và phá hủy vật dẫn của luồng ý chí Thiên quốc."],"chuSoHuu":[{"ten":"Tiểu Hồng","tuChuong":"@c0570","denChuong":"","cachCoDuoc":"Được Thạch Hạo giao từ bảo khố Thạch quốc","trangThai":"đang sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c0570","loai":"dùng","importance":"normal","giaiDoan":"Chém phá tượng thần","text":"Tiểu Hồng dùng pháp kiếm chém đứt hàng chục cánh tay và phá hủy vật dẫn của tượng thần mạ vàng.","anchor":"Tiểu Hồng chém xuống một chiêu, cắt đứt mấy chục cánh tay.","phamCap":"Pháp khí Chân Thần"}]},"capNhatToi":"@c0570","nguon":["@c0570"]},{"id":"nguyen-rua-mau","name":"Nguyền rủa mâu","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Cốt mâu nguyền rủa","phamCap":"Có thể khiến Tôn giả bình thường thân tử đạo tiêu","soHuu":["Ông lão áo xám"],"trangThai":"Bị phá hủy","blurb":"Nguyền rủa mâu là cốt mâu thuộc sở hữu của ông lão áo xám, mang nguyền rủa cùng oán niệm của ít nhất ngàn vạn sinh hồn. Pháp bảo có thể thôn phệ người bị đánh trúng và đủ sức khiến một Tôn giả bình thường thân tử đạo tiêu, nhưng cuối cùng bị Thạch Hạo chặn đứng, bẻ gãy rồi làm nổ tung.","detail":"Nguyền rủa mâu là một cây cốt mâu chứa lượng oán khí cực lớn, quy tụ oán niệm của ít nhất ngàn vạn sinh hồn và thuộc sở hữu của ông lão áo xám. Nó có khả năng thôn phệ người trúng đòn. Khi đối đầu Thạch Hạo, cốt mâu bị phù văn của hắn chặn lại trước người, sau đó gãy thành nhiều khúc và nổ tung, khiến chủ nhân chịu phản phệ. @c0571","vatLieu":"Cốt mâu luyện cùng oán niệm của ít nhất ngàn vạn sinh hồn","uyLuc":"Có thể khiến một Tôn giả bình thường thân tử đạo tiêu.","dacDiem":"Là cốt mâu mang nguyền rủa và lượng oán niệm sinh hồn cực lớn; đã gãy thành nhiều khúc rồi nổ tung dưới phù văn của Thạch Hạo. @c0571","chuHienThoi":"","congNang":["Thôn phệ người bị đánh trúng.","Chứa và phát huy oán niệm của ít nhất ngàn vạn sinh hồn."],"chuSoHuu":[{"ten":"Ông lão áo xám","tuChuong":"@c0571","denChuong":"@c0571","cachCoDuoc":"Pháp khí dùng để thi triển nguyền rủa","trangThai":"Mất khi cốt mâu bị phá hủy"}],"capNhatToi":"@c0571","tabs":{"tienTrinh":[{"chuong":"@c0571","loai":"hư tổn/tu bổ","importance":"major","giaiDoan":"Bị phá hủy","phamCap":"Có thể uy hiếp Tôn giả bình thường","text":"Nguyền rủa mâu bị phù văn của Thạch Hạo chặn lại, gãy thành nhiều khúc rồi nổ tung.","anchor":"thanh cốt mau dừng lại ngay trước người, bị phu văn cản trở sau đó nhanh chóng đứt thành từng khúc"}]},"nguon":["@c0571"]},{"id":"than-kich-chan-than-cua-bong-long","name":"Thần kích Chân Thần của Bóng Lông","cn":"","aliases":[],"category":"than-khi","categoryLabel":"Vũ khí Chân Thần","phamCap":"Vũ khí Chân Thần","soHuu":["Bóng Lông"],"trangThai":"Đang được sử dụng","blurb":"Thần kích do Bóng Lông sử dụng trong trận chiến tại biên giới phía Tây. Vũ khí được dùng để công kích cường giả Thiên quốc và trấn áp Huyết Ma thước.","detail":"Bóng Lông cầm thần kích khi hiện thân cao như núi, dùng nó giao chiến với cường giả Thiên quốc rồi phối hợp cùng pháp kiếm của Tiểu Hồng đánh nát Huyết Ma thước.","hinhDang":"Thần kích dựng thẳng trong tay Bóng Lông","uyLuc":"Có thể phối hợp với pháp khí Chân Thần khác để phá hủy Huyết Ma thước.","dacDiem":"Vũ khí cận chiến dùng cho công kích và trấn áp.","chuHienThoi":"Bóng Lông","congNang":["Công kích cường giả Thiên quốc.","Phối hợp trấn áp và phá hủy Huyết Ma thước."],"chuSoHuu":[{"ten":"Bóng Lông","tuChuong":"@c0571","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"Đang sở hữu"}],"capNhatToi":"@c0571","tabs":{"tienTrinh":[{"chuong":"@c0571","loai":"dùng","importance":"normal","giaiDoan":"Tham chiến tại biên giới phía Tây","phamCap":"Vũ khí Chân Thần","text":"Bóng Lông dùng thần kích đối chiến cường giả Thiên quốc và phối hợp phá hủy Huyết Ma thước.","anchor":"Bóng Lông thân hình lại cao như núi, cả người vàng óng, trong tay cầm thần kích dựng thẳng"}]},"nguon":["@c0571"]},{"id":"khung-xuong-hu-khong-thu","name":"Khung xương Hư Không thú","cn":"","category":"nguyen-lieu","categoryLabel":"Di cốt phá giới","phamCap":"Tiếp cận cấp Chí Tôn","soHuu":["Minh thổ"],"trangThai":"Được đề nghị dùng trong kế hoạch phá giới","blurb":"Bộ xương của Hư Không thú do Minh thổ sở hữu, có cấp độ tiếp cận Chí Tôn. Di cốt được đưa ra làm phương tiện hỗ trợ phá vỡ giới bích.","detail":"Đại năng Minh thổ đề nghị dùng bộ xương trong kế hoạch đưa cường giả đã nhen nhóm Thần hỏa xuống hạ giới, đồng thời yêu cầu giết Thạch Hạo làm điều kiện trao đổi.","phanLoaiPhu":"Di cốt Hư Không thú","nguonGoc":"Thuộc Minh thổ","uyLuc":"Có khả năng hỗ trợ phá giới nhờ đặc tính của Hư Không thú gần cấp Chí Tôn.","dacDiem":"Di cốt của Hư Không thú đã tiếp cận cấp Chí Tôn.","chuHienThoi":"Minh thổ","congNang":["Hỗ trợ phá vỡ giới bích để đưa cường giả xuống hạ giới."],"chuSoHuu":[{"ten":"Minh thổ","tuChuong":"@c0572","denChuong":"","cachCoDuoc":"Di cốt được xác nhận nằm trong tay Minh thổ","trangThai":"đang sở hữu"}],"capNhatToi":"@c0572","tabs":{"tienTrinh":[{"chuong":"@c0572","loai":"xuất hiện","importance":"normal","giaiDoan":"Được đưa vào kế hoạch phá giới","text":"Minh thổ đề nghị sử dụng khung xương Hư Không thú gần cấp Chí Tôn để phá giới.","anchor":"Minh thổ ta có một khung xương của Hư không thú đã tiếp cận tới cấp Chí tôn","phamCap":"Tiếp cận cấp Chí Tôn"}]},"nguon":["@c0572"]},{"id":"te-dan-huyet-te-hong-vuc","name":"Tế đàn huyết tế Hồng vực","cn":"","aliases":["Tế đàn màu đen Hồng vực","Tế đàn đen Hồng vực"],"category":"phap-bao","categoryLabel":"Tế đàn huyết tế","phamCap":"Không rõ","soHuu":[],"trangThai":"Đã được dựng và chuẩn bị sử dụng","blurb":"Tế đàn màu đen được dựng trong đầm lầy Hồng vực để phục vụ nghi thức huyết tế và kế hoạch phá giới. Bề mặt tế đàn khắc dày đặc phù văn thần ma, tạo áp lực lên linh hồn.","detail":"Nhiều người thuộc các đạo thống khác nhau bí mật tập kết tại tế đàn trước khi hoạt động thu bắt sinh linh trên quy mô lớn bắt đầu.","phanLoaiPhu":"Tế đàn phá giới","hinhDang":"Tế đàn màu đen bóng khắc nhiều phù văn thần ma","nguonGoc":"Được dựng trong đầm lầy Hồng vực","uyLuc":"Tạo áp lực lên linh hồn và được dùng trong nghi thức huyết tế phá giới.","dacDiem":"Màu đen bóng, phủ kín phù văn thần ma.","congNang":["Tiến hành huyết tế.","Hỗ trợ kế hoạch phá giới đưa cường giả xuống hạ giới."],"capNhatToi":"@c0572","tabs":{"tienTrinh":[{"chuong":"@c0572","loai":"xuất hiện","importance":"normal","giaiDoan":"Chuẩn bị huyết tế","text":"Tế đàn đen được dựng trong đầm lầy Hồng vực và trở thành nơi tập kết bí mật của những người thuộc nhiều đạo thống.","anchor":"một tòa tế đàn màu đen bóng, khắc rất nhiều phù văn thần ma","phamCap":"Không rõ"}]},"nguon":["@c0572"]},{"id":"tui-can-khon-cua-ton-gia-dai-giao-bat-hu","name":"Túi càn khôn của Tôn giả đại giáo bất hủ","cn":"","category":"phap-bao","categoryLabel":"Pháp khí thu giữ","phamCap":"Không rõ","soHuu":["Tôn giả mới tấn cấp của đại giáo bất hủ"],"trangThai":"Đang được dùng thu bắt sinh linh","blurb":"Túi càn khôn do một Tôn giả mới tấn cấp của đại giáo bất hủ sử dụng tại Hồng vực. Pháp khí hút sinh linh trên diện rộng và giam giữ cả một con giao ngân mạnh mẽ.","detail":"Túi được sử dụng trong hoạt động thu bắt sinh linh phục vụ huyết tế. Kẻ sử dụng điên cuồng hút mọi sinh linh xung quanh mà không giải thích mục đích.","phanLoaiPhu":"Pháp khí không gian thu giữ","uyLuc":"Có thể hút nhiều sinh linh trên phạm vi rộng, kể cả giao ngân đang ra sức chống cự.","dacDiem":"Tạo lực hút mạnh để thu và giam sinh linh.","chuHienThoi":"Tôn giả mới tấn cấp của đại giáo bất hủ","congNang":["Hút sinh linh từ khu vực xung quanh.","Giam giữ sinh linh bị thu vào túi."],"chuSoHuu":[{"ten":"Tôn giả mới tấn cấp của đại giáo bất hủ","tuChuong":"@c0572","denChuong":"","cachCoDuoc":"Được ghi nhận trực tiếp sử dụng pháp khí","trangThai":"đang sở hữu"}],"capNhatToi":"@c0572","tabs":{"tienTrinh":[{"chuong":"@c0572","loai":"dùng","importance":"normal","giaiDoan":"Thu sinh linh cho huyết tế","text":"Tôn giả của đại giáo bất hủ dùng túi càn khôn hút sinh linh bốn phía và thu cả một con giao ngân đang chống cự.","anchor":"Một cường giả cầm túi càn khôn trong tay, hắn điên cuồng hút lấy sinh linh bốn phía","phamCap":"Không rõ"}]},"nguon":["@c0572"]},{"id":"lo-luyen-hu-khong","name":"Lò luyện hư không","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Bảo cụ trấn giáo","phamCap":"Bảo cụ trấn giáo","soHuu":["Các giáo chủ trong cổ điện"],"trangThai":"Đã theo Hư không thú xuống hạ giới","blurb":"Bảo cụ trấn giáo dùng để chứa và bảo vệ mười mấy sinh linh nhen nhóm Thần hỏa trong quá trình vượt giới. (+) Pháp khí chứa một lượng hư không kim quý hiếm, trở thành mục tiêu bị các đại giáo liên tục đòi lấy. [CAN-SOAT-GOP]","detail":"Lò thu nhỏ bằng nắm đấm rồi được đặt vào đầu lâu Hư không thú. Thần linh bình thường không thể tế luyện, sử dụng, thậm chí hiếm khi được nhìn thấy bảo cụ này.","phanLoaiPhu":"Bảo cụ vận chuyển và phòng hộ","hinhDang":"Lư đồng có thể thu nhỏ bằng nắm đấm","uyLuc":"Có thể bảo vệ một nhóm sinh linh Thần hỏa trên đường vượt giới.","dacDiem":"Thần linh bình thường không thể tế luyện hoặc sử dụng.","congNang":["Chứa và bảo vệ người vượt giới."],"chuHienThoi":"Các giáo chủ trong cổ điện","chuSoHuu":[{"ten":"Các giáo chủ trong cổ điện","tuChuong":"@c0573","denChuong":"","cachCoDuoc":"Bảo cụ trấn giáo được dùng trong kế hoạch đưa người xuống hạ giới.","trangThai":"Đã đưa vào đầu lâu Hư không thú"}],"tabs":{"tienTrinh":[{"chuong":"@c0573","loai":"dùng","importance":"normal","giaiDoan":"Bảo vệ người vượt giới","text":"Mười mấy sinh linh Thần hỏa tiến vào lò để được bảo vệ trước khi cùng Hư không thú đi xuống hạ giới.","anchor":"Những người này đều bay vào trong một lư đồng, dùng thứ này để bảo vệ bản thân, đây là một bảo cụ trấn giáo, Thần linh bình thường cơ bản không cách nào tế luyện, không thể sử dụng, thậm chí cũng chưa bao giờ nhìn thấy.","phamCap":"Bảo cụ trấn giáo"}]},"capNhatToi":"@c0573","nguon":["@c0573","@c0608"]},{"id":"than-dan-thuong-gioi","name":"Thần đan thượng giới","cn":"","aliases":[],"category":"dan-duoc","categoryLabel":"Đan dược","phamCap":"Thần đan","soHuu":["Tần Hạo"],"trangThai":"Đã sử dụng","blurb":"Bảo dược thần thánh từ thượng giới được Tần Hạo dùng sau khi cấy Chí Tôn cốt. Một viên có thể hỗ trợ tái tạo răng, xương và huyết nhục.","detail":"Loại thần đan này được luyện từ hàng trăm linh chu, thần trùng và khoáng vật. Tần Hạo dùng một viên để tái tạo thân thể và giảm hậu hoạn sau quá trình cấy cốt.","phanLoaiPhu":"Bảo dược hồi phục và tái tạo thân thể","nguonGoc":"Thượng giới","uyLuc":"Có thể khiến răng mọc lại, xương phát triển và huyết nhục tái tạo.","dacDiem":"Được luyện từ hàng trăm linh chu, thần trùng và khoáng vật.","chuHienThoi":"Tần Hạo","congNang":["Tái tạo răng, xương và huyết nhục sau tổn thương.","Hỗ trợ thân thể thoát thai hoán cốt sau quá trình cấy Chí Tôn cốt."],"chuSoHuu":[{"ten":"Tần Hạo","tuChuong":"@c0575","denChuong":"@c0575","cachCoDuoc":"Được cung cấp để hồi phục sau khi cấy cốt","trangThai":"Đã sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c0575","loai":"dùng","importance":"normal","giaiDoan":"Hỗ trợ hồi phục sau cấy cốt","text":"Tần Hạo dùng một viên thần đan thượng giới để tái tạo thân thể và tránh hậu hoạn sau khi cấy Chí Tôn cốt.","anchor":"mỗi một viên có thể khiến răng người mọc lại, xương to lớn hơn, huyết nhục tái tạo"}]},"capNhatToi":"@c0575","nguon":["@c0575"]},{"id":"hac-giay-truyen-tin","name":"Hạc giấy truyền tin","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Pháp khí truyền tin","phamCap":"Không rõ","soHuu":["Thạch Hạo"],"trangThai":"Đang sử dụng","blurb":"Pháp khí dạng hạc giấy được Thạch Hạo để lại tại hoàng cung Thạch quốc. Nó có thể mang tin và tìm tới chủ nhân khi cần báo gấp.","detail":"Khi người báo tin không tìm thấy Thạch Hạo tại Tam Sinh sơn, hạc giấy bay tới trấn nhỏ và xuất hiện trong lòng bàn tay nó, mang theo tin các vị Thần đã giáng lâm hoàng đô.","phanLoaiPhu":"Pháp khí truyền tin","hinhDang":"Một tờ giấy hóa thành hình hạc","uyLuc":"Có thể tự tìm tới Thạch Hạo để chuyển tin khẩn cấp.","dacDiem":"Khi hạ xuống mang theo ánh sáng và xuất hiện trong lòng bàn tay người nhận.","chuHienThoi":"Thạch Hạo","congNang":["Mang tin từ hoàng cung và tìm tới Thạch Hạo."],"chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c0575","denChuong":"","cachCoDuoc":"Được Thạch Hạo để lại tại hoàng cung làm phương tiện báo tin","trangThai":"Đang có"}],"tabs":{"tienTrinh":[{"chuong":"@c0575","loai":"dùng","importance":"normal","giaiDoan":"Báo tin Thần giáng hoàng đô","text":"Hạc giấy từ hoàng cung bay tới trấn nhỏ và truyền cho Thạch Hạo tin các vị Thần đang ép nó tới hoàng đô.","anchor":"một tờ giấy Hạc hạ xuống mang theo vằng sáng xuất hiện trong lòng bàn tay của Thạch Hạo"}]},"capNhatToi":"@c0575","nguon":["@c0575"]},{"id":"quyen-sach-chu-giet","name":"Quyển sách chữ Giết","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Pháp khí cấp Thần dùng một lần","phamCap":"Cấp Thần","soHuu":["Thạch Hạo"],"trangThai":"Đã giải thể hoàn toàn","blurb":"Quyển sách chữ Giết là đại sát khí lấy từ nội khố Thạch quốc, có khả năng công kích trực tiếp hồn phách. Pháp khí chỉ có thể kích hoạt một lần và đã giải thể hoàn toàn khi được Thạch Hạo dùng đối phó Xuyên sơn giáp màu bạc.","detail":"Pháp khí có nguồn gốc từ nội khố Thạch quốc, mang chữ Giết có thể hóa thành những thanh kiếm máu để đâm thẳng vào hồn phách mục tiêu. Thạch Hạo từng giải thể toàn bộ pháp khí nhằm công kích Xuyên sơn giáp màu bạc đã nhen Thần hỏa, nhưng đòn đánh chỉ khiến mi tâm đối phương chảy máu; sau lần kích hoạt này, pháp khí bị tiêu hao hoàn toàn. @c0577","phanLoaiPhu":"Pháp khí công kích linh hồn dùng một lần","nguonGoc":"Nội khố Thạch quốc","uyLuc":"Có thể nghiền Tôn giả thành bột, nhưng khi công kích Xuyên sơn giáp màu bạc đã nhen Thần hỏa thì chỉ khiến mi tâm đối phương chảy máu, không thể giết chết. @c0577","dacDiem":"Chỉ dùng được một lần và giải thể hoàn toàn sau khi kích hoạt.","chuHienThoi":"Thạch Hạo","congNang":["Chữ Giết hóa thành những thanh kiếm máu, trực tiếp công kích hồn phách mục tiêu. @c0577"],"chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c0577","denChuong":"@c0577","cachCoDuoc":"Lấy từ nội khố Thạch quốc","trangThai":"Đã dùng"}],"tabs":{"tienTrinh":[{"chuong":"@c0577","loai":"dùng","importance":"major","giaiDoan":"Giải thể hoàn toàn","text":"Thạch Hạo dùng pháp khí công kích hồn phách Xuyên sơn giáp màu bạc nhưng chỉ khiến mi tâm đối phương chảy máu, còn quyển sách bị tiêu hao hoàn toàn.","anchor":"Pháp khí cấp Thần này chỉ dùng được một lần, uy lực cực kỳ lớn khó mà tưởng tượng nổi","phamCap":"Cấp Thần"}]},"capNhatToi":"@c0577","nguon":["@c0577"]},{"id":"hoa-sen-than-hoa","name":"Hoa sen thần hỏa","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Đại sát khí dùng một lần","phamCap":"Không rõ","soHuu":["Thạch Hạo"],"trangThai":"Đã dùng","blurb":"Hoa sen thần hỏa là đại sát khí chứa thần hỏa, có thể tạo thành biển lửa thiêu chảy núi đá. Thạch Hạo từng dùng nó đối phó Dương Ly, song không thể giết được đối phương do khả năng phục hồi nhanh chóng.","detail":"Không rõ nguồn gốc. Thạch Hạo phóng hoa sen thần hỏa vào Dương Ly, đốt cháy bàn tay đối phương và khiến núi đá xung quanh hóa thành dung nham; tuy nhiên, Dương Ly nhanh chóng tái sinh da thịt nên đòn đánh không thể ngăn cản hắn. Pháp bảo này chỉ có thể sử dụng một lần. @c0577","phanLoaiPhu":"Vật phẩm thần hỏa dùng một lần","uyLuc":"Tạo biển lửa khiến núi đá tan thành dung nham.","dacDiem":"Chỉ có thể sử dụng một lần.","chuHienThoi":"Thạch Hạo","congNang":["Phóng thần hỏa thiêu hủy mục tiêu và khu vực xung quanh, tạo thành biển lửa khiến núi đá tan thành dung nham. @c0577"],"chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c0577","denChuong":"@c0577","cachCoDuoc":"Không rõ","trangThai":"Đã dùng"}],"tabs":{"tienTrinh":[{"chuong":"@c0577","loai":"dùng","importance":"major","giaiDoan":"Tiêu hao hoàn toàn","text":"Thạch Hạo dùng hoa sen thần hỏa đốt cháy bàn tay Dương Ly nhưng không thể ngăn đối phương nhanh chóng phục hồi.","anchor":"Đây cũng là một đại sát khí, cũng là vật dùng một lần","phamCap":"Không rõ"}]},"capNhatToi":"@c0577","nguon":["@c0577"]},{"id":"co-dan-mau-den-tay-lang-gioi","name":"Cổ đàn màu đen Tây Lăng giới","cn":"","aliases":[],"category":"khac","categoryLabel":"Tế đàn","phamCap":"Không rõ","soHuu":[],"trangThai":"đã kích hoạt","blurb":"Cổ đàn bằng đá đen nằm giữa vô số xương cốt cấp Thiên thần trong Tây Lăng giới, trên đàn đặt ba tế phẩm thần bí. Khi bị Thạch Hạo làm chấn động, tròng mắt trên đàn khóa chặt ba cường giả Thần hỏa và dẫn phát sức mạnh giam cầm họ.","detail":"Cổ đàn tọa lạc giữa những bộ xương cấp Thiên thần đã mất cốt văn; uy nghiêm tại nơi này khiến các cường giả không dám tùy tiện vận dụng thần lực. Trên đàn có ba tế phẩm thần bí, trong đó tròng mắt đã hiển lộ sát cơ khi Thạch Hạo đạp mạnh làm tế đàn chấn động, khóa chặt ba kẻ truy sát thuộc cấp độ Thần hỏa và dẫn phát sức mạnh tiến tới giam cầm họ. @c0578","phanLoaiPhu":"Tế đàn cổ","hinhDang":"Cổ đàn bằng đá màu đen","congNang":["Khi cổ đàn chấn động, tròng mắt trên đàn có thể khóa chặt mục tiêu, từng khóa ba cường giả Thần hỏa. @c0578","Kích phát sát cơ và dẫn phát sức mạnh giam cầm những kẻ tiếp cận. @c0578"],"dacDiem":"Cổ đàn bằng đá đen ở Tây Lăng giới, được bao quanh bởi xương cốt cấp Thiên thần đã mất cốt văn và đặt ba tế phẩm thần bí.","capNhatToi":"@c0578","tabs":{"tienTrinh":[{"chuong":"@c0578","loai":"khai phong","importance":"major","giaiDoan":"Sát cơ được kích hoạt","text":"Thạch Hạo đạp mạnh khiến cổ đàn chấn động, làm tròng mắt trên đàn khóa chặt ba cường giả Thần hỏa và dẫn phát sức mạnh giam cầm.","anchor":"Thạch Hạo giơ chân lên rồi đạp mạnh xuống đất, khiến cả tòa tế đàn chấn động","phamCap":"Không rõ"}]},"nguon":["@c0578"],"uyLuc":"Uy lực mạnh nhất đã hiển lộ là đồng thời khóa chặt và dẫn phát sức mạnh tiến tới giam cầm ba cường giả Thần hỏa. @c0578"},{"id":"xuong-tay-mau-vang","name":"Xương tay màu vàng","cn":"","aliases":[],"category":"khac","categoryLabel":"Tế phẩm thần bí","phamCap":"Không rõ","soHuu":[],"trangThai":"đặt trên cổ đàn","blurb":"Một trong ba tế phẩm thần bí được đặt trên cổ đàn màu đen tại Tây Lăng giới.","detail":"Xương tay màu vàng tỏa ra khí tức thần bí và lưu chuyển sức mạnh kỳ lạ, khiến ba cường giả Thần hỏa coi nó quan trọng hơn việc bắt giữ Thạch Hạo.","phanLoaiPhu":"Tế phẩm","hinhDang":"Một đoạn xương tay màu vàng","dacDiem":"Tỏa khí tức thần bí và chứa sức mạnh kỳ lạ.","capNhatToi":"@c0578","tabs":{"tienTrinh":[{"chuong":"@c0578","loai":"xuất hiện","importance":"normal","giaiDoan":"Hiện trên cổ đàn","text":"Xương tay màu vàng xuất hiện cùng xương sọ thủy tinh và tròng mắt dính máu trên cổ đàn Tây Lăng giới.","anchor":"Một xương tay màu vàng, một xương sọ thủy tinh, một tròng mắt dính máu","phamCap":"Không rõ"}]},"nguon":["@c0578"]},{"id":"khoi-cot-to-khi-thach-thon","name":"Khối cốt tổ khí Thạch thôn","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Tổ khí","phamCap":"Mạnh hơn pháp khí Chân Thần của hoàng cung Thạch quốc","soHuu":["Thạch thôn","Bóng Lông","Tiểu Hồng"],"trangThai":"Đã mở phong ấn","blurb":"Một trong hai tổ khí của Thạch thôn, khối cốt được Bóng Lông và Tiểu Hồng mở phong ấn để đối đầu cường giả Tây Phương giáo. Khi phối hợp với tấm da thú tổ khí, hai cổ khí thể hiện uy năng mạnh hơn pháp khí Chân Thần của hoàng cung Thạch quốc. (+) Một trong hai tổ khí của Thạch thôn, bị nứt sau trận tự bạo của Thạch Hạo. [CAN-SOAT-GOP]","detail":"Khối cốt có nguồn gốc từ Thạch thôn và là một trong hai tổ khí của thôn. Trong trận chiến với cường giả Tây Phương giáo, Bóng Lông và Tiểu Hồng đã mở phong ấn khối cốt cùng tấm da thú, dùng hai cổ khí phối hợp chiến đấu; uy năng của chúng được đánh giá vượt trên pháp khí Chân Thần trong hoàng cung Thạch quốc. @c0580","phanLoaiPhu":"Tổ khí Thạch thôn","nguonGoc":"Thạch thôn","uyLuc":"Khi phối hợp với tấm da thú tổ khí, uy năng của hai cổ khí mạnh hơn pháp khí Chân Thần trong hoàng cung Thạch quốc.","dacDiem":"Là một trong hai tổ khí của Thạch thôn và cần được mở phong ấn để phát huy uy năng.","chuHienThoi":"Thạch thôn","congNang":["Sau khi được mở phong ấn, phối hợp với tấm da thú để hỗ trợ Bóng Lông và Tiểu Hồng chiến đấu chống cường giả Tây Phương giáo. @c0580"],"chuSoHuu":[{"ten":"Thạch thôn","tuChuong":"@c0580","denChuong":"","cachCoDuoc":"Tổ khí của thôn","trangThai":"đang sở hữu"}],"capNhatToi":"@c0580","tabs":{"tienTrinh":[{"chuong":"@c0580","loai":"khai phong","importance":"major","giaiDoan":"Mở phong ấn tổ khí","text":"Bóng Lông và Tiểu Hồng mở phong ấn khối cốt cùng tấm da thú để chống cường giả Tây Phương giáo.","anchor":"lần này Bóng Lông và tiểu Hồng mở ra phong ấn của hai cổ khí","phamCap":"Mạnh hơn pháp khí Chân Thần của hoàng cung Thạch quốc"}]},"nguon":["@c0580","@c0608"]},{"id":"sat-kiem-do-dam-cua-ngan-duc","name":"Sát kiếm đỏ đậm của Ngân Dực","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Sát kiếm","phamCap":"","soHuu":["Ngân Dực"],"trangThai":"hư tổn","blurb":"Thanh sát kiếm đỏ đậm và liên tục nhỏ máu được Ngân Dực sử dụng trong cuộc giao chiến với Quỷ gia.","detail":"Ngân Dực dùng sát kiếm để phối hợp với áo nghĩa sát lục của Thiên quốc. Thanh kiếm bị một kiếm của Quỷ gia đánh rạn nứt.","phanLoaiPhu":"Sát kiếm","hinhDang":"Thanh kiếm đỏ đậm","dacDiem":"Thân kiếm liên tục nhỏ máu.","uyLuc":"Không chống nổi kiếm gãy trong tay Quỷ gia và bị đánh rạn nứt.","chuHienThoi":"Ngân Dực","congNang":["Dùng làm binh khí thi triển đòn sát phạt và áo nghĩa sát lục của Thiên quốc."],"chuSoHuu":[{"ten":"Ngân Dực","tuChuong":"@c0582","denChuong":"","cachCoDuoc":"","trangThai":"đang sở hữu"}],"tabs":{"tienTrinh":[{"chuong":"@c0582","loai":"hư tổn/tu bổ","importance":"normal","giaiDoan":"Bị kiếm gãy áp chế","phamCap":"","text":"Ngân Dực triệu ra sát kiếm đỏ đậm để giao chiến nhưng thanh kiếm bị Quỷ gia đánh rạn nứt.","anchor":"một thanh sát kiếm đỏ đậm vô cùng kỳ lạ xuất hiện ở trong tay"}]},"capNhatToi":"@c0582","nguon":["@c0582"]},{"id":"te-dan-do-cua-ngan-duc","name":"Tế đàn đỏ của Ngân Dực","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Pháp khí huyết tế","phamCap":"Không rõ","soHuu":["Ngân Dực"],"trangThai":"Đã bị phá hủy","blurb":"Tế đàn huyết tế cao ba thước được Ngân Dực dùng để triệu hồi nhiều Thần ma huyết sắc. Trong cuộc đối đầu với Quỷ gia, tế đàn bị chém rạn nứt rồi nổ tung hoàn toàn.","detail":"Tế đàn được khắc đầy ký hiệu, vận hành bằng cách kết hợp tinh huyết của người thi triển với oán khí và linh hồn thu được từ huyết tế. Ngân Dực từng dùng nó để triệu hồi các Thần ma màu máu; sau đó, Quỷ gia chém tế đàn rạn nứt và phá hủy hoàn toàn. @c0583","phanLoaiPhu":"Tế đàn triệu hồi","hinhDang":"Tế đàn đỏ tươi cao ba thước và khắc đầy ký hiệu","uyLuc":"Có thể triệu hồi nhiều Thần ma huyết sắc.","dacDiem":"Tế đàn cao ba thước, khắc đầy ký hiệu, vận hành bằng tinh huyết, oán khí và linh hồn huyết tế; cuối cùng bị Quỷ gia chém nổ tung.","chuHienThoi":"Không còn","congNang":["Triệu hồi nhiều Thần ma huyết sắc từ tinh huyết của người thi triển, oán khí và linh hồn huyết tế. @c0583"],"chuSoHuu":[{"ten":"Ngân Dực","tuChuong":"@c0583","denChuong":"@c0583","cachCoDuoc":"Được tiền bối Thiên quốc ban tặng","trangThai":"Đã mất do tế đàn bị phá hủy"}],"tabs":{"tienTrinh":[{"chuong":"@c0583","loai":"hư tổn/tu bổ","importance":"major","giaiDoan":"Bị phá hủy","text":"Ngân Dực dùng tế đàn triệu hồi Thần ma huyết sắc, nhưng Quỷ gia chém nó rạn nứt rồi nổ tung.","anchor":"tòa tế đàn đỏ tươi kia phát ra tiếng răng rắc sau đó là rạn nứt rồi nổ tung","phamCap":"Không rõ"}]},"capNhatToi":"@c0583","nguon":["@c0583"]},{"id":"hat-hoa-huong-duong-ma-quy","name":"Hạt hoa hướng dương Ma Quỳ","cn":"","category":"khac","categoryLabel":"Vật phẩm chứa thần năng","phamCap":"Không rõ","soHuu":["Thạch Hạo"],"trangThai":"Đã dùng @c0584","blurb":"Hạt từ bản thể hoa hướng dương đen của cường giả Ma Quỳ viên, chứa thần năng có thể bổ sung sức mạnh.","detail":"Sau trận chiến, Thạch Hạo lấy một hạt trong suốt như mặc ngọc cho vào miệng để bổ sung thần năng và bắt đầu chữa thương.","hinhDang":"Hạt trong suốt như mặc ngọc.","nguonGoc":"Bản thể hoa hướng dương đen của cường giả Ma Quỳ viên.","congNang":["Bổ sung thần năng và hỗ trợ người dùng bắt đầu chữa thương. @c0584"],"chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c0584","denChuong":"@c0584","cachCoDuoc":"Thu được sau khi cường giả Ma Quỳ viên tử vong.","trangThai":"Đã dùng"}],"capNhatToi":"@c0584","tabs":{"tienTrinh":[{"chuong":"@c0584","loai":"dùng","importance":"normal","giaiDoan":"Bổ sung thần năng","text":"Thạch Hạo nuốt một hạt hoa hướng dương Ma Quỳ để bổ sung thần năng và chữa thương.","anchor":"lấy ra một hạt hoa hướng dương trong suốt như mặc ngọc nhét vào trong miệng","phamCap":"Không rõ"}]},"nguon":["@c0584"]},{"id":"than-tinh","name":"Thần tinh","cn":"","category":"nguyen-lieu","categoryLabel":"Thần liệu","phamCap":"Kết tinh của Thần cấp cao","soHuu":["Thạch Hạo","Đả Thần Thạch"],"trangThai":"Đang được dùng luyện đại sát khí","blurb":"Kết tinh tử kim hình thành trong thi thể Thần cấp cao, còn chứa thần năng mạnh nhưng bị pha tạp tử khí.","detail":"Hơn mười viên Thần tinh được tìm thấy trong thần hài tại đất cũ Thạch thôn. Chúng không thích hợp để hấp thu trực tiếp nhưng có thể làm căn cơ cho vũ khí Sát đạo.","phanLoaiPhu":"Thần liệu luyện khí","hinhDang":"Viên kết tinh tử kim tròn","nguonGoc":"Hình thành trong thi thể Thần cấp cao","uyLuc":"Còn chứa thần năng đáng sợ dù đã pha tạp tử khí và thần lực hỗn loạn.","dacDiem":"Không thể hấp thu an toàn vì lẫn tử khí.","congNang":["Làm căn cơ luyện đại sát khí."],"chuHienThoi":"Đả Thần Thạch","chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c0585","denChuong":"","cachCoDuoc":"Tìm thấy trong thần hài tại đất cũ Thạch thôn","trangThai":"Đưa vào luyện đại sát khí"},{"ten":"Đả Thần Thạch","tuChuong":"@c0585","denChuong":"","cachCoDuoc":"Được giao chủ trì tế luyện","trangThai":"Đang sử dụng"}],"capNhatToi":"@c0585","tabs":{"tienTrinh":[{"chuong":"@c0585","loai":"xuất hiện","importance":"normal","giaiDoan":"Được phát hiện trong thần hài","phamCap":"Kết tinh của Thần cấp cao","text":"Thần tinh được tìm thấy trong thần hài và được xác định là kết tinh chỉ có thể sinh ra từ Thần cấp cao.","anchor":"Đây chính là Thần tinh, chỉ có Thần cấp cao thì mới có thể phát sinh ra"}]},"nguon":["@c0585"]},{"id":"than-hai-tu-kim","name":"Thần hài tử kim","cn":"","category":"nguyen-lieu","categoryLabel":"Thần liệu","phamCap":"Hài cốt Thần cấp cao","soHuu":["Thạch Hạo","Đả Thần Thạch"],"trangThai":"Đang được tế luyện thành đại sát khí","blurb":"Bộ hài cốt tử kim dài trăm trượng của một Thần cấp cao, được chôn dưới đất cũ Thạch thôn.","detail":"Thần hài vẫn cứng như sắt đá và còn dao động năng lượng sau nhiều năm. Thạch Hạo mang toàn bộ bộ xương về thôn để Đả Thần Thạch phối hợp với Bóng Lông và Tiểu Hồng tế luyện thành đại sát khí.","phanLoaiPhu":"Thần liệu luyện khí","hinhDang":"Bộ xương tử kim dài trăm trượng","vatLieu":"Xương của Thần cấp cao","nguonGoc":"Được phát hiện dưới đất cũ Thạch thôn","uyLuc":"Còn thần năng và uy nghiêm dù phần tinh túy đã bị Liễu Thần hấp thu.","dacDiem":"Cứng như sắt đá, toàn thân có màu tử kim.","congNang":["Dùng làm thần liệu luyện đại sát khí."],"chuHienThoi":"Đả Thần Thạch","chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c0585","denChuong":"","cachCoDuoc":"Đào được tại đất cũ Thạch thôn","trangThai":"Mang về Thạch thôn"},{"ten":"Đả Thần Thạch","tuChuong":"@c0585","denChuong":"","cachCoDuoc":"Được giao chủ trì tế luyện","trangThai":"Đang tế luyện"}],"capNhatToi":"@c0585","tabs":{"tienTrinh":[{"chuong":"@c0585","loai":"dùng","importance":"normal","giaiDoan":"Được dùng luyện đại sát khí","phamCap":"Hài cốt Thần cấp cao","text":"Bộ thần hài được đào lên, mang về Thạch thôn và dùng làm thần liệu cho đại sát khí chuẩn bị trước trận chiến.","anchor":"một bộ Thần thi cấp cao không có phân hủy như vầy, toàn bộ đều là báu vật"}]},"nguon":["@c0585"]},{"id":"chi-ton-huyet-cua-thach-hao","name":"Chí Tôn huyết của Thạch Hạo","cn":"","category":"khac","categoryLabel":"Huyết mạch đặc biệt","phamCap":"Không rõ","soHuu":["Thạch Hạo"],"trangThai":"Tồn tại trong cơ thể Thạch Hạo","blurb":"Dòng máu đặc biệt của Thạch Hạo, được xác định là điều kiện cần để tiến vào Cung điện Chí tôn.","detail":"Từ ký ức trong thức hải của ba vị thần, Thạch Hạo nhận ra Hoàng Vũ muốn lợi dụng Chí Tôn huyết của mình để tìm tạo hóa trong Cung điện Chí tôn.","phanLoaiPhu":"Huyết mạch","nguonGoc":"Thạch Hạo","congNang":["Là điều kiện cần để tiến vào Cung điện Chí tôn."],"dacDiem":"Mang tính chất đặc biệt và gắn với việc mở đường vào Cung điện Chí tôn.","chuHienThoi":"Thạch Hạo","chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c0586","denChuong":"","cachCoDuoc":"Huyết mạch trong cơ thể","trangThai":"Đang sở hữu"}],"tabs":{"tienTrinh":[{"chuong":"@c0586","loai":"xuất hiện","importance":"normal","giaiDoan":"Lộ công dụng","text":"Thạch Hạo nhận ra Chí Tôn huyết đặc biệt là điều kiện để tiến vào Cung điện Chí tôn và là mục tiêu thật sự của Hoàng Vũ.","anchor":"nó phát hiện trong thức hải của ba Thần rằng muốn vào Cung điện Chí tôn thì cần phải có Chí Tôn huyết đặc biệt","phamCap":"Không rõ"}]},"capNhatToi":"@c0586","nguon":["@c0586"]},{"id":"phu-cot-mau-tim","name":"Phù cốt màu tím","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Đại sát khí dùng một lần","phanLoaiPhu":"Phù cốt phát nổ","phamCap":"Luyện từ kết tinh Thần linh cấp cao và Thần cốt","soHuu":["Thạch Hạo"],"trangThai":"Đã kích nổ","blurb":"Đại sát khí dùng một lần được Thạch Hạo bí mật bố trí trong hư không. Vụ nổ làm Hoàng Vũ rách đạo bào và chảy máu nhưng không gây trọng thương.","detail":"Phù cốt màu tím được luyện từ kết tinh của Thần linh cấp cao cùng Thần cốt. Thạch Hạo bố trí các khối phù cốt trong lúc chạy trốn, dụ Hoàng Vũ tiến vào phạm vi rồi kích nổ toàn bộ.","vatLieu":"Kết tinh Thần linh cấp cao và Thần cốt","nguonGoc":"Đại sát khí do Thạch Hạo chuẩn bị trước trận phản kích","uyLuc":"Vụ nổ phá nát đạo bào và làm Hoàng Vũ chảy máu nhưng chưa đủ gây trọng thương.","dacDiem":"Có thể ẩn trong hư không và chỉ dùng được một lần.","chuHienThoi":"Thạch Hạo","congNang":["Ẩn trong hư không để phục kích mục tiêu.","Phát nổ trên diện rộng khi được kích hoạt."],"chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c0587","denChuong":"@c0587","cachCoDuoc":"Đã chuẩn bị và bố trí trước trong hư không","trangThai":"Đã sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c0587","loai":"dùng","importance":"normal","giaiDoan":"Kích nổ phục kích","phamCap":"Đại sát khí dùng một lần","text":"Thạch Hạo kích nổ các khối phù cốt màu tím đã bố trí trong hư không, khiến Hoàng Vũ bị thương nhẹ.","anchor":"đây chính lúc Thạch Hạo chạy trốn đã bố trí ẩn trong hư không, lúc này hoàn toàn cho nổ tung"}]},"capNhatToi":"@c0587","nguon":["@c0587"]},{"id":"con-roi-hinh-nguoi-cua-hoang-vu","name":"Con rối hình người của Hoàng Vũ","cn":"","category":"khac","categoryLabel":"Con rối thế mạng","phamCap":"Không rõ","soHuu":["Hoàng Vũ"],"trangThai":"hong","blurb":"Con rối hình người được Hoàng Vũ chuẩn bị làm vật thế mạng. Nó đã chịu thay Hoàng Vũ một đòn mang sức mạnh Luân hồi từ Chí Tôn cốt, sau đó mục nát và giải thể hoàn toàn.","detail":"Tại thời điểm Hoàng Vũ đối mặt với sức mạnh Luân hồi từ Chí Tôn cốt, con rối hình người được dùng để hứng trọn đòn đánh thay chủ nhân. Sau khi hoàn thành vai trò thế mạng, nó nhanh chóng mục nát rồi giải thể hoàn toàn. @c0588","phanLoaiPhu":"Con rối hình người","congNang":["Thế mạng và đỡ thay Hoàng Vũ một đòn mang sức mạnh Luân hồi từ Chí Tôn cốt. @c0588"],"chuHienThoi":"Hoàng Vũ","chuSoHuu":[{"ten":"Hoàng Vũ","tuChuong":"@c0588","denChuong":"@c0588","cachCoDuoc":"Đã được chuẩn bị sẵn","trangThai":"đã dùng và bị phá hủy"}],"capNhatToi":"@c0588","tabs":{"tienTrinh":[{"chuong":"@c0588","loai":"hư tổn/tu bổ","importance":"major","giaiDoan":"Thế mạng rồi tan rã","text":"Con rối đỡ sức mạnh Luân hồi thay Hoàng Vũ rồi mục nát và giải thể hoàn toàn.","anchor":"Lão dùng một con rối để đỡ một đòn Chí Tôn cốt","phamCap":"Không rõ"}]},"nguon":["@c0588"],"uyLuc":"Có thể chịu thay Hoàng Vũ một đòn mang sức mạnh Luân hồi từ Chí Tôn cốt, nhưng sau đó mục nát và giải thể hoàn toàn. @c0588","dacDiem":"Con rối hình người dùng một lần; sau khi thế mạng thì mục nát và giải thể hoàn toàn. @c0588"},{"id":"nhan-phap-khi-cua-hoang-vu","name":"Nhẫn pháp khí của Hoàng Vũ","aliases":["Nhẫn ngón cái của Hoàng Vũ","Chiếc nhẫn của Hoàng Vũ"],"cn":"","category":"phap-bao","categoryLabel":"Pháp khí hộ thân","phamCap":"Không rõ","soHuu":["Hoàng Vũ"],"trangThai":"dang-co","blurb":"Chiếc nhẫn đeo trên ngón cái của Hoàng Vũ có khả năng hộ thân khi giao chiến.","detail":"Pháp khí phát sáng trong lúc Hoàng Vũ đối chưởng với Thạch Hạo, giúp lão giảm hậu quả từ thần lực của khối cốt Chân thần.","phanLoaiPhu":"Nhẫn hộ thân","congNang":["Phát sáng bảo vệ Hoàng Vũ khi đối chưởng tại @c0588."],"chuHienThoi":"Hoàng Vũ","chuSoHuu":[{"ten":"Hoàng Vũ","tuChuong":"@c0588","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"đang sở hữu"}],"capNhatToi":"@c0588","tabs":{"tienTrinh":[{"chuong":"@c0588","loai":"dùng","importance":"normal","giaiDoan":"Hộ thân khi đối chưởng","text":"Chiếc nhẫn phát sáng và giúp Hoàng Vũ tránh chịu thương thế nặng hơn khi đối chưởng với Thạch Hạo.","anchor":"nếu không phải chiếc nhẫn trên ngón cái của lão phát sáng thì đã ăn quả đắng rồi","phamCap":"Không rõ"}]},"nguon":["@c0588"]},{"id":"than-dan-tang-cuong-suc-song-cua-tien-dien","name":"Thần đan tăng cường sức sống của Tiên điện","cn":"","category":"dan-duoc","categoryLabel":"Đan dược","phamCap":"Thần đan","soHuu":["Hoàng Vũ"],"trangThai":"đã luyện hóa hoàn toàn","blurb":"Thần đan do Tiên điện ban cho Hoàng Vũ khi lão hạ giới, có tác dụng tăng cường sức sống. Phần dược lực còn lại sau đó được luyện hóa hoàn toàn, giúp lão chữa lành thương thế và khôi phục chiến lực.","detail":"Thần đan có nguồn gốc từ Tiên điện, được ban cho Hoàng Vũ khi lão hạ giới. Tại @c0589, phù văn Chí Tôn của Thạch Hạo đã thúc đẩy Hoàng Vũ luyện hóa hết phần dược lực còn tồn đọng trong cơ thể; nhờ đó thương thế của lão khép lại, sức sống được tăng cường và chiến lực được khôi phục.","nguonGoc":"Tiên điện ban cho Hoàng Vũ khi hạ giới","congNang":["Tăng cường sức sống của người dùng. @c0589","Sau khi được luyện hóa hoàn toàn, dược lực có thể chữa lành thương thế và khôi phục chiến lực. @c0589"],"chuHienThoi":"Hoàng Vũ","chuSoHuu":[{"ten":"Hoàng Vũ","tuChuong":"@c0589","denChuong":"@c0589","cachCoDuoc":"Được Tiên điện ban khi hạ giới","trangThai":"đã luyện hóa"}],"tabs":{"tienTrinh":[{"chuong":"@c0589","loai":"dùng","importance":"major","giaiDoan":"Luyện hóa hoàn toàn","text":"Phù văn Chí Tôn giúp Hoàng Vũ luyện hóa hết dược lực còn lại của thần đan, chữa lành thương thế và khôi phục chiến lực đỉnh cao.","anchor":"Tiên điện từng tặng cho ta một viên thần đan để tăng cường sức sống","phamCap":"Thần đan"}]},"capNhatToi":"@c0589","nguon":["@c0589"]},{"id":"bua-nho-hoang-kim","name":"Búa nhỏ hoàng kim","cn":"","aliases":["Búa nhỏ màu vàng của Hoàng Vũ"],"category":"phap-bao","categoryLabel":"Pháp khí","phamCap":"Không rõ","soHuu":["Hoàng Vũ"],"trangThai":"đang sử dụng","blurb":"Pháp khí hình búa nhỏ màu vàng của Hoàng Vũ, có thể phát ra sấm sét và tia chớp.","detail":"Hoàng Vũ dùng búa nhỏ hoàng kim liên tục đánh xuống trong cuộc truy sát. Va chạm giữa nó và pháp khí Chân thần khiến Thạch Hạo chấn động, ho ra máu.","hinhDang":"Búa nhỏ màu vàng","congNang":["Phát ra sấm sét và tia chớp để công kích mục tiêu tại @c0589."],"uyLuc":"Va chạm với pháp khí Chân thần khiến Thạch Hạo bị chấn động và ho ra máu.","chuHienThoi":"Hoàng Vũ","chuSoHuu":[{"ten":"Hoàng Vũ","tuChuong":"@c0589","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"đang sở hữu"}],"tabs":{"tienTrinh":[{"chuong":"@c0589","loai":"dùng","importance":"normal","giaiDoan":"Truy sát Thạch Hạo","text":"Hoàng Vũ dùng búa nhỏ phát sấm sét và tia chớp công kích Thạch Hạo.","anchor":"búa nhỏ phát ra âm thanh sấm sét, tia chớp lại đánh xuống","phamCap":"Không rõ"}]},"capNhatToi":"@c0589","nguon":["@c0589"]},{"id":"phap-khi-chan-than-cua-thach-hao","name":"Pháp khí Chân thần của Thạch Hạo","cn":"","category":"phap-bao","categoryLabel":"Pháp khí","phamCap":"Chân Thần","soHuu":["Thạch Hạo"],"trangThai":"nhiều món đã bị huyết tế","blurb":"Nhóm pháp khí cấp Chân Thần được Thạch Hạo sử dụng để đối kháng pháp khí của Hoàng Vũ và phá vòng vây pháp tắc hoàng kim. Nhiều món đã bị huyết tế để mở đường thoát tại @c0589.","detail":"Thạch Hạo dùng các pháp khí Chân Thần đối đầu pháp khí của Hoàng Vũ. Khi bị các cột vàng của pháp tắc hoàng kim vây kín, hắn huyết tế nhiều món, qua đó mở một lỗ hổng trong vòng vây và thoát ra @c0589.","congNang":["Đối kháng pháp khí của Hoàng Vũ @c0589.","Có thể được huyết tế để mở một lỗ hổng trong vòng vây của pháp tắc hoàng kim @c0589."],"chuHienThoi":"Thạch Hạo","chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c0589","denChuong":"@c0589","cachCoDuoc":"Không rõ","trangThai":"nhiều món đã bị huyết tế"}],"tabs":{"tienTrinh":[{"chuong":"@c0589","loai":"hư tổn/tu bổ","importance":"major","giaiDoan":"Huyết tế phá vây","text":"Thạch Hạo huyết tế nhiều pháp khí Chân thần để mở một lỗ hổng trong vòng vây của pháp tắc hoàng kim.","anchor":"nó cắn răng huyết tế mấy thanh pháp khí Chân thần thì mới tạo ra một lỗ hổng","phamCap":"Chân Thần"}]},"capNhatToi":"@c0589","nguon":["@c0589"],"uyLuc":"Sau khi nhiều món bị huyết tế, chúng có thể mở một lỗ hổng trong vòng vây của pháp tắc hoàng kim @c0589.","dacDiem":"Là một nhóm gồm nhiều pháp khí cấp Chân Thần; nhiều món đã bị Thạch Hạo huyết tế @c0589."},{"id":"duong-ngu","name":"Dương ngư","cn":"","category":"khac","categoryLabel":"Dị chủng","phamCap":"Không rõ","soHuu":[],"trangThai":"sống trong biển dung nham","blurb":"Biến chủng của Hỏa Viêm ngư sinh sống trong dung nham tại tổ địa Hỏa quốc.","detail":"Hoàng Vũ nhận định Dương ngư có thể dừng lại trong Thái dương và ẩn chứa lượng vật chất thần tính đáng kinh ngạc.","phanLoaiPhu":"Biến chủng của Hỏa Viêm ngư","dacDiem":"Sống trong dung nham và chứa vật chất thần tính.","congNang":["Ẩn chứa vật chất thần tính đáng kinh ngạc tại @c0589."],"tabs":{"tienTrinh":[{"chuong":"@c0589","loai":"xuất hiện","importance":"normal","giaiDoan":"Được phát hiện trong dung nham","text":"Dương ngư xuất hiện trong biển dung nham tại tổ địa Hỏa quốc và được nhận định chứa vật chất thần tính đáng kinh ngạc.","anchor":"được xưng là có thể dừng lại trong Thái dương, ẩn chứa vật chất thần tính kinh người","phamCap":"Không rõ"}]},"capNhatToi":"@c0589","nguon":["@c0589"]},{"id":"hoang-kim-phien","name":"Hoàng Kim phiến","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Pháp khí lông chim","phamCap":"Không rõ","soHuu":["Hoàng Vũ"],"trangThai":"Đang được Hoàng Vũ sử dụng","blurb":"Chiếc quạt bện từ lông chim của Hoàng Vũ, có thể tạo ra lốc xoáy màu vàng với sức phá hoại lớn.","detail":"Hoàng Vũ dùng Hoàng Kim phiến quạt ra lốc xoáy vàng, biến hàng chục ngọn núi thành tro và đánh Thạch Hạo văng xa dù đối phương có pháp khí Chân thần bảo vệ.","phanLoaiPhu":"Quạt lông chim","hinhDang":"Chiếc quạt bện từ lông chim","vatLieu":"Lông chim","uyLuc":"Một lần quạt có thể tạo lốc xoáy vàng phá hủy hàng chục ngọn núi.","dacDiem":"Tạo lốc xoáy màu vàng.","chuHienThoi":"Hoàng Vũ","congNang":["Tạo lốc xoáy màu vàng để phá hủy địa hình và đánh văng mục tiêu."],"chuSoHuu":[{"ten":"Hoàng Vũ","tuChuong":"@c0590","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"đang-giữ"}],"capNhatToi":"@c0590","tabs":{"tienTrinh":[{"chuong":"@c0590","loai":"dùng","importance":"normal","giaiDoan":"Truy sát Thạch Hạo","text":"Hoàng Vũ dùng Hoàng Kim phiến tạo lốc xoáy vàng, phá hủy hàng chục ngọn núi và đánh Thạch Hạo văng xa.","anchor":"thanh pháp khí này được bện thành từ lông chim, quạt mạnh một cái thì lốc xoáy xuất hiện","phamCap":"Không rõ"}]},"nguon":["@c0590"]},{"id":"bong-mo-tien-dien-bang-dong","name":"Bóng mờ Tiên điện bằng đồng","cn":"","aliases":["Bóng mờ Tiên điện"],"category":"than-khi","categoryLabel":"Bóng mờ chí bảo Tiên đạo","phamCap":"Chí bảo Tiên đạo","soHuu":["Hoàng Vũ"],"trangThai":"Được triệu hồi từ cơ thể Hoàng Vũ","blurb":"Bóng mờ của một tòa Tiên điện bằng đồng khổng lồ tại thượng giới, được một vị đại nhân của Tiên điện truyền vào cơ thể Hoàng Vũ. Khi được triệu hồi, nó dùng uy áp trấn áp Thạch Hạo và gần như dập tắt ngọn lửa tế sống của hắn.","detail":"Bóng mờ Tiên điện bằng đồng bắt nguồn từ thực thể Tiên điện bằng đồng tại thượng giới và được một vị đại nhân của Tiên điện truyền vào cơ thể Hoàng Vũ. Hoàng Vũ từng triệu hồi nó để trấn áp thế tế sống của Thạch Hạo; uy áp giáng xuống gần như dập tắt ngọn lửa hiến tế, đồng thời khiến thân thể Thạch Hạo rạn nứt. @c0590","phanLoaiPhu":"Bóng mờ chí bảo","hinhDang":"Tòa Tiên điện bằng đồng khổng lồ và nguy nga","vatLieu":"Đồng","nguonGoc":"Do một vị đại nhân của Tiên điện truyền vào cơ thể Hoàng Vũ","uyLuc":"Uy áp của bóng mờ gần như dập tắt thế tế sống và khiến thân thể Thạch Hạo rạn nứt. @c0590","dacDiem":"Là bóng mờ của thực thể Tiên điện bằng đồng khổng lồ tại thượng giới, được cất giữ trong cơ thể Hoàng Vũ.","chuHienThoi":"Hoàng Vũ","congNang":["Trấn áp mục tiêu bằng uy áp. @c0590","Phá thế tế sống, gần như dập tắt ngọn lửa hiến tế của Thạch Hạo. @c0590"],"chuSoHuu":[{"ten":"Hoàng Vũ","tuChuong":"@c0590","denChuong":"","cachCoDuoc":"Được một vị đại nhân của Tiên điện truyền vào cơ thể","trangThai":"đang-mang"}],"capNhatToi":"@c0590","tabs":{"tienTrinh":[{"chuong":"@c0590","loai":"xuất hiện","importance":"major","giaiDoan":"Trấn áp tế sống","text":"Hoàng Vũ triệu hồi bóng mờ Tiên điện bằng đồng từ cơ thể, gần như dập tắt ngọn lửa tế sống của Thạch Hạo.","anchor":"đó là một tòa Tiên điện bằng đồng, khổng lồ vô biên, nguy nga hùng vĩ","phamCap":"Chí bảo Tiên đạo"}]},"nguon":["@c0590"]},{"id":"canh-lieu-lieu-than-luu-lai","name":"Cành liễu Liễu Thần lưu lại","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Tín vật cứu mạng","phanLoaiPhu":"Cành cây lưu giữ sức sống","phamCap":"Không rõ","soHuu":["Thạch Hạo"],"chuHienThoi":"Thạch Hạo","trangThai":"Đã tiêu hao các chồi non để chữa thương","blurb":"Cành liễu do Liễu Thần trao cho Thạch Hạo, bất ngờ thức tỉnh khi nó sắp chết.","detail":"Cành liễu phát ra ánh sáng xanh, kéo huyết nhục, xương vỡ và tàn cốt trở về rồi tạm ghép lại thân thể Thạch Hạo. Các chồi non lần lượt tiêu hao trong quá trình chữa thương, còn sức sống lưu lại không đủ áp chế quy tắc Tiên điện.","hinhDang":"Một cành liễu gần khô quắc còn các chồi non.","nguonGoc":"Liễu Thần trao cho Thạch Hạo trước khi nó tới ổ Côn bằng ở Bắc Hải.","uyLuc":"Có thể thu hồi những phần thân thể bị đánh văng và tạm gây dựng lại cơ thể của Thạch Hạo.","dacDiem":"Các chồi non tiêu hao để chữa thương nhưng không còn pháp tắc đủ mạnh nhằm áp chế quy tắc Tiên điện.","congNang":["Thu hồi huyết nhục, xương vỡ và tàn cốt của Thạch Hạo.","Tạm ghép và chữa trị thân thể đang tan rã."],"chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c0591","denChuong":"","cachCoDuoc":"Được Liễu Thần trao để dùng khi gặp nguy hiểm.","trangThai":"Đang giữ"}],"capNhatToi":"@c0591","tabs":{"tienTrinh":[{"chuong":"@c0591","loai":"dùng","importance":"normal","giaiDoan":"Thức tỉnh cứu mạng","text":"Cành liễu thức tỉnh khi Thạch Hạo cận tử, kéo xương thịt trở về và dùng các chồi non để tạm ghép lại thân thể.","anchor":"cành cây này lại thức tỉnh tỏa ra ánh sáng xanh biếc lấp lánh, kéo huyết nhục và các mãnh xương cốt trở về lại","phamCap":"Không rõ"}]},"nguon":["@c0591"]},{"id":"phap-kiem-than-linh-bi-ton-hai","name":"Pháp kiếm Thần linh bị tổn hại","cn":"","aliases":[],"category":"than-khi","categoryLabel":"Thần binh","phamCap":"Thần linh","soHuu":["Thạch quốc"],"trangThai":"Đã tổn hại","blurb":"Một số pháp kiếm Thần linh bị hư hại trong thần chiến và được Thạch Hạo giao lại cho thị vệ hoàng cung Thạch quốc.","detail":"Các pháp kiếm đã bị tổn hại sau trận chiến với Hoàng Vũ. Thạch Hạo mang chúng về hoàng cung và giao lại cho người của Thạch quốc.","phanLoaiPhu":"Pháp kiếm","chuHienThoi":"Thạch quốc","capNhatToi":"@c0592","chuSoHuu":[{"ten":"Thạch quốc","tuChuong":"@c0592","denChuong":"","cachCoDuoc":"Được Thạch Hạo giao lại tại hoàng cung.","trangThai":"Đang giữ"}],"tabs":{"tienTrinh":[{"chuong":"@c0592","loai":"đổi chủ","importance":"normal","giaiDoan":"Được giao lại cho Thạch quốc","text":"Thạch Hạo giao các pháp kiếm Thần linh đã tổn hại cho thị vệ hoàng cung Thạch quốc.","anchor":"còn có một vào pháp kiếm thần linh đã tổn hại cho bọn họ."}]},"nguon":["@c0592"]},{"id":"te-dan-truyen-tong-hoang-cung-thach-quoc","name":"Tế đàn truyền tống hoàng cung Thạch quốc","cn":"","aliases":[],"category":"khac","categoryLabel":"Tế đàn truyền tống","phamCap":"Không rõ","soHuu":["Thạch quốc"],"trangThai":"Đang hoạt động","blurb":"Tế đàn trong hoàng cung Thạch quốc có thể mở thông đạo truyền tống đường dài.","detail":"Thạch Hạo kích hoạt tế đàn để mở thông đạo, rời hoàng cung và nhanh chóng tới Bất Lão sơn khi sinh mệnh không còn nhiều.","phanLoaiPhu":"Tế đàn","chuHienThoi":"Thạch quốc","capNhatToi":"@c0592","congNang":["Mở thông đạo truyền tống giúp người sử dụng nhanh chóng rời hoàng cung Thạch quốc @c0592"],"chuSoHuu":[{"ten":"Thạch quốc","tuChuong":"@c0592","denChuong":"","cachCoDuoc":"Được đặt trong hoàng cung Thạch quốc.","trangThai":"Đang giữ"}],"tabs":{"tienTrinh":[{"chuong":"@c0592","loai":"dùng","importance":"normal","giaiDoan":"Đưa Thạch Hạo tới Bất Lão sơn","text":"Thạch Hạo mở tế đàn, tiến vào thông đạo và rời khỏi hoàng cung Thạch quốc.","anchor":"Nó mở tế đàn, tiến vào trong thông đạo cứ thế biến mất, rời khỏi hoàng cung Thạch quốc."}]},"nguon":["@c0592"]},{"id":"phap-y-than-linh-cua-tan-hao","name":"Pháp y thần linh của Tần Hạo","cn":"","aliases":["Pháp y thần linh màu bạc của Tần Hạo"],"category":"phap-bao","categoryLabel":"Pháp y","phamCap":"Thần linh","soHuu":["Tần Hạo"],"trangThai":"Đang được Tần Hạo mặc","blurb":"Pháp y thần linh màu bạc của Tần Hạo, tỏa ánh sáng trắng bạc khi người mặc xuất hiện.","detail":"Tần Hạo mặc pháp y này khi xuất hiện lăng không tại Bất Lão sơn. Ánh sáng trắng bạc khiến dáng vẻ của nó thêm thần thánh và siêu nhiên.","phanLoaiPhu":"Pháp y","hinhDang":"Chiến y màu trắng bạc phát sáng","dacDiem":"Tỏa ánh sáng trắng bạc quanh người mặc.","chuHienThoi":"Tần Hạo","chuSoHuu":[{"ten":"Tần Hạo","tuChuong":"@c0593","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"đang sở hữu"}],"capNhatToi":"@c0593","tabs":{"tienTrinh":[{"chuong":"@c0593","loai":"xuất hiện","importance":"normal","giaiDoan":"Tần Hạo xuất hiện tại Bất Lão sơn","text":"Tần Hạo mặc pháp y thần linh màu bạc và lăng không xuất hiện.","anchor":"một thiếu niên mặc pháp y thần linh màu bạc xuất hiện lăng không mà tới","phamCap":"Thần linh"}]},"nguon":["@c0593"]},{"id":"tien-cot-trong-co-the-tan-hao","name":"Tiên cốt trong cơ thể Tần Hạo","cn":"","aliases":["Tiên cốt của Tần Hạo"],"category":"khac","categoryLabel":"Tiên cốt cấy ghép","phamCap":"Tiên cốt","soHuu":["Tần Hạo"],"trangThai":"Đã cấy thành công trong cơ thể Tần Hạo","blurb":"Tiên cốt là khối cốt đã được cấy thành công và tồn tại trong cơ thể Tần Hạo. Khi các phương pháp cứu chữa Thạch Hạo đều thất bại, lão dược sư cho rằng có thể dùng nó để cứu mạng Thạch Hạo, nhưng phải trả giá rất lớn.","detail":"Tiên cốt được cấy vào cơ thể Tần Hạo và đã dung nhập thành công. Đến khi việc cứu chữa Thạch Hạo lâm vào bế tắc, lão dược sư đề xuất sử dụng khối Tiên cốt này làm phương án cứu mạng, dù cách làm ấy đòi hỏi một cái giá rất lớn. @c0593","phanLoaiPhu":"Tiên cốt cấy ghép","nguonGoc":"Được cấy vào cơ thể Tần Hạo","congNang":["Có khả năng được dùng để cứu mạng Thạch Hạo. @c0593"],"dacDiem":"Đã được cấy thành công và tồn tại trong cơ thể Tần Hạo.","chuHienThoi":"Tần Hạo","chuSoHuu":[{"ten":"Tần Hạo","tuChuong":"@c0593","denChuong":"","cachCoDuoc":"Được cấy vào cơ thể","trangThai":"đang mang trong cơ thể"}],"capNhatToi":"@c0593","tabs":{"tienTrinh":[{"chuong":"@c0593","loai":"nhắc tới","importance":"major","giaiDoan":"Được đề xuất dùng cứu Thạch Hạo","text":"Lão dược sư xác nhận Tiên cốt đã được cấy thành công trong cơ thể Tần Hạo và đề xuất dùng nó để cứu Thạch Hạo.","anchor":"Nhị công từ trong cơ thể đã cấy thành công một khối Tiên cốt, cũng có thể cứu được Thạch Hoàng.","phamCap":"Tiên cốt"}]},"nguon":["@c0593"]},{"id":"hoang-kim-dich-cua-than-thu-thai-duong","name":"Hoàng Kim dịch của thần thụ Thái Dương","cn":"","aliases":[],"category":"dan-duoc","categoryLabel":"Thần dịch cứu mạng","phamCap":"Chưa rõ","soHuu":["Thạch Hạo"],"trangThai":"Đã dùng một giọt","blurb":"Thần dịch lấy từ thần thụ Thái Dương, được dùng để tạm giữ sinh cơ cho Thạch Hạo.","detail":"Cha mẹ cho Thạch Hạo nuốt một giọt Hoàng Kim dịch sau khi nó hôn mê. Thần dịch giúp tạm giữ hơi thở và khiến nó tỉnh lại sau một ngày hai đêm, nhưng không chữa khỏi thương thế chí tử.","phanLoaiPhu":"Thần dịch","nguonGoc":"Thần thụ Thái Dương","congNang":["Tạm thời giữ lại hơi thở cho người đang mang thương thế chí tử."],"uyLuc":"Giữ Thạch Hạo chưa chết sau thời gian hôn mê nhưng không chữa được căn nguyên thương thế.","chuHienThoi":"Thạch Hạo","chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c0593","denChuong":"@c0593","cachCoDuoc":"Được cha mẹ cho dùng","trangThai":"đã dùng"}],"capNhatToi":"@c0593","tabs":{"tienTrinh":[{"chuong":"@c0593","loai":"dùng","importance":"normal","giaiDoan":"Tạm giữ mạng Thạch Hạo","text":"Cha mẹ cho Thạch Hạo nuốt một giọt Hoàng Kim dịch để tạm thời giữ lại hơi thở.","anchor":"ba mẹ đã cho nó nuốt giọt Hoàng Kim dịch của thần thụ Thái dương kia","phamCap":"Chưa rõ"}]},"nguon":["@c0593"]},{"id":"te-dan-truyen-tong-hac-thach-thanh","name":"Tế đàn truyền tống Hắc Thạch thành","cn":"","aliases":[],"category":"khac","categoryLabel":"Tế đàn truyền tống","phamCap":"Chưa rõ","soHuu":[],"trangThai":"Đã được sửa chữa","blurb":"Tế đàn truyền tống lâu năm không được tu sửa tại Hắc Thạch thành. Thạch Hạo mất nửa canh giờ khôi phục nó để chuẩn bị mở thông lộ.","detail":"Tế đàn ban đầu bị hỏng do lâu năm không được tu sửa. Nhờ kiến thức trận pháp tích lũy, Thạch Hạo sửa thành công nhưng chưa kịp rời đi thì cha mẹ đã tìm tới.","phanLoaiPhu":"Tế đàn truyền tống","dacDiem":"Từng bị hỏng vì lâu năm không được tu sửa.","congNang":["Mở thông lộ truyền tống sau khi được sửa chữa."],"capNhatToi":"@c0593","tabs":{"tienTrinh":[{"chuong":"@c0593","loai":"hư tổn/tu bổ","importance":"normal","giaiDoan":"Được Thạch Hạo sửa chữa","text":"Thạch Hạo mất nửa canh giờ sửa thành công tế đàn truyền tống đã bị hỏng.","anchor":"Sau nửa canh giờ, nó đã sửa thành công","phamCap":"Chưa rõ"}]},"nguon":["@c0593"]},{"id":"chen-khac-phu-van-nguyen-rua","name":"Chén khắc phù văn nguyền rủa","cn":"","aliases":["Chén nguyền rủa"],"category":"phap-bao","categoryLabel":"Pháp khí ám hại","phamCap":"Không rõ","soHuu":[],"trangThai":"Bị phát hiện","blurb":"Một chiếc bát ngọc giả dạng chén linh nhưng được khắc phù văn nguyền rủa. Nếu dùng lâu cho bệnh nhân, nó sẽ âm thầm gây tổn thương nghiêm trọng.","detail":"Chiếc chén được đưa tới khi các Vương chuẩn bị hòa tan thánh dược cho Thạch Hạo. Chiến vương nhận ra linh khí dao động bất thường và phát hiện phù văn nguyền rủa ẩn bên trong.","phanLoaiPhu":"Pháp khí ám hại","hinhDang":"Bát ngọc","uyLuc":"Có thể gây tổn thương lớn cho bệnh nhân nếu được sử dụng lâu.","dacDiem":"Bề ngoài tỏa linh khí như một chiếc chén linh.","congNang":["Âm thầm dùng phù văn nguyền rủa làm bệnh nhân tổn thương."],"capNhatToi":"@c0595","tabs":{"tienTrinh":[{"chuong":"@c0595","loai":"xuất hiện","importance":"normal","giaiDoan":"Bị Chiến vương phát hiện","text":"Chiến vương phát hiện chiếc chén dùng để hòa thánh dược thực chất được khắc phù văn nguyền rủa gây hại cho bệnh nhân.","anchor":"có khắc phù văn nguyền rủa, nếu sử dụng lâu thì sẽ gây tổn thương rất lớn với bệnh nhân"}]},"nguon":["@c0595"]},{"id":"chien-mau-hoang-kim-cua-thach-tu-lang","name":"Chiến mâu hoàng kim của Thạch Tử Lăng","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Binh khí","phamCap":"Không rõ","soHuu":["Thạch Tử Lăng"],"trangThai":"Đang được sở hữu","blurb":"Một thanh chiến mâu màu vàng xuất hiện trong tay Thạch Tử Lăng khi hắn chuẩn bị giao chiến để bảo vệ Thạch Hạo.","detail":"Thạch Tử Lăng triệu chiến mâu sau khi nhận ra người Tần tộc vừa âm thầm mưu hại con trai mình.","phanLoaiPhu":"Chiến mâu","hinhDang":"Thanh chiến mâu màu vàng","chuHienThoi":"Thạch Tử Lăng","chuSoHuu":[{"ten":"Thạch Tử Lăng","tuChuong":"@c0595","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"Đang sở hữu"}],"capNhatToi":"@c0595","tabs":{"tienTrinh":[{"chuong":"@c0595","loai":"dùng","importance":"normal","giaiDoan":"Triệu ra chuẩn bị giao chiến","text":"Thạch Tử Lăng triệu chiến mâu hoàng kim khi sẵn sàng giao chiến với những người Tần tộc.","anchor":"trong tay của hắn xuất hiện một thanh chiến mâu hoàng kim"}]},"nguon":["@c0595"]},{"id":"gay-go-cua-ba-lao-tan-toc","name":"Gậy gỗ của bà lão Tần tộc","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Bảo cụ","phamCap":"Không rõ","soHuu":["Bà lão cầm gậy gỗ"],"trangThai":"Bị đánh gãy","blurb":"Bảo cụ dạng gậy gỗ do một bà lão Tần tộc sử dụng trong cuộc xung đột tại Bất Lão sơn. Khi bà dùng nó chống lại Bằng Cửu, gậy đã bị Bằng trảo màu vàng đánh gãy.","detail":"Gậy gỗ thuộc quyền sử dụng của một bà lão Tần tộc. Trong cuộc xung đột tại Bất Lão sơn, bà vung gậy chống lại Bằng Cửu, nhưng bảo cụ không thể ngăn cản đối phương và bị Bằng trảo màu vàng đánh gãy @c0595.","phanLoaiPhu":"Bảo cụ dạng gậy","hinhDang":"Gậy gỗ","chuHienThoi":"Bà lão cầm gậy gỗ","chuSoHuu":[{"ten":"Bà lão cầm gậy gỗ","tuChuong":"@c0595","denChuong":"@c0595","cachCoDuoc":"Không rõ","trangThai":"Bị đánh gãy"}],"capNhatToi":"@c0595","tabs":{"tienTrinh":[{"chuong":"@c0595","loai":"hư tổn/tu bổ","importance":"major","giaiDoan":"Bị Bằng Cửu đánh gãy","text":"Bà lão dùng gậy gỗ chống lại Bằng Cửu nhưng bảo cụ bị Bằng trảo màu vàng đánh gãy.","anchor":"gậy vỗ vung lên, đây là một bảo cụ, muốn chống lại"}]},"nguon":["@c0595"],"dacDiem":"Có hình dạng một cây gậy bằng gỗ; đã bị Bằng trảo màu vàng của Bằng Cửu đánh gãy @c0595.","congNang":["Được dùng làm bảo cụ để giao chiến, trực tiếp chống lại Bằng Cửu @c0595."]},{"id":"phap-khi-cap-than-cua-thach-quoc","name":"Pháp khí cấp Thần của Thạch quốc","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Pháp khí","phamCap":"Cấp Thần","soHuu":["Thạch quốc"],"trangThai":"đang sử dụng","blurb":"Những pháp khí cấp Thần được ba đại Tôn giả mang tới để gây sức ép với Bất Lão sơn.","detail":"Bảo cụ tỏa sáng như mặt trời, phát ra khí tức thần linh và gợn sóng kinh khủng, góp phần khiến Tần tộc không dám khai chiến.","uyLuc":"Tạo sức ép đủ khiến Bất Lão sơn phải nhượng bộ trong thế lực lượng lép vế.","dacDiem":"Tỏa sáng như mặt trời và mang khí tức thần linh.","chuHienThoi":"Thạch quốc","capNhatToi":"@c0596","congNang":["Uy hiếp và áp chế lực lượng phòng thủ của Bất Lão sơn."],"chuSoHuu":[{"ten":"Thạch quốc","tuChuong":"@c0596","denChuong":"","cachCoDuoc":"","trangThai":"đang sở hữu"}],"tabs":{"tienTrinh":[{"chuong":"@c0596","loai":"dùng","importance":"normal","giaiDoan":"Uy hiếp Bất Lão sơn","text":"Ba đại Tôn giả của Thạch quốc mang pháp khí cấp Thần tới gây sức ép, khiến Bất Lão sơn không dám khai chiến.","anchor":"Bảo cụ trong tay ba đại Tôn giả cứ như mặt trời phát sáng","phamCap":"Cấp Thần"}]},"nguon":["@c0596"]},{"id":"nua-vien-thanh-duoc","name":"Nửa viên thánh dược","cn":"","aliases":[],"category":"dan-duoc","categoryLabel":"Thánh dược","phamCap":"Thánh dược","soHuu":["Thạch Hạo"],"trangThai":"đã dùng","blurb":"Phần thánh dược được dùng để tạm thời trị liệu thương thế nguy kịch của Thạch Hạo.","detail":"Thánh dược được hòa thành chất lỏng cho Thạch Hạo uống, sau đó một Tôn giả giúp hắn luyện hóa để trị thương.","congNang":["Hỗ trợ luyện hóa và trị liệu thương thế của Thạch Hạo."],"chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c0596","denChuong":"@c0596","cachCoDuoc":"Được đưa cho uống để trị thương.","trangThai":"đã dùng"}],"capNhatToi":"@c0596","tabs":{"tienTrinh":[{"chuong":"@c0596","loai":"dùng","importance":"normal","giaiDoan":"Tạm trị thương","text":"Nửa viên thánh dược được hòa thành chất lỏng cho Thạch Hạo uống và được một Tôn giả hỗ trợ luyện hóa.","anchor":"Tôn giả ra tay giúp nó luyện hóa thánh dược, trị liệu thương thế","phamCap":"Thánh dược"}]},"nguon":["@c0596"]},{"id":"khoi-cot-khac-phap-mon-con-bang","name":"Khối cốt khắc pháp môn Côn Bằng","cn":"","aliases":["Bảo cốt khắc pháp môn Côn Bằng"],"category":"khac","categoryLabel":"Cốt truyền thừa","phanLoaiPhu":"Vật mang truyền thừa","phamCap":"Không rõ","soHuu":["Thạch Hạo"],"trangThai":"Đang được khắc","blurb":"Khối cốt được Thạch Hạo dùng tâm khắc Bảo thuật Côn Bằng khi sinh cơ đã gần cạn. Cậu muốn lưu truyền pháp môn này cho Thạch quốc và Thạch thôn.","detail":"Thạch Hạo bất chấp Chí Tôn cốt đang giải thể để khắc truyền thừa lên khối cốt. Chương chưa xác nhận quá trình khắc đã hoàn tất.","nguonGoc":"Được Thạch Hạo chọn làm vật mang truyền thừa Côn Bằng.","uyLuc":"Có khả năng lưu giữ pháp môn Côn Bằng.","dacDiem":"Được khắc bằng tâm lực trong lúc cơ thể Thạch Hạo suy kiệt nghiêm trọng.","chuHienThoi":"Thạch Hạo","capNhatToi":"@c0597","congNang":["Lưu giữ Bảo thuật Côn Bằng để truyền lại cho Thạch quốc và Thạch thôn."],"chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c0597","denChuong":"","cachCoDuoc":"Dùng làm vật mang để khắc truyền thừa.","trangThai":"Đang khắc"}],"tabs":{"tienTrinh":[{"chuong":"@c0597","loai":"xuất hiện","importance":"normal","giaiDoan":"Khắc truyền thừa","text":"Thạch Hạo dùng tâm khắc pháp môn Côn Bằng lên khối cốt với ý định lưu lại cho Thạch quốc và Thạch thôn.","anchor":"con nghĩ nên lưu lại cho Thạch quốc, cho Thạch thôn pháp môn này","phamCap":"Không rõ"}]},"nguon":["@c0597"]},{"id":"long-huyet-moc","name":"Long Huyết mộc","cn":"","category":"nguyen-lieu","categoryLabel":"Dược liệu","phamCap":"Thần mộc","soHuu":[],"trangThai":"Được đưa tới hoàng cung Thạch Quốc","blurb":"Một khối bảo thụ đỏ sậm từng nhuộm long huyết, được đưa tới để tìm cách cứu chữa Thạch Hạo.","detail":"Long Huyết mộc có thể rang rồi sắc thành thuốc nhằm khai thác tinh hoa long huyết còn lưu lại. Tuy là dược liệu quý, nó vẫn không đủ để hóa giải tình trạng của Thạch Hạo.","nguon":["@c0598"]},{"id":"hac-kim-trung","name":"Hắc Kim trùng","cn":"","category":"nguyen-lieu","categoryLabel":"Dược liệu","phamCap":"Thần trùng trưởng thành","soHuu":[],"trangThai":"Chỉ còn thi thể","blurb":"Thi thể Hắc Kim trùng trưởng thành dài khoảng một thước được tìm thấy trong số cổ vật do người Thạch thôn mang tới.","detail":"Hắc Kim trùng trưởng thành có chiến lực cấp Thần. Thi thể của nó là một vị chủ dược không thể thiếu để luyện Cửu chuyển thần đan, nhưng những nguyên liệu còn lại vẫn không thể tập hợp đầy đủ.","nguon":["@c0598"]},{"id":"qua-ngan-dao","name":"Quả Ngân Đào","cn":"","category":"nguyen-lieu","categoryLabel":"Dược liệu","phamCap":"Chuẩn thánh dược","soHuu":[],"trangThai":"Đã được hái để cứu Thạch Hạo","blurb":"Quả đầu tiên của Ngân Đào thụ tại Thạch thôn được Thạch Phi Giao mang tới để cứu Thạch Hạo.","detail":"Ngân Đào thụ vốn được Thạch Hạo đào từ Bách Đoạn sơn về trồng tại Thạch thôn. Khi cây kết quả, người trong thôn hái chuẩn thánh dược này và cẩn thận đưa tới hoàng cung, nhưng nó không thể đảo ngược thương thế của hắn.","nguon":["@c0598"]},{"id":"than-tuu-con-bang","name":"Thần tửu Côn Bằng","cn":"","aliases":["Thần tửu tổ Côn Bằng"],"category":"dan-duoc","categoryLabel":"Thần tửu","phamCap":"Có đặc tính gần thần dược","soHuu":["Bóng Lông","Tiểu Hồng","Thạch Hạo"],"trangThai":"da-dung","blurb":"Giọt thần tửu cuối cùng lấy từ tổ Côn Bằng được dùng để kéo dài sinh cơ cho Thạch Hạo. Nó giúp Thạch Hạo tỉnh lại tạm thời nhưng không thể hóa giải nguyền rủa Tiên điện.","detail":"Thần tửu khiến toàn thân Thạch Hạo phát sáng và hỗ trợ hồi phục trong thời gian ngắn. Hương rượu đủ mạnh để khiến người có tu vi yếu hôn mê, nhưng dược lực không thể đảo ngược kết cục của Thạch Hạo.","phanLoaiPhu":"Thần tửu","nguonGoc":"Tổ Côn Bằng","uyLuc":"Có dược lực gần với thần dược và có thể tạm thời kéo dài sinh cơ.","dacDiem":"Hương rượu có thể khiến người tu vi yếu hôn mê.","chuHienThoi":"Đã được dùng cho Thạch Hạo","capNhatToi":"@c0600","congNang":["Kéo dài sinh cơ và hỗ trợ cơ thể hồi phục tạm thời.","Giúp Thạch Hạo tỉnh lại trong một khoảng thời gian ngắn."],"chuSoHuu":[{"ten":"Bóng Lông và Tiểu Hồng","tuChuong":"@c0600","denChuong":"@c0600","cachCoDuoc":"Mang giọt rượu cuối cùng lấy từ tổ Côn Bằng tới Thạch thôn.","trangThai":"đã dùng cho Thạch Hạo"},{"ten":"Thạch Hạo","tuChuong":"@c0600","denChuong":"@c0600","cachCoDuoc":"Được Bóng Lông và Tiểu Hồng cho dùng để kéo dài sinh cơ.","trangThai":"đã luyện hóa"}],"tabs":{"tienTrinh":[{"chuong":"@c0600","loai":"dùng","importance":"normal","giaiDoan":"Giọt rượu cuối cùng","text":"Bóng Lông và Tiểu Hồng dùng giọt thần tửu cuối cùng cho Thạch Hạo, giúp nó tỉnh lại tạm thời nhưng không thể hóa giải nguyền rủa.","phamCap":"Có đặc tính gần thần dược","anchor":"Rượu này có đặc tính của thần dược, quả nhiên bất phàm"}]},"nguon":["@c0600"]}]};
